import React, { useEffect, useState } from 'react'
import "../../style/order.css"
import LogoImg from "../../assest/png/logoIcon.png"
import { useNavigate } from 'react-router-dom'
import { Space, Table, Tag, Card, Button, Avatar, Segmented, Pagination, message, Input, Radio, Select } from 'antd';

import {
    LoadingOutlined,
    SearchOutlined
} from '@ant-design/icons';
import { deliveryOptionType, fetchOrderhisotry, fetchStatusCount } from '../../service/api_services';
import { useAuth } from '../../authentication/context/authContext';
import { useScreen } from '../../authentication/context/AuthScreen';
import { getDisplayStatusLabel } from '../../utils/statusDisplay';
import { getSlotDelayColor, getSlotDelayLabel, getSlotDelayRowClassName } from '../../utils/slotDelayDisplay';


function OrderHistory() {
    const { screenWidth } = useScreen();
    const isMobile = screenWidth < 768;
    const { token, logout } = useAuth()
    const navigate = useNavigate()
    const [deliveryOption, setDeliveryopt] = useState("")
    const [orderData, setOrderData] = useState([])
    const [orderStatusData, setOrderStatusData] = useState([])
    const [isLoading, setIsLoading] = useState(false)
    const [totalPage, setTotalPage] = useState(null);
    const [current, setCurrent] = useState(1);
    const [searchInput, setSearchInput] = useState("")
    const [orderStatus, setOrderStatus] = useState(null)
    const capitalize = (str) => str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();

    const getOrderSourceTag = (orderSource) => (
        <Tag color={orderSource === "WEB" ? "geekblue" : "green"}>
            {orderSource || "APP"}
        </Tag>
    );



    const onChange = (page) => {
        setCurrent(page);
        setIsLoading(true);
    };

    const getStatusColor = (status) => {
        switch (status) {
            case 'ASSIGNED':
                return '#EB5B00';
            case 'ORDERPACKED':
                return '#219C90';
            case 'ACCEPTED':
                return '#90D26D';
            case 'DISPATCHED':
                return '#008DDA';
            case 'DELIVERED':
                return '#87A922';
            case 'CANCELLED':
                return '#FF204E';
            case 'CANCELLEDRETURN':
                return '#FF204E';
            case 'CLOSED':
                return '#FF201E';
            default:
                return '#B3A398';
        }
    };
    const columns = [
        {
            title: 'Order Code',
            dataIndex: 'orderCode',
            key: 'orderCode',
            render: (_, { orderCode, _id }) => (
                <div className="order_code">
                    <span>#</span><span><b>{orderCode}</b></span>

                </div>
            ),
            ellipsis: true,
        },
        {
            title: 'Status',
            key: 'status',
            dataIndex: 'status',
            render: (_, { status, _id }) => (
                <>
                    <Tag key={_id} color={getStatusColor(status)}>{getDisplayStatusLabel(status)}</Tag>
                </>
            ),
        },
        {
            title: 'Name',
            dataIndex: 'userInfo',
            key: 'userInfo',

            render: (_, { userInfo }) => (
                <>
                    <span>{userInfo?.fullName}</span>
                </>

            ),
            ellipsis: true,
        },

        {
            title: 'Number',
            dataIndex: 'userInfo',
            key: 'userInfo',
            render: (_, { userInfo }) => (
                <>
                    <span>{userInfo?.mobileNo}</span>
                </>

            ),
        },
        {
            title: 'Branch',
            dataIndex: 'branchAlias',
            key: 'branchAlias',

            ellipsis: true,
        },
        {
            title: 'Order Source',
            dataIndex: 'orderSource',
            key: 'orderSource',
            render: (_, { orderSource }) => getOrderSourceTag(orderSource),
            ellipsis: true,
        },
        {
            title: 'Delivery Date',
            dataIndex: 'deliveryDate',
            key: 'deliveryDate',
            // render: (_, { deliveryDate }) => (

            //     <Tag color="blue">
            //         {branchCode}
            //     </Tag>

            // ),
            ellipsis: true,
        },
        {
            title: 'Delivery Slot',
            dataIndex: 'timeSlotFrom',
            key: 'deliverySlot',
            render: (_, { timeSlotFrom, timeSlotTo }) => (
                <span>{timeSlotFrom && timeSlotTo ? `${timeSlotFrom} - ${timeSlotTo}` : "--"}</span>
            ),
            ellipsis: true,
        },
        {
            title: 'Delay',
            dataIndex: 'slotDelayLabel',
            key: 'slotDelayLabel',
            render: (_, record) => (
                <Tag color={getSlotDelayColor(record?.slotDelayStatus)}>{getSlotDelayLabel(record)}</Tag>
            ),
            ellipsis: true,
        },
        {
            title: 'Delivery Type',
            dataIndex: 'deliveryOption',
            key: 'deliveryOption',
            render: (_, { deliveryOption }) => (

                <Tag color={deliveryOption == "DELIVERY" ? "#7ABA78" : "#387ADF"}>
                    {deliveryOption}
                </Tag>

            ),
            ellipsis: true,
        },
        {
            title: 'No. of Item',
            dataIndex: 'totalItem',
            key: 'totalItem',
            render: (_, { totalItem }) => (
                <span>{totalItem}</span>
            ),
            ellipsis: true,
        },
        {
            title: 'Payment Mode',
            dataIndex: 'paymentMode',
            key: 'paymentMode',
            render: (_, { paymentMode }) => (

                <Tag color={paymentMode != "COD" ? "#7ABA78" : "#F57D1F"}>
                    {paymentMode}
                </Tag>

            ),
            ellipsis: true,
        },

        {
            title: 'Payable Amount',
            dataIndex: 'totalPayableAmount',
            key: 'totalPayableAmount',
            render: (_, { totalPayableAmount }) => (
                <span>₹ {totalPayableAmount?.toFixed(2)}</span>

            ),
            ellipsis: true,
        },


        {
            title: 'Action',
            key: '_id',
            render: (_, { _id }) => (
                <Space size="middle">

                    <Button shape="round" className="view_details"
                        onClick={() => navigate(`/dashboard/order-history-details/${_id}`)}
                    >View </Button>


                </Space>
            ),
            fixed: 'right',
        },
    ];

    const ShowOrderHistoryList = async () => {
        setIsLoading(true)
        try {
            await fetchOrderhisotry(token, current, deliveryOption, orderStatus, searchInput)
                .then((res) => {
                    console.log("order history list", res);
                    if (res.status == 200) {
                        setOrderData(res.data.data.data);
                        setTotalPage(res.data.data.totalPage)
                        setIsLoading(false)
                    } else if (res.data.code == 283) {
                        message.error(res.data.message)
                        logout()

                    }
                })
                .catch((err) => {
                    console.log(err.message);
                    setIsLoading(false)
                });
        } catch (error) {
            console.log(error);
            setIsLoading(false)
        }
    };

    useEffect(() => {
        ShowOrderHistoryList();
    }, [token, current, orderStatus, searchInput, deliveryOption]);

    const showOrderCount = async () => {
        try {
            await fetchStatusCount(token)
                .then((res) => {
                    console.log(" order count ", res);
                    if (res.status == 200) {
                        setOrderStatusData(res.data.data);
                        setIsLoading(true)
                    } else if (res.data.code == 283) {
                        message.error(res.data.message)
                        logout()
                    }
                })
                .catch((err) => {
                    console.log(err);
                });
        } catch (error) {
            console.log(error);
            setIsLoading(true)
        }
    };

    useEffect(() => {
        showOrderCount()
    }, [])

    return (
        <section className="main_Section">
            <div className="content_head">
                <div className="order_content_title">
                    <Card className="card_body">
                        <div className="order_status_titiles">
                            <div className="order_title">
                                <div className="order_img">
                                    <img src={LogoImg} className="logo_icon" />
                                </div>
                                <div className="order_status">
                                    <h4>Order  History</h4>
                                    <p>{orderData?.length}  Orders </p>
                                </div>
                            </div>
                            <div className="order_status_action" style={{ display: 'flex', gap: '8px', alignItems: 'center', flexDirection: isMobile ? 'column' : 'row' }}>
                                <Space>
                                    <Select

                                        allowClear
                                        placeholder="Select Delivery Type "
                                        optionFilterProp="children"
                                        onChange={(value) => setDeliveryopt(value)}
                                        style={{ width: '180px' }}

                                    >
                                        {deliveryOptionType.map((opt) => (
                                            <Select.Option key={opt.key} value={opt.values}>{opt.values}</Select.Option>
                                        ))}
                                    </Select>

                                    <Input placeholder="Search Order" onChange={(e) => setSearchInput(e.target.value)} prefix={<SearchOutlined />} id="seach_ord" size="medium" />
                                </Space>

                                <Button
                                    type="primary"
                                    onClick={() => ShowOrderHistoryList()}
                                    loading={isLoading}
                                    icon={isLoading ? <LoadingOutlined /> : null}
                                    style={{ width: isMobile ? '100%' : 'auto' }}
                                >
                                    Refresh
                                </Button>
                            </div>

                        </div>
                        <div className="status_filter">
                            {orderStatus ? <Button type="link" danger onClick={() => setOrderStatus(null)}>Clear Filter</Button> : null}
                            <Radio.Group value={orderStatus} >
                                {orderStatusData.map((opt) => (
                                    <Radio.Button onClick={() => {
                                        // Toggle the orderStatus value, if the clicked value is already selected, set to null
                                        setOrderStatus((prevValue) => (prevValue === opt._id ? null : opt._id));
                                    }} key={opt._id} value={opt._id}>{getDisplayStatusLabel(opt._id, capitalize(opt._id))} ({opt.count})</Radio.Button>
                                ))}
                            </Radio.Group>
                        </div>
                    </Card>
                </div>


            </div>
            <div className="partner_content" style={{ border: '1px solid #f0f0f0', borderRadius: '8px' }}>
                {isLoading ? <div className="loader_main"> <span class="loader2"></span></div> :
                    <Table columns={columns} dataSource={orderData} scroll={{ x: true }}
                        rowClassName={(record) => getSlotDelayRowClassName(record)}
                        pagination={false}
                        footer={() => <div className="pagination">
                            <Pagination current={current} onChange={onChange} total={totalPage * 10} />
                        </div>}

                    />}

            </div>
        </section>
    )
}


export default OrderHistory
