

import React, { useEffect, useState } from 'react';
import { Alert, Button, Card, Divider, message, Modal, Radio, Segmented, Skeleton, Space } from 'antd';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuth } from '../../authentication/context/authContext';
import { fetchPartialRemoveReview, fetchReviewPartialReturn, PartialReturnAction, PartialReturnItem } from '../../service/api_services';
import "../../style/order.css"
import { useSelector } from 'react-redux';
import { selectCartItems } from '../../redux-toolkit/CartSlice';


const RemoveItemDetails = ({ isRemove, ShowOrderList, open, setOpen, setIsRemove }) => {
    const { token } = useAuth();
    const navigate = useNavigate()
    const { id } = useParams()
    const [isReviewLoad, setIsReviewLoad] = useState(false)
    const [returnType, setReturnType] = useState("BRANCH");
    const [removeReview, setRemoveReview] = useState([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isRemoveLoder, setIsRemoveLoder] = useState(false)
    const [paymentOpt, setPaymentOpt] = useState(null);


    const cartItem = useSelector(selectCartItems);

    // Helper function to parse offer pattern (e.g., "1+1", "2+1", "4+1", "1+2")
    const parseOfferPattern = (offerQtyStr) => {
        if (!offerQtyStr || typeof offerQtyStr !== 'string') return null;
        const parts = offerQtyStr.split('+');
        if (parts.length !== 2) return null;
        const billing = parseInt(parts[0], 10);
        const free = parseInt(parts[1], 10);
        if (isNaN(billing) || isNaN(free)) return null;
        return { billingPerCombo: billing, freePerCombo: free, comboSize: billing + free };
    };

    // Calculate billing quantity for offer products
    const getBillingQuantity = (product) => {
        const totalQty = product.unit || 0;
        const offerPattern = product.offerQty ? parseOfferPattern(product.offerQty) : null;

        if (offerPattern) {
            // Calculate number of complete combos
            const numCombos = Math.floor(totalQty / offerPattern.comboSize);
            // Return only billing quantity (not including free items)
            return numCombos * offerPattern.billingPerCombo;
        }

        // For non-offer products, return total quantity
        return totalQty;
    };

    const oldItemData = removeReview?.oldPaymentDetails
    const newItemData = removeReview?.newPaymentDetails


    const reviewRetuenItem = cartItem?.map((product) => {
        console.log("product", product);
        return {
            productCode: product.productCode,
            quantity: getBillingQuantity(product), // Use billing quantity instead of total
            _id: product?._id
        };
    }, []);
    console.log("reviewRetuenItem", reviewRetuenItem)

    const returnReviewBody = {
        userOrderId: id,
        removedBy: returnType,
        cart: reviewRetuenItem
    }


    const removeProductReview = async () => {
        setIsReviewLoad(true)
        try {
            await fetchReviewPartialReturn(token, returnReviewBody)
                .then((res) => {
                    console.log("remove review", res);
                    if (res.status == 200) {
                        setIsLoading(true)
                        setRemoveReview(res.data.data)
                        setIsReviewLoad(false)
                    }
                    if (res.status == 202) {
                        message.error(res.data.message)
                        setOpen(false)

                    }
                })
                .catch((err) => {
                    console.log(err.message);
                    setIsReviewLoad(false)
                });
        } catch (error) {
            console.log(error);
            setIsReviewLoad(false)
        }
    };

    useEffect(() => {
        if (open) {
            removeProductReview();
            setIsRemoveLoder(false);
        }
    }, [open, returnType]);

    const onChange = (e) => {
        setPaymentOpt(e.target.value);
    };

    const removeOrderHandler = async () => {
        setIsRemoveLoder(true);

        if (newItemData?.balanceAmount > 0 && newItemData?.
            paymentMode
            ===
            "ONLINE" && !paymentOpt) {
            message.error("Please Select Repayement Method");
            setIsRemoveLoder(false);
            return;
        }

        const body = {
            userOrderId: id,
            removedBy: returnType,
            cart: reviewRetuenItem,
            rePaymentMode: newItemData?.paymentMode === "ONLINE" ? paymentOpt || "" : ""
        };

        try {
            console.log("Sending request with body:", body); // Debugging log
            setIsRemoveLoder(false);
            return;
            const res = await PartialReturnAction(token, body);
            console.log("API Response:", res); // Debugging log

            if (res && res.status === 201) {
                message.success(res.data.message);
                ShowOrderList();
                setOpen(false)
                setIsRemove(false);
            } else {
                message.error(res?.message);
            }
        } catch (error) {
            message.error(error?.message);
        } finally {
            setIsRemoveLoder(false);
        }
    };


    // const removeOrderHandler = async () => {
    //     setIsRemoveLoder(true)
    //     if (newItemData?.balanceAmount > 0 && !paymentOpt) {
    //         message.error("Please Select Repayement Method")
    //         setIsRemoveLoder(false)
    //         return
    //     }
    //     const body = {
    //         userOrderId: id,
    //         removedBy: returnType,
    //         cart: returnReviewBody,
    //         rePaymentMode: paymentOpt || ""
    //     };
    //     try {
    //         await PartialReturnAction(token, body)
    //             .then((res) => {
    //                 if (res.status === 201) {
    //                     message.success(res.data.message);
    //                     ShowOrderList();
    //                     setIsModalOpen(false);
    //                     setIsRemoveLoder(false)
    //                 }
    //             }).catch((err) => {
    //                 console.log(err);
    //                 setIsRemoveLoder(false)
    //             });
    //     } catch (error) {
    //         console.log(error);
    //         setIsRemoveLoder(false)

    //     }

    // };

    const handleRemoveType = (value) => {
        setReturnType(value)
        console.log(value)

    }

    return (
        <>
            {/* <Button type="primary" onClick={showModal} danger disabled={!isRemove}> Edit order</Button> */}

            <Modal
                style={{ top: 20 }}
                loading={isLoading}
                footer={false} title="Review of Partial Return Payment Calculation"
                open={open}
                onCancel={() => setOpen(false)}
            >
                <div className="show_data">
                    <Segmented block options={["BRANCH", "USER"]} onChange={handleRemoveType} />
                    <Divider>Before Remove Item</Divider>
                    {isReviewLoad ? <Skeleton active /> :
                        <>
                            <Alert banner showIcon={false} type="info" message={<div className="saved_item">
                                <p>Total Save Amount</p>
                                <p>₹{oldItemData?.totalSaving?.toFixed(2)}</p>
                            </div>} />
                            <Alert showIcon={false} type="error" message={
                                <>
                                    <div className="calculat_item">
                                        <p> Total MRP Amount</p>
                                        <p>₹{oldItemData
                                            ?.mrpTotalProductAmount}</p>
                                    </div>
                                    <div className="calculat_item">
                                        <p> Total Amount</p>
                                        <p>₹{oldItemData
                                            ?.totalProductAmount}</p>
                                    </div>
                                    <div className="calculat_item">
                                        <p>Discount Amount</p>
                                        <p>₹{oldItemData
                                            ?.discountAmount}</p>
                                    </div>
                                    <div className="calculat_item">
                                        <p>Delivery Charge</p>
                                        <p>₹{oldItemData
                                            ?.deliveryCharge}</p>
                                    </div>

                                    <div className="calculat_item total_amt">
                                        <p>Total Payable Amount</p>
                                        <p>₹{oldItemData
                                            ?.totalPayableAmount}</p>
                                    </div>

                                </>
                            } banner />

                            <Divider>After Remove Item</Divider>
                            <Alert banner showIcon={false} type="info" message={<div className="saved_item">
                                <p>Total Save Amount</p>
                                <p>₹{newItemData?.totalSaving?.toFixed(2)}</p>
                            </div>} />
                            <Alert showIcon={false} type="success" message={
                                <>
                                    <div className="calculat_item">
                                        <p>Total MRP Amount</p>
                                        <p>₹{newItemData?.mrpTotalProductAmount}</p>
                                    </div>
                                    <div className="calculat_item">
                                        <p> Total Amount</p>
                                        <p>₹{newItemData?.totalProductAmount}</p>
                                    </div>

                                    <div className="calculat_item">
                                        <p>Discount Amount</p>
                                        <p>₹{newItemData?.discountAmount}</p>
                                    </div>
                                    <div className="calculat_item">
                                        <p>Delivery Charge</p>
                                        <p>₹{newItemData?.deliveryCharge}</p>
                                    </div>
                                    <div className="calculat_item total_amt">
                                        <p>Total Payable Amount</p>
                                        <p>₹{newItemData?.totalPayableAmount}</p>
                                    </div>


                                </>
                            } banner />
                            {newItemData?.paymentMode === "ONLINE" ? newItemData?.balanceAmount > 0 ? <>
                                <Alert type="error" banner showIcon={false} message={<div className="saved_item">
                                    <p>Repayment Amount</p>
                                    <strong>₹{newItemData?.reTotalPayableAmount}</strong>
                                </div>} />
                                <div className="show_payment_type">
                                    <Card title="Choose Repayment Method" bordered={false}>
                                        <Radio.Group
                                            onChange={onChange}
                                            value={paymentOpt}
                                            options={[
                                                {
                                                    value: "ONLINE",
                                                    label: 'Online',
                                                },
                                                {
                                                    value: "COD",
                                                    label: 'Cash on delivery',
                                                },


                                            ]}
                                        />
                                    </Card>
                                </div>
                            </> : newItemData?.balanceAmount < 0 ? <Alert showIcon={false} banner type="info" message={<div className="saved_item">
                                <p>Refund Amount</p>
                                <strong>₹{newItemData?.totalReturnableAmount}</strong>
                            </div>} /> :
                                <Alert banner showIcon={false} type="success" message={<div className="saved_item">
                                    <p>Neither repay nor refund</p>
                                    {/* <p>₹{removeReview?.newPaymentDetails?.totalReturnableAmount}</p> */}
                                </div>} /> : null}



                            <div className="remove_item_btn">
                                <Divider dashed />
                                <Button
                                    loading={isRemoveLoder}
                                    onClick={removeOrderHandler}
                                >Submit</Button>

                            </div>
                        </>
                    }
                </div>
            </Modal>
        </>
    );
};

export default RemoveItemDetails;
