import React, { useCallback, useEffect, useState } from "react";
import {
  Breadcrumb,
  Button,
  Card,
  Input,
  InputNumber,
  Modal,
  QRCode,
  Select,
  Table,
  Tag,
  Typography,
  message,
} from "antd";
import {
  DownOutlined,
  ReloadOutlined,
  SearchOutlined,
  UpOutlined,
} from "@ant-design/icons";
import moment from "moment";
import { useAuth } from "../../authentication/context/authContext";
import {
  acceptVendorCashCollectionLedger,
  createVendorCashCollectionLedger,
  fetchVendorCashCollectionLedger,
  fetchVendorCashCollectionSummary,
  fetchVendorCashCollectionVendors,
  rejectVendorCashCollectionLedger,
} from "../../service/api_services";
import "../../style/riderCashCollection.css";

const paymentTypeOptions = [
  { label: "All Payment Type", value: "ALL" },
  { label: "Partly", value: "PARTLY" },
  { label: "Fully Payment", value: "FULLY PAYMENT" },
];

const requestStatusOptions = [
  { label: "All Payment Status", value: "ALL" },
  { label: "Process", value: "PROCESS" },
  { label: "Completed", value: "COMPLETED" },
  { label: "Rejected", value: "REJECTED" },
];

const cashCollectionUpiId = process.env.REACT_APP_CASH_COLLECTION_UPI_ID || "onbkd@upi";
const cashCollectionUpiName = process.env.REACT_APP_CASH_COLLECTION_UPI_NAME || "BKDgo Cash Collection";
const CASH_COLLECTION_PAGE_SIZE = 10;

const formatCurrency = (value) => {
  const amount = Number(value || 0);
  return `Rs. ${amount.toLocaleString("en-IN", {
    minimumFractionDigits: amount % 1 === 0 ? 0 : 2,
    maximumFractionDigits: 2,
  })}`;
};

const formatRequestType = (value) => {
  if (value === "FULLY PAYMENT") {
    return "Fully Payment";
  }

  if (value === "PARTLY") {
    return "Partly";
  }

  return value || "N/A";
};

const getCollectionModeLabel = (value) => {
  if (value === "UPI") {
    return "UPI";
  }

  if (value === "SECURITY_PAYOUT") {
    return "Security/Payout";
  }

  return "Cash";
};

const formatDateTime = (value) => (value ? moment(value).format("DD-MM-YY, hh:mm A") : "N/A");

const requestStatusConfig = {
  PROCESS: {
    label: "Process",
    color: "gold",
  },
  COMPLETED: {
    label: "Completed",
    color: "green",
  },
  REJECTED: {
    label: "Rejected",
    color: "red",
  },
};

function RiderCashCollection() {
  const { token, logout } = useAuth();

  const [ledgerData, setLedgerData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [current, setCurrent] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const [pageSize, setPageSize] = useState(CASH_COLLECTION_PAGE_SIZE);
  const [searchInput, setSearchInput] = useState("");
  const [paymentType, setPaymentType] = useState("ALL");
  const [requestStatus, setRequestStatus] = useState("ALL");
  const [totalOutstanding, setTotalOutstanding] = useState(0);
  const [vendorOptions, setVendorOptions] = useState([]);
  const [vendorOptionsLoading, setVendorOptionsLoading] = useState(false);
  const [riderSearchInput, setRiderSearchInput] = useState("");
  const [selectedVendorId, setSelectedVendorId] = useState(null);
  const [isVendorListExpanded, setIsVendorListExpanded] = useState(false);
  const [collectedAmount, setCollectedAmount] = useState(null);
  const [creatingEntry, setCreatingEntry] = useState(false);
  const [acceptingLedgerId, setAcceptingLedgerId] = useState(null);
  const [rejectingLedgerId, setRejectingLedgerId] = useState(null);
  const [isUpiModalOpen, setIsUpiModalOpen] = useState(false);

  const normalizedRiderSearch = riderSearchInput.trim().toLowerCase();
  const filteredVendorOptions = vendorOptions.filter((item) => {
    if (!normalizedRiderSearch) {
      return true;
    }

    return [item.fullName, item.mobileNo]
      .filter(Boolean)
      .some((value) => value.toLowerCase().includes(normalizedRiderSearch));
  });

  const selectedVendor = vendorOptions.find((item) => item._id === selectedVendorId) || null;
  const selectedVendorOutstanding = Number(selectedVendor?.currentOutstanding || 0);
  const hasSelectedVendorOutstanding = selectedVendorOutstanding > 0;
  const enteredAmount = Number(collectedAmount || 0);
  const shouldShowVendorList = isVendorListExpanded || !selectedVendor || Boolean(normalizedRiderSearch);
  const requestTypePreview = enteredAmount > 0 && selectedVendorOutstanding > 0
    ? enteredAmount < selectedVendorOutstanding
      ? "Partly"
      : "Fully Payment"
    : "N/A";
  const remainingAmountPreview = Math.max(selectedVendorOutstanding - enteredAmount, 0);
  const upiPaymentLink = `upi://pay?pa=${encodeURIComponent(cashCollectionUpiId)}&pn=${encodeURIComponent(cashCollectionUpiName)}&am=${enteredAmount.toFixed(2)}&cu=INR&tn=${encodeURIComponent(`COD collection ${selectedVendor?.fullName || ""}`.trim())}`;

  const loadLedgerData = useCallback(async () => {
    setIsLoading(true);

    try {
      const [ledgerResponse, summaryResponse] = await Promise.all([
        fetchVendorCashCollectionLedger(
          token,
          current,
          searchInput,
          paymentType === "ALL" ? "" : paymentType,
          requestStatus === "ALL" ? "" : requestStatus
        ),
        fetchVendorCashCollectionSummary(token),
      ]);

      if (ledgerResponse.status === 200) {
        setLedgerData(ledgerResponse?.data?.data?.data || []);
        setTotalCount(ledgerResponse?.data?.data?.totalCount || 0);
        setPageSize(ledgerResponse?.data?.data?.itemsPerPage || CASH_COLLECTION_PAGE_SIZE);
        const nextCurrentPage = ledgerResponse?.data?.data?.currentPage || 1;

        if (nextCurrentPage !== current) {
          setCurrent(nextCurrentPage);
        }
      }

      if (summaryResponse.status === 200) {
        setTotalOutstanding(summaryResponse?.data?.data?.totalOutstanding || 0);
      }
    } catch (error) {
      console.log(error);
      message.error(error?.response?.data?.message || "Failed to load cash collection ledger");
      if (error?.response?.status === 283) {
        logout();
      }
    } finally {
      setIsLoading(false);
    }
  }, [current, logout, paymentType, requestStatus, searchInput, token]);

  const loadVendorOptions = useCallback(async () => {
    setVendorOptionsLoading(true);

    try {
      const response = await fetchVendorCashCollectionVendors(token);

      if (response.status === 200) {
        const riderOutstandingList = [...(response?.data?.data || [])].sort(
          (firstItem, secondItem) =>
            Number(secondItem?.currentOutstanding || 0) - Number(firstItem?.currentOutstanding || 0)
        );

        setVendorOptions(riderOutstandingList);
      }
    } catch (error) {
      console.log(error);
      message.error(error?.response?.data?.message || "Failed to load delivery riders");
      if (error?.response?.status === 283) {
        logout();
      }
    } finally {
      setVendorOptionsLoading(false);
    }
  }, [logout, token]);

  useEffect(() => {
    if (token) {
      loadLedgerData();
    }
  }, [loadLedgerData, token]);

  useEffect(() => {
    if (token) {
      loadVendorOptions();
    }
  }, [loadVendorOptions, token]);

  useEffect(() => {
    if (!vendorOptions.length) {
      setSelectedVendorId(null);
      return;
    }

    const selectedVendorAvailable = vendorOptions.some((item) => item._id === selectedVendorId);

    if (!selectedVendorAvailable) {
      const nextVendor = vendorOptions.find(
        (item) => Number(item.currentOutstanding || 0) > 0 && !item.hasOpenRequest
      )
        || vendorOptions.find((item) => Number(item.currentOutstanding || 0) > 0)
        || vendorOptions.find((item) => !item.hasOpenRequest)
        || vendorOptions[0];
      setSelectedVendorId(nextVendor?._id || null);
    }
  }, [selectedVendorId, vendorOptions]);

  useEffect(() => {
    setCollectedAmount(null);
  }, [selectedVendorId]);

  useEffect(() => {
    if (normalizedRiderSearch) {
      setIsVendorListExpanded(true);
    }
  }, [normalizedRiderSearch]);

  const handleRefreshOutstanding = useCallback(async () => {
    await Promise.all([loadVendorOptions(), loadLedgerData()]);
  }, [loadLedgerData, loadVendorOptions]);

  const handleToggleVendorList = useCallback(() => {
    if (shouldShowVendorList) {
      setRiderSearchInput("");
      setIsVendorListExpanded(false);
      return;
    }

    setIsVendorListExpanded(true);
  }, [shouldShowVendorList]);

  const handleSelectVendor = useCallback((vendorId) => {
    setSelectedVendorId(vendorId);
    setRiderSearchInput("");
    setIsVendorListExpanded(false);
  }, []);

  const validateCollectionInput = () => {
    if (!selectedVendor?._id) {
      message.info("Please select a delivery rider from the outstanding list");
      return false;
    }

    if (selectedVendor.hasOpenRequest) {
      message.info("A process cash collection entry already exists for this delivery rider");
      return false;
    }

    if (!hasSelectedVendorOutstanding) {
      message.info("No outstanding COD is available for this delivery rider right now");
      return false;
    }

    if (!enteredAmount || enteredAmount <= 0) {
      message.info("Please enter COD received amount");
      return false;
    }

    if (enteredAmount > selectedVendorOutstanding) {
      message.info("Collected amount should not exceed delivery rider outstanding COD");
      return false;
    }

    return true;
  };

  const submitLedgerEntry = async (collectionMode = "CASH") => {
    setCreatingEntry(true);

    try {
      const response = await createVendorCashCollectionLedger(
        {
          vendorId: selectedVendor._id,
          amountRequested: enteredAmount,
          collectionMode,
        },
        token
      );

      if (response.status === 201) {
        message.success(response?.data?.message || "Cash collection entry created successfully");
        setCollectedAmount(null);
        setCurrent(1);
        await Promise.all([loadLedgerData(), loadVendorOptions()]);
        return;
      }

      message.info(response?.data?.message || "Unable to create cash collection entry");
    } catch (error) {
      console.log(error);
      message.error(error?.response?.data?.message || "Failed to create cash collection entry");
    } finally {
      setCreatingEntry(false);
    }
  };

  const handleCreateLedgerEntry = () => {
    if (!validateCollectionInput()) {
      return;
    }

    Modal.confirm({
      title: "Confirm cash collection",
      content: `Are you sure you want to collect ${formatCurrency(enteredAmount)} from ${selectedVendor.fullName || "this delivery rider"}?`,
      okText: "Yes, collect",
      cancelText: "No",
      centered: true,
      onOk: () => submitLedgerEntry("CASH"),
    });
  };

  const handleOpenUpiPayment = () => {
    if (!validateCollectionInput()) {
      return;
    }

    setIsUpiModalOpen(true);
  };

  const handleConfirmUpiPayment = async () => {
    await submitLedgerEntry("UPI");
    setIsUpiModalOpen(false);
  };

  const handleAcceptLedger = async (ledgerId) => {
    setAcceptingLedgerId(ledgerId);

    try {
      const response = await acceptVendorCashCollectionLedger(ledgerId, token);

      if (response.status === 200) {
        message.success(response?.data?.message || "Cash collection entry accepted successfully");
        await Promise.all([loadLedgerData(), loadVendorOptions()]);
      }
    } catch (error) {
      console.log(error);
      message.error(error?.response?.data?.message || "Failed to accept cash collection entry");
    } finally {
      setAcceptingLedgerId(null);
    }
  };

  const handleRejectLedger = (ledgerId, riderName) => {
    Modal.confirm({
      title: "Reject cash collection request",
      content: `Are you sure you want to reject this cash collection request${riderName ? ` for ${riderName}` : ""}?`,
      okText: "Reject",
      okButtonProps: { danger: true },
      cancelText: "Cancel",
      centered: true,
      onOk: async () => {
        setRejectingLedgerId(ledgerId);

        try {
          const response = await rejectVendorCashCollectionLedger(ledgerId, token);

          if (response.status === 200) {
            message.success(response?.data?.message || "Cash collection entry rejected successfully");
            await Promise.all([loadLedgerData(), loadVendorOptions()]);
          }
        } catch (error) {
          console.log(error);
          message.error(error?.response?.data?.message || "Failed to reject cash collection entry");
        } finally {
          setRejectingLedgerId(null);
        }
      },
    });
  };

  const columns = [
    {
      title: "Date",
      dataIndex: "addedDate",
      key: "addedDate",
      width: 110,
      render: (value) => (value ? moment(value).format("DD-MM-YY") : "N/A"),
    },
    {
      title: "Delivery Rider Name",
      dataIndex: "riderName",
      key: "riderName",
      width: 210,
      render: (_, record) => (
        <div className="cash-ledger-rider-cell">
          <div className="cash-ledger-rider-name">{record.riderName || "N/A"}</div>
          <div className="cash-ledger-rider-mobile">{record.riderMobileNo || "N/A"}</div>
        </div>
      ),
    },
    {
      title: "Transaction ID",
      dataIndex: "transactionId",
      key: "transactionId",
      width: 170,
      render: (value) => (value ? `#${value}` : "N/A"),
    },
    {
      title: "Request Type",
      dataIndex: "requestType",
      key: "requestType",
      width: 140,
      render: (value) => formatRequestType(value),
    },
    {
      title: "Total COD",
      dataIndex: "totalCodAmount",
      key: "totalCodAmount",
      width: 130,
      render: (value) => formatCurrency(value),
    },
    {
      title: "Balance COD",
      dataIndex: "balanceCodAmount",
      key: "balanceCodAmount",
      width: 130,
      render: (value) => formatCurrency(value),
    },
    {
      title: "Amount Request",
      dataIndex: "amountRequested",
      key: "amountRequested",
      width: 150,
      render: (value) => (
        <span className="cash-ledger-amount-pill">{formatCurrency(value)}</span>
      ),
    },
    {
      title: "Mode",
      dataIndex: "collectionMode",
      key: "collectionMode",
      width: 110,
      render: (value) => (
        <Tag
          className="cash-ledger-mode-tag"
          color={value === "UPI" ? "blue" : value === "SECURITY_PAYOUT" ? "purple" : "green"}
        >
          {getCollectionModeLabel(value)}
        </Tag>
      ),
    },
    {
      title: "Request Status",
      dataIndex: "requestStatus",
      key: "requestStatus",
      width: 150,
      render: (value) => {
        const statusConfig = requestStatusConfig[value] || requestStatusConfig.PROCESS;

        return (
          <Tag
            className="cash-ledger-status-tag"
            color={statusConfig.color}
          >
            {statusConfig.label}
          </Tag>
        );
      },
    },
    {
      title: "Collection Date & Time",
      dataIndex: "collectedAt",
      key: "collectedAt",
      width: 185,
      render: (value) => formatDateTime(value),
    },
    {
      title: "Collected By",
      dataIndex: "collectedByName",
      key: "collectedByName",
      width: 160,
      render: (value) => value || "N/A",
    },
    {
      title: "Action",
      key: "action",
      width: 210,
      fixed: "right",
      render: (_, record) =>
        record.requestStatus === "PROCESS" ? (
          <div className="cash-ledger-action-group">
            <Button
              type="primary"
              shape="round"
              loading={acceptingLedgerId === record._id}
              disabled={rejectingLedgerId === record._id}
              onClick={() => handleAcceptLedger(record._id)}
            >
              Approve
            </Button>
            <Button
              danger
              shape="round"
              loading={rejectingLedgerId === record._id}
              disabled={acceptingLedgerId === record._id}
              onClick={() => handleRejectLedger(record._id, record.riderName)}
            >
              Reject
            </Button>
          </div>
        ) : (
          <span className="cash-ledger-action-placeholder">-</span>
        ),
    },
  ];

  return (
    <section className="cash-ledger-page">
      <div className="cash-ledger-header">
        <div>
          <Breadcrumb
            items={[
              { title: "Branch" },
              { title: "Collect Outstanding" },
            ]}
          />
          <Typography.Title level={4} className="cash-ledger-title">
            Collect Outstanding
          </Typography.Title>
          <Typography.Text className="cash-ledger-subtitle">
            {moment().format("hh:mm a  DD-MMM-YYYY")}
          </Typography.Text>
        </div>
      </div>

      <div className="cash-ledger-layout">
        <div className="cash-ledger-main">
          <Card className="cash-ledger-filter-card">
            <div className="cash-ledger-filter-row">
              <Input
                allowClear
                prefix={<SearchOutlined />}
                placeholder="Search by txn id, delivery rider, mobile, amount..."
                value={searchInput}
                onChange={(event) => {
                  setCurrent(1);
                  setSearchInput(event.target.value);
                }}
                className="cash-ledger-search"
              />

              <Select
                value={paymentType}
                options={paymentTypeOptions}
                onChange={(value) => {
                  setCurrent(1);
                  setPaymentType(value);
                }}
                className="cash-ledger-filter-select"
              />

              <Select
                value={requestStatus}
                options={requestStatusOptions}
                onChange={(value) => {
                  setCurrent(1);
                  setRequestStatus(value);
                }}
                className="cash-ledger-filter-select"
              />

            </div>
          </Card>

          <Card className="cash-ledger-table-card">
            <Table
              rowKey={(record) => record._id}
              loading={isLoading}
              columns={columns}
              dataSource={ledgerData}
              pagination={{
                current,
                pageSize,
                total: totalCount,
                showSizeChanger: false,
                onChange: (page) => setCurrent(page),
              }}
              scroll={{ x: 1900 }}
              rowClassName={(record) =>
                record.requestStatus === "COMPLETED"
                  ? "cash-ledger-row-completed"
                  : record.requestStatus === "REJECTED"
                    ? "cash-ledger-row-rejected"
                    : "cash-ledger-row-process"
              }
              locale={{
                emptyText: "No cash collection ledger entries found",
              }}
            />
          </Card>
        </div>

        <div className="cash-ledger-sidebar">
          <Card
            className="cash-ledger-side-card"
                    title="Delivery Rider Wise COD Outstanding"
            extra={(
              <Button
                type="text"
                icon={<ReloadOutlined />}
                onClick={handleRefreshOutstanding}
                loading={vendorOptionsLoading}
              />
            )}
          >
            <div className="cash-ledger-outstanding-overview">
              <span>Total Outstanding</span>
              <strong>{formatCurrency(totalOutstanding)}</strong>
            </div>

            {selectedVendor ? (
              <div className="cash-ledger-selected-rider-strip">
                <div className="cash-ledger-selected-rider-info">
                            <span className="cash-ledger-side-label">Selected Delivery Rider</span>
                  <strong>{selectedVendor.fullName || "N/A"}</strong>
                  <span className="cash-ledger-side-subtitle">
                    {selectedVendor.mobileNo || "N/A"}
                  </span>
                </div>

                <div className="cash-ledger-selected-rider-action">
                  <strong>{formatCurrency(selectedVendorOutstanding)}</strong>
                  <Button
                    type="default"
                    size="small"
                    icon={shouldShowVendorList ? <UpOutlined /> : <DownOutlined />}
                    onClick={handleToggleVendorList}
                  >
                          {shouldShowVendorList ? "Hide delivery riders" : "Change delivery rider"}
                  </Button>
                </div>
              </div>
            ) : null}

            {shouldShowVendorList ? (
              <>
                <Input
                  allowClear
                  value={riderSearchInput}
                  onChange={(event) => setRiderSearchInput(event.target.value)}
                  prefix={<SearchOutlined />}
                          placeholder="Search delivery rider by name or mobile"
                  className="cash-ledger-side-search"
                />

                <div className="cash-ledger-side-count">
                        Showing {filteredVendorOptions.length} branch delivery rider
                  {filteredVendorOptions.length === 1 ? "" : "s"}
                </div>

            <div className="cash-ledger-vendor-list">
              {filteredVendorOptions.length ? (
                filteredVendorOptions.map((item) => (
                  <button
                    key={item._id}
                    type="button"
                    className={`cash-ledger-vendor-item ${
                      selectedVendorId === item._id ? "is-active" : ""
                    }`}
                    onClick={() => handleSelectVendor(item._id)}
                  >
                    <div className="cash-ledger-vendor-item-info">
                      <span className="cash-ledger-vendor-item-name">
                        {item.fullName || "N/A"}
                      </span>
                      <span className="cash-ledger-vendor-item-meta">
                        {item.mobileNo || "N/A"}
                        {item.hasOpenRequest ? " - Pending request" : ""}
                      </span>
                    </div>
                    <strong>{formatCurrency(item.currentOutstanding)}</strong>
                  </button>
                ))
              ) : (
                <div className="cash-ledger-empty-side">
                  {vendorOptions.length
                                ? "No delivery riders match this search."
                                : "No delivery riders are associated with this branch right now."}
                </div>
              )}
            </div>
              </>
            ) : null}
          </Card>

          <Card className="cash-ledger-side-card cash-ledger-collect-card" title="Collect Cash">
            {selectedVendor ? (
              <>
                <div className="cash-ledger-selected-summary">
                  <div className="cash-ledger-selected-user">
                        <span className="cash-ledger-side-label">Selected Delivery Rider</span>
                    <strong>{selectedVendor.fullName || "N/A"}</strong>
                    <span className="cash-ledger-side-subtitle">
                      {selectedVendor.mobileNo || "N/A"}
                    </span>
                  </div>

                  <div className="cash-ledger-selected-outstanding">
                    <span>Outstanding</span>
                    <strong>{formatCurrency(selectedVendorOutstanding)}</strong>
                  </div>
                </div>

                <InputNumber
                  value={collectedAmount}
                  onChange={(value) => setCollectedAmount(value)}
                  min={1}
                  max={selectedVendorOutstanding || undefined}
                  precision={2}
                  placeholder="Enter COD received amount"
                  className="cash-ledger-collect-input"
                  disabled={selectedVendor.hasOpenRequest || !hasSelectedVendorOutstanding}
                  style={{ width: "100%" }}
                />

                <div className="cash-ledger-collect-meta">
                  <div className="cash-ledger-collect-meta-item">
                    <span>Request Type</span>
                    <strong>{requestTypePreview}</strong>
                  </div>

                  <div className="cash-ledger-collect-meta-item">
                    <span>Remaining</span>
                    <strong>{formatCurrency(remainingAmountPreview)}</strong>
                  </div>
                </div>

                {selectedVendor.hasOpenRequest ? (
                  <Typography.Text className="cash-ledger-side-warning">
                              A process cash collection entry already exists for this delivery rider. Please accept
                    it from the ledger first.
                  </Typography.Text>
                ) : !hasSelectedVendorOutstanding ? (
                  <Typography.Text className="cash-ledger-side-warning">
                            No COD outstanding is available for this delivery rider yet.
                  </Typography.Text>
                ) : null}

                <div className="cash-ledger-payment-actions">
                  <Button
                    type="primary"
                    className="cash-ledger-collect-button"
                    loading={creatingEntry}
                    onClick={handleCreateLedgerEntry}
                    disabled={
                      selectedVendor.hasOpenRequest ||
                      !hasSelectedVendorOutstanding ||
                      !enteredAmount ||
                      enteredAmount > selectedVendorOutstanding
                    }
                  >
                    {enteredAmount ? `Collect Cash ${formatCurrency(enteredAmount)}` : "Collect Cash"}
                  </Button>
                  <Button
                    className="cash-ledger-upi-button"
                    onClick={handleOpenUpiPayment}
                    disabled={
                      selectedVendor.hasOpenRequest ||
                      !hasSelectedVendorOutstanding ||
                      !enteredAmount ||
                      enteredAmount > selectedVendorOutstanding
                    }
                  >
                    Pay Online
                  </Button>
                </div>
              </>
            ) : (
              <div className="cash-ledger-empty-side">
                      Select a delivery rider from the outstanding list to start cash collection.
              </div>
            )}
          </Card>
        </div>
      </div>

      <Modal
        title="Pay Online via UPI"
        open={isUpiModalOpen}
        onCancel={() => setIsUpiModalOpen(false)}
        footer={[
          <Button key="cancel" onClick={() => setIsUpiModalOpen(false)}>
            Cancel
          </Button>,
          <Button
            key="received"
            type="primary"
            loading={creatingEntry}
            onClick={handleConfirmUpiPayment}
          >
            Payment Received
          </Button>,
        ]}
        centered
      >
        <div className="cash-ledger-upi-modal">
          <QRCode value={upiPaymentLink} size={220} />
          <div className="cash-ledger-upi-details">
                    <Typography.Text className="cash-ledger-side-label">Delivery Rider</Typography.Text>
            <strong>{selectedVendor?.fullName || "N/A"}</strong>
            <Typography.Text className="cash-ledger-side-subtitle">
              {selectedVendor?.mobileNo || "N/A"}
            </Typography.Text>
            <div className="cash-ledger-upi-amount">
              {formatCurrency(enteredAmount)}
            </div>
            <Typography.Text className="cash-ledger-side-warning">
              Gateway is not connected yet. Mark payment received only after confirming the UPI payment manually.
            </Typography.Text>
          </div>
        </div>
      </Modal>
    </section>
  );
}

export default RiderCashCollection;
