import React, { useEffect, useRef, useState } from 'react';
import { Button, Form, Input, message, Modal, notification, Popconfirm } from 'antd';
import { useNavigate, useParams } from 'react-router-dom';
import { PickupOrderOtpVerify, ReturnReplaceBranchAccept } from '../../service/api_services';
import OtpInput from "react-otp-input";
import { useAuth } from '../../authentication/context/authContext';


const CollectPayment = ({ orderType,orderOption }) => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const { token } = useAuth()
    const focusOtp = useRef()
    const navigate = useNavigate()
    const { id } = useParams()
    const [otp, setOtp] = useState(0);

    const showModal = () => {
        setIsModalOpen(true);
    };
    const handleOk = () => {
        setIsModalOpen(false);
    };
    const handleCancel = () => {
        setIsModalOpen(false);
    };




    useEffect(() => {
        if (focusOtp.current) {
            focusOtp.current.focus();
        }
    }, []);


    const submitHandler = async () => {
        const body = {


            retOrRepId: id,
            userOtp: otp
        }
        try {
            await ReturnReplaceBranchAccept(body, token)
                .then((res) => {
                    console.log("verify otp", res);
                    if (res.status == 201) {
                        navigate("/dashboard/return-replace")
                        notification.success({
                            placement: "topRight",
                            message: res.data.message,
                        });

                    } else if (res.status === 200) {
                        notification.error({
                            placement: "topRight",
                            message: res.data.message,
                        });
                    }
                })
                .catch((err) => {
                    console.log(err.message);
                });
        } catch (error) {
            console.log(error);
        }
    };

    const cancel = (e) => {
        console.log(e);
        message.error('Click on No');
    };

    return (
        <>
            <Button className='return_replace_mark' shape='round' type="primary" onClick={showModal}>
                {orderType === "RETURN" ? "Collect Return" : "Collect Replace"}
            </Button>
            <Modal width={300} footer={false} title="Collect Item" open={isModalOpen} onOk={handleOk} onCancel={handleCancel}>
                <div className="otp_vefiyed">
                    <OtpInput
                        value={otp}
                        onChange={setOtp}
                        numInputs={4}
                        placeholder={0}
                        inputType="numeric"
                        // renderSeparator={<span>-</span>}
                        renderInput={(props, index) => (
                            <div className="ot_field">
                                <Form.Item>

                                    <Input ref={focusOtp}  {...props} style={{ width: "2.5rem", height: "2.5rem" }} placeholder="0" variant="filled"
                                        // type="number"
                                        inputMode="numeric"
                                        pattern="[0-9]*" />
                                </Form.Item>
                            </div>
                        )}
                    />


                    <div className="verify_continue">
                        <Popconfirm
                            title=" Collect Item OTP Verify"
                            description="Are you sure to collect item and verify otp?"
                            onConfirm={submitHandler}
                            onCancel={cancel}
                            okText="Yes"
                            cancelText="No"
                            placement="topLeft"

                        >

                            <Button shape="round" type="default" >Submit</Button>
                        </Popconfirm>
                    </div>
                </div>
            </Modal>
        </>
    );
};
export default CollectPayment;