const deliveryRiderStatusLabels = {
  RETURNPENDING: "Return Pending",
  RETURNASSIGNED: "Return Assigned",
  RETURNACCEPTED: "Return Accepted",
  RETURNVENDORASSIGNED: "Return Delivery Rider Assigned",
  RETURNVENDORACCEPTED: "Return Delivery Rider Accepted",
  RETURNVENDORREACHED: "Return Delivery Rider Reached",
  RETURNREJECTED: "Return Rejected",
  RETURNED: "Returned",
  REPLACEPENDING: "Replace Pending",
  REPLACEASSIGNED: "Replace Assigned",
  REPLACEACCEPTED: "Replace Accepted",
  REPLACEDISPATCHED: "Replace Dispatched",
  REPLACEVENDORASSIGNED: "Replace Delivery Rider Assigned",
  REPLACEVENDORACCEPTED: "Replace Delivery Rider Accepted",
  REPLACEVENDORREACHED: "Replace Delivery Rider Reached",
  REPLACEREJECTED: "Replace Rejected",
  REPLACED: "Replaced",
};

export const getDisplayStatusLabel = (status, fallback) => {
  if (!status) return fallback || "N/A";
  return deliveryRiderStatusLabels[status] || fallback || status;
};
