

import React, { useEffect, useState } from 'react';
import { Alert, Button, Card, Divider, Form, Input, message, Radio, Skeleton } from 'antd';
import { useParams } from 'react-router-dom';
import { useAuth } from '../../authentication/context/authContext';
import { EditOrder } from '../../service/api_services';
import "../../style/order.css"
import { useSelector } from 'react-redux';
import { selectCartItems } from '../../redux-toolkit/CartSlice';
import { parseOfferPattern } from './EditProductsModal';
import TextArea from 'antd/es/input/TextArea';

const RemoveItemDetails = ({ orderDetailsData, ShowOrderList, onClose }) => {
    const { token } = useAuth();
    const { id } = useParams()
    const [isReviewLoad, setIsReviewLoad] = useState(false)
    const [isLoading, setIsLoading] = useState(false);
    const [isRemoveLoder, setIsRemoveLoder] = useState(false)
    const [reason, setReason] = useState("");

    const [form] = Form.useForm();

    const cartItem = useSelector(selectCartItems);

    const getBillingQuantity = (product) => {
        const totalQty = product.unit || 0;
        const offerPattern = (product.offerQty && product.offerProduct) ? parseOfferPattern(product.offerQty) : null;

        if (offerPattern) {
            const numCombos = Math.floor(totalQty / offerPattern.comboSize);
            return numCombos * offerPattern.billingPerCombo;
        }

        return totalQty;
    };

    const reviewRetuenItem = cartItem?.map((product) => {
        return {
            productCode: product.productCode,
            quantity: getBillingQuantity(product),
            _id: product?._id
        };
    }, []);

    const calculateProductTotalPrice = (product) => {
        if ((product?.offerTypeName === "DISCOUNT" || product?.offerTypeName === "PROMOTIONS") && product?.offerProduct) {

            return (
                (Number(product?.unit || 0) / Number(product?.offerProduct?.offerQuantity || 1))
                * Number(product?.requiredOfferedBillingPrice || 0)
            );
        }
        if (parseOfferPattern(product?.offerQty) && product?.offerProduct) {
            const offerPattern = parseOfferPattern(product.offerQty);
            const numCombos = Math.floor(Number(product?.unit || 0) / offerPattern.comboSize);
            const billingQty = numCombos * offerPattern.billingPerCombo;

            return (
                billingQty * Number(product?.requiredOfferedBillingPrice || 0)
            );
        }
        if (product?.offerTypeName === "FOC" && product?.offerProduct) {
            return (
                Number(product?.unit || 0) * Number(product?.requiredOfferedBillingPrice || 0)
            );
        }
        return (
            Number(product?.unit || 0) * Number(product?.bkdAmount || 0)
        );
    };

    const removeOrderHandler = async () => {
        setIsRemoveLoder(true);

        const body = {
            userOrderId: id,
            removedBy: 'BRANCH',
            cart: reviewRetuenItem,
            reason: reason,
            rePaymentMode: orderDetailsData?.paymentMode === "COD" ? "CASH" : "ONLINE",
            status: "",
            oldData: {
                productInfo: orderDetailsData?.productInfo?.map((item) => {
                    return {
                        brandID: item.brandID,
                        brandName: item.brandName,
                        categoryID: item.categoryID,
                        categoryName: item.categoryName,
                        comboPrice: item.comboPrice,
                        isPoolProduct: item.isPoolProduct,
                        isRefridgerator: item.isRefridgerator,
                        mrpPrice: item.mrpPrice,
                        nonReplaceable: item.nonReplaceable,
                        nonReturnable: item.nonReturnable,
                        offerProduct: item.offerProduct ? {
                            billingQty: item.offerProduct.billingQty,
                            isRefridgerator: item.offerProduct.isRefridgerator,
                            mrpPrice: item.offerProduct.mrpPrice,
                            offerId: item.offerProduct.offerId,
                            offerName: item.offerProduct.offerName,
                            productCode: item.offerProduct.productCode,
                            quantity: item.offerProduct.quantity,
                        } : null,
                        offerType: item.offerType,
                        productCode: item.productCode,
                        productPrice: item.productPrice,
                        quantity: item.quantity,
                        requiredOfferedBillingPrice: item.requiredOfferedBillingPrice,
                        requiredOfferedBillingQty: item.requiredOfferedBillingQty,
                        totalPrice: item.totalPrice,
                    };
                }),
                totalPayableAmount: orderDetailsData.totalPayableAmount,
            },
            updatedData: {
                productInfo: cartItem?.map((product) => {
                    return {
                        brandID: product.brandID,
                        brandName: product.brandName,
                        categoryID: product.categoryID,
                        categoryName: product.categoryName,
                        isPoolProduct: product.isPoolProduct,
                        isRefridgerator: product.isRefridgerator,
                        mrpPrice: product.mrpPrice,
                        nonReplaceable: product.nonReplaceable,
                        nonReturnable: product.nonReturnable,
                        offerProduct: product.offerProduct ? {
                            billingQty: product.offerProduct.billingQty,
                            isRefridgerator: product.offerProduct.isRefridgerator,
                            mrpPrice: product.offerProduct.mrpPrice,
                            offerId: product.offerProduct.offerId,
                            offerName: product.offerProduct.offerName,
                            productCode: product.offerProduct.productCode,
                            quantity: product.offerProduct.quantity,
                        } : null,
                        offerType: product.offerType,
                        productCode: product.productCode,
                        productPrice: product.productPrice,
                        quantity: Number(product.unit || 0),
                        requiredOfferedBillingPrice: product.requiredOfferedBillingPrice,
                        requiredOfferedBillingQty: getBillingQuantity(product),
                        totalPrice: Math.round(calculateProductTotalPrice(product)),
                    };
                }),
                totalPayableAmount: Math.round(cartItem?.reduce(
                    (sum, product) =>
                        sum + calculateProductTotalPrice(product),
                    0
                )) + Number(orderDetailsData?.deliveryCharge || 0) - Number(orderDetailsData?.couponDiscountAmount || 0),
            },
        };

        try {
            const res = await EditOrder(token, body);

            if (res && res.status === 201) {
                message.success(res.data.message);
                ShowOrderList();
                onClose?.()
            } else {
                message.error(res?.message);
            }
        } catch (error) {
            message.error(error?.message);
        } finally {
            setIsRemoveLoder(false);
        }
    };

    const oldTotalPayable = Number(orderDetailsData?.totalPayableAmount || 0);

    const updatedTotalPayable = Math.round(cartItem?.reduce(
        (sum, product) =>
            sum + calculateProductTotalPrice(product),
        0
    )) + Number(orderDetailsData?.deliveryCharge || 0) - Number(orderDetailsData?.couponDiscountAmount || 0);

    const refundAmount = Math.max(oldTotalPayable - updatedTotalPayable, 0);

    return (
        <div>
            {isReviewLoad ?
                <Skeleton.Button active block style={{ height: 240 }} /> :
                <>
                    <Alert
                        style={{ margin: '10px 0' }}
                        showIcon={false}
                        banner
                        type="info"
                        message={
                            <div className="saved_item">
                                <p>Refund Amount</p>
                                <strong>₹{refundAmount}</strong>
                            </div>
                        }
                    />
                    <Form form={form} onFinish={removeOrderHandler}>
                        <Form.Item
                            name="reason"
                            rules={[
                                { required: true, message: "Please enter reason" },
                                { min: 3, message: "Reason must be at least 3 characters long" },
                            ]}
                        >
                            <TextArea
                                rows={3}
                                placeholder="Please Enter Reason"
                                value={reason}
                                onChange={(e) => setReason(e.target.value)}
                            />
                        </Form.Item>

                        <div className="remove_item_model_btn">
                            <Button
                                loading={isRemoveLoder}
                                onClick={() => onClose()}
                            >
                                Cancel
                            </Button>
                            <Button
                                type="primary"
                                htmlType="submit"
                                loading={isRemoveLoder}
                            >
                                Submit
                            </Button>
                        </div>
                    </Form>
                </>
            }
        </div>
    );
};

export default RemoveItemDetails;
