import React, { useState } from "react";
import { Button, Modal, Space, Table, Tabs, Tag, message } from "antd";
import { DownloadOutlined } from "@ant-design/icons";
import dayjs from "dayjs";
import { downloadCsvFile } from "../../utils/tableExport";

export const initialVendorOrdersOverview = {
  allOrdersCount: 0,
  liveOrdersCount: 0,
  assignedOrdersCount: 0,
  allOrders: [],
  liveOrders: [],
  assignedOrders: [],
};

const formatOverviewAmount = (value) => `Rs. ${Number(value || 0).toFixed(2)}`;

const formatOverviewSlotTime = (slotStartDateTime, slotEndDateTime) => {
  if (!slotStartDateTime || !slotEndDateTime) return "N/A";

  const slotStart = dayjs(slotStartDateTime);
  const slotEnd = dayjs(slotEndDateTime);

  if (!slotStart.isValid() || !slotEnd.isValid()) return "N/A";

  return `${slotStart.format("hh:mm A")} - ${slotEnd.format("hh:mm A")}`;
};

const getOverviewDelayLabel = (slotEndDateTime) => {
  if (!slotEndDateTime) return "--";

  const slotEnd = dayjs(slotEndDateTime);
  if (!slotEnd.isValid()) return "--";

  const diffMs = dayjs().diff(slotEnd);
  if (diffMs <= 0) return "--";

  const totalMinutes = Math.floor(diffMs / (1000 * 60));
  const days = Math.floor(totalMinutes / (60 * 24));
  const hours = Math.floor((totalMinutes % (60 * 24)) / 60);
  const minutes = totalMinutes % 60;
  const parts = [];

  if (days) parts.push(`${days}d`);
  if (hours) parts.push(`${hours}h`);
  if (minutes || parts.length === 0) parts.push(`${minutes}m`);

  return parts.join(" ");
};

const getOverviewSlotState = (record) => {
  const slotStart = dayjs(record?.slotStartDateTime);
  const slotEnd = dayjs(record?.slotEndDateTime);

  if (!slotStart.isValid() || !slotEnd.isValid()) {
    return { status: "none" };
  }

  const now = dayjs();

  if (now.isAfter(slotEnd)) {
    return {
      status: "delayed",
      label: `Delay: ${getOverviewDelayLabel(record?.slotEndDateTime)}`,
    };
  }

  if (now.isAfter(slotStart)) {
    return {
      status: "started",
      label: `Slot Started: ${getOverviewDelayLabel(record?.slotStartDateTime)}`,
    };
  }

  return { status: "onTime", label: "--" };
};

const getOverviewRowClassName = (record) => {
  const slotState = getOverviewSlotState(record);

  if (slotState.status === "delayed") {
    return "delayed-delivery-row";
  }

  if (slotState.status === "started") {
    return "slot-started-delivery-row";
  }

  return "";
};

const getOverviewStatusColor = (status) => {
  switch (status) {
    case "DISPATCHED":
      return "blue";
    case "REACHED":
      return "purple";
    case "ASSIGNED":
      return "gold";
    case "ACCEPTED":
      return "green";
    case "ORDERPACKED":
      return "cyan";
    case "DELIVERED":
    case "PARTIALDELIVERED":
    case "PARTIALDELIVEREDRETURN":
      return "green";
    case "CANCELLED":
    case "CANCELLEDRETURN":
      return "red";
    case "CLOSED":
      return "default";
    default:
      return "default";
  }
};

const getCashCollectionStatusColor = (status) => {
  switch (status) {
    case "PREPAID":
      return "blue";
    case "COLLECTED":
      return "green";
    case "PENDING":
      return "orange";
    default:
      return "default";
  }
};

const overviewTabMeta = {
  "all-orders": {
    label: "All Orders",
    countKey: "allOrdersCount",
    dataKey: "allOrders",
  },
  "live-orders": {
    label: "Live Orders",
    countKey: "liveOrdersCount",
    dataKey: "liveOrders",
  },
  "assigned-orders": {
    label: "Assigned Orders",
    countKey: "assignedOrdersCount",
    dataKey: "assignedOrders",
  },
};

const overviewExportColumns = [
  { header: "Order ID", key: "orderCode" },
  { header: "Customer Name", key: "customerName" },
  { header: "Customer Mobile", key: "customerMobile" },
  { header: "Items", key: "items" },
  { header: "Placed Date & Time", key: "placedDateTime" },
  { header: "Dispatch Date & Time", key: "dispatchDateTime" },
  { header: "Slot Time", key: "slotTime" },
  { header: "Delay", key: "delay" },
  { header: "Amount", key: "amount" },
  { header: "Payment Mode", key: "paymentMode" },
  { header: "Distance", key: "distance" },
  { header: "Status", key: "status" },
  { header: "Type", key: "type" },
  { header: "Cash Collection", key: "cashCollectionStatus" },
];

const formatOverviewDateTime = (value) =>
  value && dayjs(value).isValid() ? dayjs(value).format("DD MMM YYYY, hh:mm A") : "N/A";

const sanitizeExportFileName = (value) =>
  String(value || "delivery-rider")
    .replace(/[^a-z0-9-_]+/gi, "-")
    .replace(/^-+|-+$/g, "") || "delivery-rider";

const vendorOrdersOverviewColumns = [
  {
    title: "Order ID",
    dataIndex: "orderCode",
    key: "orderCode",
    width: 112,
    render: (value) => value || "N/A",
  },
  {
    title: "Customer",
    key: "customer",
    width: 142,
    render: (_, record) => (
      <div>
        <div style={{ fontWeight: 600 }}>{record.customerName}</div>
        <div style={{ color: "#667085" }}>{record.customerMobile}</div>
      </div>
    ),
  },
  {
    title: "Items",
    dataIndex: "items",
    key: "items",
    width: 56,
  },
  {
    title: "Placed Date",
    dataIndex: "placedDateTime",
    key: "placedDateTime",
    width: 112,
    render: (value) => (
      <div>
        <div>{value ? dayjs(value).format("DD MMM YYYY") : "N/A"}</div>
        <div style={{ color: "#667085" }}>
          {value ? dayjs(value).format("hh:mm A") : ""}
        </div>
      </div>
    ),
  },
  {
    title: "Dispatch Time",
    dataIndex: "dispatchDateTime",
    key: "dispatchDateTime",
    width: 112,
    render: (value) => (
      <div>
        <div>{value ? dayjs(value).format("DD MMM YYYY") : "N/A"}</div>
        <div style={{ color: "#667085" }}>
          {value ? dayjs(value).format("hh:mm A") : ""}
        </div>
      </div>
    ),
  },
  {
    title: "Slot Time",
    key: "slotTime",
    width: 128,
    render: (_, record) =>
      formatOverviewSlotTime(record.slotStartDateTime, record.slotEndDateTime),
  },
  {
    title: "Delay",
    key: "delay",
    width: 138,
    render: (_, record) => {
      const slotState = getOverviewSlotState(record);

      if (slotState.status === "delayed") {
        return <Tag color="red">{slotState.label}</Tag>;
      }

      if (slotState.status === "started") {
        return <Tag color="gold">{slotState.label}</Tag>;
      }

      return "--";
    },
  },
  {
    title: "Amount",
    dataIndex: "amount",
    key: "amount",
    width: 96,
    render: formatOverviewAmount,
  },
  {
    title: "Payment Mode",
    dataIndex: "paymentMode",
    key: "paymentMode",
    width: 104,
    render: (value) => <Tag>{value || "N/A"}</Tag>,
  },
  {
    title: "Distance",
    dataIndex: "distance",
    key: "distance",
    width: 82,
  },
  {
    title: "Status",
    dataIndex: "status",
    key: "status",
    width: 112,
    render: (value) => <Tag color={getOverviewStatusColor(value)}>{value}</Tag>,
  },
  {
    title: "Type",
    dataIndex: "type",
    key: "type",
    width: 92,
    render: (value) => <Tag color="geekblue">{value || "N/A"}</Tag>,
  },
  {
    title: "Cash Collection",
    dataIndex: "cashCollectionStatus",
    key: "cashCollectionStatus",
    width: 126,
    render: (value) => (
      <Tag color={getCashCollectionStatusColor(value)}>{value || "N/A"}</Tag>
    ),
  },
];

const renderVendorOrdersOverviewTable = (dataSource, loading) => (
  <div className="vendor-orders-overview-table">
    <Table
      columns={vendorOrdersOverviewColumns}
      dataSource={dataSource}
      loading={loading}
      rowKey={(record) => record?._id || record?.orderCode}
      pagination={{ pageSize: 6, position: ["bottomCenter"] }}
      size="small"
      className="vendor-orders-overview-ant-table"
      tableLayout="fixed"
      scroll={{ x: 1410 }}
      rowClassName={getOverviewRowClassName}
      locale={{ emptyText: "No orders found for this delivery rider" }}
    />
  </div>
);

function RiderOrdersOverviewModal({
  open,
  onCancel,
  selectedVendor,
  vendorOrdersLoading,
  vendorOrdersOverview,
}) {
  const [selectedOverviewTab, setSelectedOverviewTab] = useState("all-orders");

  const handleOverviewExport = () => {
    const activeTab = overviewTabMeta[selectedOverviewTab] || overviewTabMeta["all-orders"];
    const dataSource = vendorOrdersOverview?.[activeTab.dataKey] || [];

    if (!dataSource.length) {
      message.warning(`No ${activeTab.label.toLowerCase()} available to export`);
      return;
    }

    const rows = dataSource.map((record) => ({
      orderCode: record?.orderCode || "N/A",
      customerName: record?.customerName || "N/A",
      customerMobile: record?.customerMobile || "N/A",
      items: record?.items ?? 0,
      placedDateTime: formatOverviewDateTime(record?.placedDateTime),
      dispatchDateTime: formatOverviewDateTime(record?.dispatchDateTime),
      slotTime: formatOverviewSlotTime(record?.slotStartDateTime, record?.slotEndDateTime),
      delay: getOverviewDelayLabel(record?.slotEndDateTime),
      amount: formatOverviewAmount(record?.amount),
      paymentMode: record?.paymentMode || "N/A",
      distance: record?.distance || "N/A",
      status: record?.status || "N/A",
      type: record?.type || "N/A",
      cashCollectionStatus: record?.cashCollectionStatus || "N/A",
    }));

    const riderName = sanitizeExportFileName(
      selectedVendor?.fullName || selectedVendor?.mobileNo || "delivery-rider"
    );
    const tabName = sanitizeExportFileName(activeTab.label);
    downloadCsvFile(`${riderName}-${tabName}-order-overview.csv`, overviewExportColumns, rows);
  };

  return (
    <Modal
      open={open}
      title={`${selectedVendor?.fullName || "Delivery Rider"} Orders`}
      footer={null}
      width="calc(100vw - 64px)"
      style={{ maxWidth: 1440 }}
      styles={{ body: { overflowX: "visible" } }}
      onCancel={onCancel}
    >
      <div style={{ display: "grid", gap: 16 }}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            gap: 12,
            flexWrap: "wrap",
          }}
        >
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            <Tag color="green">
              All Orders: {vendorOrdersOverview?.allOrdersCount || 0}
            </Tag>
            <Tag color="blue">
              Live Orders: {vendorOrdersOverview?.liveOrdersCount || 0}
            </Tag>
            <Tag color="gold">
              Assigned Orders: {vendorOrdersOverview?.assignedOrdersCount || 0}
            </Tag>
          </div>

          <Space>
            <Button
              type="primary"
              icon={<DownloadOutlined />}
              onClick={handleOverviewExport}
              disabled={vendorOrdersLoading}
            >
              Export
            </Button>
          </Space>
        </div>

        <Tabs
          size="small"
          activeKey={selectedOverviewTab}
          onChange={setSelectedOverviewTab}
          items={[
            {
              key: "all-orders",
              label: `All Orders (${vendorOrdersOverview?.allOrdersCount || 0})`,
              children: renderVendorOrdersOverviewTable(
                vendorOrdersOverview?.allOrders || [],
                vendorOrdersLoading
              ),
            },
            {
              key: "live-orders",
              label: `Live Orders (${vendorOrdersOverview?.liveOrdersCount || 0})`,
              children: renderVendorOrdersOverviewTable(
                vendorOrdersOverview?.liveOrders || [],
                vendorOrdersLoading
              ),
            },
            {
              key: "assigned-orders",
              label: `Assigned Orders (${vendorOrdersOverview?.assignedOrdersCount || 0})`,
              children: renderVendorOrdersOverviewTable(
                vendorOrdersOverview?.assignedOrders || [],
                vendorOrdersLoading
              ),
            },
          ]}
        />
      </div>
    </Modal>
  );
}

export default RiderOrdersOverviewModal;
