import React, { useEffect, useState } from "react";
import {
    Alert,
    Avatar,
    Breadcrumb,
    Button,
    Card,
    DatePicker,
    Descriptions,
    Divider,
    Empty,
    Form,
    Image,
    Input,
    List,
    message,
    Modal,
    Popconfirm,
    QRCode,
    Select,
    Space,
    Table,
    Tag,
    Typography,
} from "antd";
import "../../style/order.css";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import { Col, Row } from "react-bootstrap";
import { HiOutlineShoppingBag } from "react-icons/hi";
import { ExclamationCircleFilled, InfoCircleOutlined, ReloadOutlined } from "@ant-design/icons";
import { MdLocationPin, MdOutlineKeyboardBackspace, MdStorefront } from "react-icons/md";
import moment from "moment/moment";
import OTPInput from "react-otp-input";
import { useDispatch, useSelector } from "react-redux";

import {
    ActionOrderStatus,
    CollectPickupCodPayment,
    fetchAllSloteAvailable,
    fetchOrderDetails,
    fetchOrderEditHistory,
    fetchVendorReturnPin,
    OrderCacelByBranch,
    UpdateDeliverySlot,
} from "../../service/api_services";
import { useAuth } from "../../authentication/context/authContext";
import { useScreen } from "../../authentication/context/AuthScreen";
import { addItem, fetchCartProducts, removeCartItem, selectCartItems } from "../../redux-toolkit/CartSlice";

import KotDetails from "./KotDetails";
import InvoiceDetials from "./InvoiceDetials";
import VendorAssignModel from "./VendorAssignModel";
import PickupOtpVerify from "./PickupOtpVerify";
import RemoveItemDetails from "./RemoveOrderItem";
import OrderInfo from "./OrderInfo";
import OrderComplaintAction from "./OrderComplaintAction";

import LogImng from "../../assest/png/logoIcon.png";
import DefaulImg from "../../assest/icon/bkd logo (1).png";
import DefaultImage from "../../assest/png/default-image.jpg"
import BKDLogo from "../../assest/chat/logo.png";
import DefaultImg from "../../assest/png/user.png"
import EditProductsModal from "./EditProductsModal";
import dayjs from "dayjs";
import EditProductsHistoryModal from "./EditProductsHistoryModal";
import { getDisplayStatusLabel } from "../../utils/statusDisplay";

export const formatCurrency = (value) => {
    const amount = Number(value);
    return Number.isFinite(amount) ? `Rs. ${amount.toFixed(2)}` : "Rs. 0.00";
};

function OrderDetails() {
    const { screenWidth } = useScreen();
    const isMobile = screenWidth < 768;
    const getOrderSourceTag = (orderSource) => (
        <Tag color={orderSource === "WEB" ? "geekblue" : "green"}>
            {orderSource || "APP"}
        </Tag>
    );
    const location = useLocation();
    const navigate = useNavigate();
    const { id } = useParams();
    const { confirm } = Modal;
    const [form] = Form.useForm();
    const dispatch = useDispatch();
    const cartItem = useSelector(selectCartItems);

    const { token, logout, login, getBranchData } = useAuth();

    const [orderData, setOrderData] = useState([]);
    const [slotList, setSlotList] = useState([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isOrderHistoryLoading, setIsOrderHistoryLoading] = useState(false);
    const [orderEditHistoryData, setOrderEditHistoryData] = useState([]);
    const [isChangeSlot, setIsChangeSlot] = useState(false);
    const [isLoadInvoice, setIsLoadInvoice] = useState(false);
    const [isRemove, setIsRemove] = useState(false);
    const [isShowOtp, setIsShowOtp] = useState(false);
    const [isOtpLoading, setIsOtpLoading] = useState(false);
    const [isAcceptLoading, setIsAcceptLoading] = useState(false);
    const [openRemoveModal, setOpenRemoveModal] = useState(false);
    const [delDate, setDelDate] = useState(null);
    const [otp, setOtp] = useState("");
    const [vendorReturnPin, setVendorReturnPin] = useState(null);
    const [isVendorReturnPinLoading, setIsVendorReturnPinLoading] = useState(false);
    const [isEditModal, setIsEditModal] = useState(false);
    const [openHistoryModal, setOpenHistoryModal] = useState(false);
    const [selectedProducts, setSelectedProducts] = useState([]);
    const [historyTitle, setHistoryTitle] = useState("");

    const toggleEditModal = () => setIsEditModal(!isEditModal)
    const toggleOrderHistoryModal = () => setOpenHistoryModal(!openHistoryModal)


    const accessToken = new URLSearchParams(window.location.search).get("code");
    const accessBranchName = new URLSearchParams(window.location.search).get("branchName");
    const accessBranchCode = new URLSearchParams(window.location.search).get("branchCode");

    const handleOpenHistoryProducts = (products, title) => {
        setSelectedProducts(products || []);
        setHistoryTitle(title)
        toggleOrderHistoryModal();
    };

    useEffect(() => {
        if (accessToken) {
            login(accessToken);
            localStorage.setItem("token", accessToken);
            localStorage.setItem(
                "branchData",
                JSON.stringify({ branchCode: accessBranchCode, branchName: accessBranchName })
            );
            getBranchData({ branchCode: accessBranchCode, branchName: accessBranchName });
        }
    }, [accessToken, accessBranchCode, accessBranchName, getBranchData, login]);

    const getStatusColor = (status) => {
        switch (status) {
            case "ASSIGNED":
                return "#EB5B00";
            case "ORDERPACKED":
                return "#219C90";
            case "ACCEPTED":
                return "#90D26D";
            case "DISPATCHED":
                return "#008DDA";
            case "REACHED":
                return "#7E60BF";
            case "DELIVERED":
            case "DELIVERD":
                return "#87A922";
            case "PARTIALDELIVERED":
                return "#90D26D";
            case "CANCELLED":
                return "#F95454";
            case "CANCELLEDRETURN":
                return "#F87A53";
            case "CLOSED":
                return "#C62E2E";
            default:
                return "#B3A398";
        }
    };

    // Helper function to parse offer pattern (e.g., "1+1", "2+1", "4+1", "1+2")
    const parseOfferPattern = (offerQtyStr) => {
        if (!offerQtyStr || typeof offerQtyStr !== 'string') return null;
        const parts = offerQtyStr.split('+');
        if (parts.length !== 2) return null;
        const billing = parseInt(parts[0], 10);
        const free = parseInt(parts[1], 10);
        if (isNaN(billing) || isNaN(free)) return null;
        return { billingPerCombo: billing, freePerCombo: free, comboSize: billing + free };
    };

    const getOrderItemAmount = (item) => {
        const quantity = Number(item?.quantity ?? item?.unit ?? 0);
        const lineAmount = Number(item?.bkdAmount);
        const comboPrice = Number(item?.requiredOfferedBillingPrice);
        const unitPrice = Number(item?.productPrice ?? item?.bkdAmount);

        // Check if item has an offer pattern (e.g., "1+1", "2+1")
        const offerPattern = item.offerQty ? parseOfferPattern(item.offerQty) : null;

        if (offerPattern && Number.isFinite(comboPrice) && comboPrice > 0) {
            // Calculate number of complete combos
            const numCombos = Math.floor(quantity / offerPattern.comboSize);
            // Calculate billing quantity (only the paid items, not free ones)
            const billingQty = numCombos * offerPattern.billingPerCombo;
            // Calculate remaining items (not part of any combo)
            const remainderQty = quantity % offerPattern.comboSize;
            const remainderAmount = Number.isFinite(unitPrice) ? remainderQty * unitPrice : 0;

            return (billingQty * comboPrice) + remainderAmount;
        }

        if (Number.isFinite(quantity) && quantity > 0 && Number.isFinite(unitPrice)) {
            return quantity * unitPrice;
        }

        return Number.isFinite(lineAmount) ? lineAmount : 0;
    };

    const getOrderItemUnitPrice = (item) => {
        const quantity = Number(item?.quantity) || 1;
        return getOrderItemAmount(item) / quantity;
    };

    const canCancelOrder = !(
        orderData?.status === "DISPATCHED" ||
        orderData?.status === "CLOSED" ||
        orderData?.status === "DELIVERD" ||
        orderData?.status === "DELIVERED" ||
        orderData?.status === "CANCELLED"
    );

    const canEditOrder = !(
        orderData?.status === "DELIVERD" ||
        orderData?.status === "DELIVERED" ||
        orderData?.status === "PARTIALDELIVERED" ||
        orderData?.status === "CANCELLED" ||
        orderData?.status === "CANCELLEDRETURN" ||
        orderData?.status === "CLOSED"
    );

    const paymentColumns = [
        {
            title: "Pay Action",
            dataIndex: "actionOn",
            key: "actionOn",
            render: (actionOn) => (
                <Tag bordered={false} color={actionOn !== "ORDER" ? "red" : "green"}>{actionOn}</Tag>
            ),
        },
        {
            title: "Payment Date",
            dataIndex: "paidDateTime",
            key: "paidDateTime",
            render: (paidDateTime) => <span>{paidDateTime || "N/A"}</span>,
        },
        {
            title: "Payment Mode",
            dataIndex: "paymentMode",
            key: "paymentMode",
        },
        {
            title: "Amount",
            dataIndex: "amountPaid",
            key: "amountPaid",
            render: (amountPaid) => <span>{formatCurrency(amountPaid)}</span>,
        },
        {
            title: "Status",
            dataIndex: "status",
            key: "status",
            render: (_, { status }) => <Tag color={status === "SUCCESS" ? "#059212" : "blue"}>{status}</Tag>,
        },
    ];

    const editedHistoryColumns = [
        {
            title: "Old Product Count",
            dataIndex: "oldProductInfo",
            key: "oldProductInfo",
            render: (oldProductInfo) => (
                <Space>
                    <span>{oldProductInfo?.length || "0"}</span>
                    <div
                        style={{ cursor: 'pointer', color: "#1677ff" }}
                        onClick={() => handleOpenHistoryProducts(oldProductInfo, "Old Product List")}
                    >
                        <InfoCircleOutlined />
                    </div>
                </Space>
            ),
        },
        {
            title: "New Product Count",
            dataIndex: "newProductInfo",
            key: "newProductInfo",
            render: (newProductInfo) => (
                <Space>
                    <span>{newProductInfo?.length || "0"}</span>
                    <div
                        style={{ cursor: 'pointer', color: "#1677ff" }}
                        onClick={() => handleOpenHistoryProducts(newProductInfo, "New Product List")}
                    >
                        <InfoCircleOutlined />
                    </div>
                </Space>
            ),
        },
        {
            title: "Edited Date",
            dataIndex: "modifiedDate",
            key: "modifiedDate",
            render: (modifiedDate) => <span>{modifiedDate ? dayjs(modifiedDate).format("DD MMM YYYY, hh:mm A") : "N/A"}</span>,
        },
        {
            title: "Old Total Payment",
            dataIndex: "oldPaymentDetails",
            key: "oldPaymentDetails",
            render: (oldPaymentDetails) => <span>{formatCurrency(oldPaymentDetails.totalPayableAmount)}</span>,
        },
        {
            title: "New Total Payment",
            dataIndex: "newPaymentDetails",
            key: "newPaymentDetails",
            render: (newPaymentDetails) => <span>{formatCurrency(newPaymentDetails.totalPayableAmount)}</span>,
        },
    ];

    const getActionByLabel = (value) => {
        if (value === "VENDOR") {
            return "Delivery Rider";
        }

        return value || "N/A";
    };

    const statusColumns = [
        {
            title: "Order Status",
            dataIndex: "orderStatus",
            key: "orderStatus",
            render: (orderStatus) => <Tag bordered={false} color={getStatusColor(orderStatus)}>{getDisplayStatusLabel(orderStatus)}</Tag>,
        },
        { title: "Name", dataIndex: "addedName", key: "addedName" },
        { title: "Action Date", dataIndex: "addedDate", key: "addedDate" },
        { title: "Action Time", dataIndex: "addedTime", key: "addedTime" },
        {
            title: "Action By",
            dataIndex: "addedVia",
            key: "addedVia",
            render: (value) => getActionByLabel(value),
        },
    ];

    const orderProductColumns = [
        {
            title: "Img",
            dataIndex: "imageUrl",
            key: "image",
            width: 90,
            render: (_, item) => (
                item.imageUrl != null ? (
                    <Image
                        src={item.imageUrl || BKDLogo}
                        onError={(e) => e.currentTarget.src = BKDLogo}
                        className="order_images"
                        width={50}
                        height={50}
                    />
                ) : (
                    <Avatar
                        size={50}
                        shape="square"
                        src={DefaulImg}
                        className="order_images"
                    />
                )
            ),
        },
        {
            title: "Product Name",
            dataIndex: "productName",
            key: "productName",
            render: (_, item) => (
                <div className="order-table-name-cell">
                    <div className="order-table-name-title">
                        <span>{item.productName}</span>
                        {item.isRefridgerator ? (
                            <Tag icon={<HiOutlineShoppingBag className="bags" />} color="blue" bordered={false}>Frozen</Tag>
                        ) : (
                            <Tag icon={<HiOutlineShoppingBag className="bags" />} bordered={false}>Normal</Tag>
                        )}
                    </div>
                    <div className="order-table-name-meta">
                        <span>{item.packSize}</span>
                    </div>
                    <div className="order-table-alerts">
                        <Alert banner message="Return" type={item.isReturnable ? "success" : "error"} showIcon />
                        <Alert banner message="Replace" type={item.isReturnable ? "success" : "error"} showIcon />
                    </div>
                    {item.offerProduct != null && item.offerType !== "DISCOUNT" ? (
                        <div className="order-offer-line">
                            <div className="order-offer-title">{item.offerProduct.productName}</div>
                            <div className="order-product-meta-row order-offer-meta">
                                <span>{item.offerProduct.packSize}</span>
                                <span>Qty. {item.offerProduct.quantity}</span>
                                <span><del>{formatCurrency(item.offerProduct.mrpPrice)}</del></span>
                                {item.offerProduct.productPrice === 0 ? <span className="offer_product">Free</span> : null}
                            </div>
                        </div>
                    ) : null}
                </div>
            ),
        },
        {
            title: "Qty",
            dataIndex: "quantity",
            key: "quantity",
            width: 80,
            render: (qty, item) => <span>{item.requiredOfferedBillingQty ?? qty}</span>,
        },
        {
            title: "Sell Price",
            key: "sellPrice",
            width: 120,
            render: (_, item) => {
                const sellPrice = Number(item?.requiredOfferedBillingPrice) > 0 ? item.requiredOfferedBillingPrice : item.productPrice;
                return <span>{formatCurrency(sellPrice)}</span>;
            },
        },
        {
            title: "Total Amount",
            key: "totalAmount",
            width: 150,
            render: (_, item) => (
                <div className="order-table-total-cell">
                    {item.status === "REMOVED" || item.status === "RETURN" || item.status === "REPLACE" ? (
                        <Tag color={item.status === "RETURN" ? "orange" : item.status === "REMOVED" ? "red" : "blue"}>{item.status}</Tag>
                    ) : null}
                    <span>{formatCurrency(item.totalPrice)}</span>
                </div>
            ),
        },
    ];

    const showOrderList = async () => {
        if (!token && !accessToken) return;
        setIsLoading(true);
        try {
            const res = await fetchOrderDetails(token || accessToken, id);
            if (res.status === 200) {
                const productItem = res.data.data.productInfo || [];
                setOrderData(res.data.data);
                setIsLoadInvoice(true);
                const productUnit = productItem.map((item) => ({
                    ...item,
                    unit: item.quantity,
                    offerProduct: item.offerProduct
                        ? { ...item.offerProduct, OfferQty: item.offerProduct.quantity, billlingQty: item.quantity }
                        : null,
                }));
                dispatch(fetchCartProducts(productUnit));
                localStorage.setItem("cart", JSON.stringify(productUnit));
            } else if (res.data.code === 283) {
                message.error(res.data.message);
                logout();
            }
        } catch (error) {
            message.error(error?.message || "Unable to fetch order details");
        } finally {
            setIsLoading(false);
        }
    };

    const showOrderEditHistory = async () => {
        if (!token && !accessToken) return;
        setIsOrderHistoryLoading(true);
        try {
            const res = await fetchOrderEditHistory(token || accessToken, id);
            if (res.status === 200) {
                const productItem = res.data.data.list || [];
                setOrderEditHistoryData(productItem);
            } else if (res.data.code === 283) {
                message.error(res.data.message);
                logout();
            }
        } catch (error) {
            message.error(error?.message || "Unable to fetch order details");
        } finally {
            setIsOrderHistoryLoading(false);
        }
    };

    const loadVendorReturnPin = async () => {
        const authToken = token || accessToken;
        if (!authToken || !id) return;
        setIsVendorReturnPinLoading(true);
        try {
            const res = await fetchVendorReturnPin(authToken, id);
            if (res?.status === 200) {
                const pin =
                    res?.data?.data?.vendorReturnPin ??
                    res?.data?.vendorReturnPin ??
                    res?.data?.data?.pin ??
                    null;
                setVendorReturnPin(pin || null);
            } else {
                setVendorReturnPin(null);
            }
        } catch (error) {
            setVendorReturnPin(null);
        } finally {
            setIsVendorReturnPinLoading(false);
        }
    };

    const showAvailableSlotList = async () => {
        if (!orderData?.deliveryOption) return;
        try {
            const res = await fetchAllSloteAvailable(orderData.deliveryOption, token || accessToken);
            if (res.status === 200) {
                setSlotList(res.data.data || []);
            }
        } catch (error) {
            console.log(error);
        }
    };

    useEffect(() => {
        showOrderList();
        showOrderEditHistory();
    }, [token, accessToken, id]);

    useEffect(() => {
        loadVendorReturnPin();
    }, [token, accessToken, id]);

    useEffect(() => {
        showAvailableSlotList();
    }, [orderData?.deliveryOption, token, accessToken]);

    useEffect(() => {
        localStorage.setItem("cart", JSON.stringify(cartItem));
    }, [cartItem]);

    const onDateChange = (_, dateString) => setDelDate(dateString);
    const disabledDate = (current) => current && current < moment().startOf("day");

    const handleSlotChange = async (value) => {
        setIsChangeSlot(true);
        try {
            const res = await UpdateDeliverySlot({ ...value, userOrderId: id, deliveryDate: delDate }, token || accessToken);
            if (res.status === 201) {
                message.success(res.data.message);
                showOrderList();
                form.resetFields();
            } else {
                message.error(res.data.message);
            }
        } catch (error) {
            message.error(error?.message || "Unable to update delivery slot");
        } finally {
            setIsChangeSlot(false);
        }
    };

    const changeStatusHandler = async (userOrderId, vendorId, status) => {
        if (orderData?.deliveryOption === "DELIVERY" && status === "ACCEPTED" && vendorId == null) {
            message.warning("Please assign a Delivery Rider");
            return;
        }
        setIsAcceptLoading(true);
        try {
            const res = await ActionOrderStatus({ userOrderId }, token || accessToken);
            if (res.data.code === 201) {
                message.success(res.data.message);
                showOrderList();
            } else {
                message.warning(res.data.message);
            }
        } catch (error) {
            message.error(error?.message || "Unable to update order status");
        } finally {
            setIsAcceptLoading(false);
        }
    };

    const getStatusActions = () => {
        if (orderData?.status === "ASSIGNED") {
            return (
                <Popconfirm title="Accept the Order" description="Are you sure to accept this order?" onConfirm={() => changeStatusHandler(id)} onCancel={() => message.error("You selected No")} okText="Yes" cancelText="No" placement="topLeft">
                    <Button loading={isAcceptLoading} type="primary" shape="round" size={isMobile ? "small" : "middle"}>Accept Order</Button>
                </Popconfirm>
            );
        }
        if (orderData?.status === "ACCEPTED") {
            return (
                <Popconfirm title="Order Has been Packed" description="Are you sure this order is packed?" onConfirm={() => changeStatusHandler(id, orderData?.vendorId, orderData?.status)} onCancel={() => message.error("You selected No")} okText="Yes" cancelText="No" placement="topLeft">
                    <Button loading={isAcceptLoading} type="primary" shape="round" size={isMobile ? "small" : "middle"}>Packed</Button>
                </Popconfirm>
            );
        }
        if (orderData?.status === "ORDERPACKED") return <Button disabled shape="round" size={isMobile ? "small" : "middle"}>Go For Scan</Button>;
        if (orderData?.status === "DISPATCHED") return <Button disabled shape="round" size={isMobile ? "small" : "middle"}>Dispatched</Button>;
        return null;
    };
    const error = (userOrderId) => {
        let reason = null;
        confirm({
            title: "Are you sure cancel this order?",
            icon: <ExclamationCircleFilled />,
            content: (
                <Form.Item name="reason" rules={[{ required: true, message: "Please enter cancel reason" }]}>
                    <Input placeholder="Please Enter Cancel Reason" onChange={(e) => { reason = e.target.value; }} />
                </Form.Item>
            ),
            okText: "Yes",
            okType: "danger",
            cancelText: "No",
            onOk: async () => {
                if (!reason) {
                    message.error("Reason is required");
                    return Promise.reject();
                }
                const res = await OrderCacelByBranch({ userOrderId, reason }, token || accessToken);
                if (res.status === 201) {
                    message.success(res.data.message);
                    showOrderList();
                    return true;
                }
                message.error(res.data.message);
                return Promise.reject();
            },
        });
    };

    const handleEditItem = () => {
        if (orderData.status === "ASSIGNED") {
            message.error("Please accept this order first");
            return;
        }
        if (orderData.status === "ORDERPACKED" || orderData.status === "DISPATCHED") {
            setIsShowOtp(true);
            return;
        }
        toggleEditModal()
    };

    const handleSaveEdit = () => {
        if (isRemove) setOpenRemoveModal(true);
    };

    const handleCancelEdit = () => {
        const originalCart = (orderData?.productInfo || []).map((item) => ({ ...item, unit: item.quantity }));
        dispatch(fetchCartProducts(originalCart));
        localStorage.setItem("cart", JSON.stringify(originalCart));
        setIsRemove(false);
    };

    const handleAddItem = (item) => {
        const offerPattern = item.offerQty ? parseOfferPattern(item.offerQty) : null;
        if (offerPattern) {
            // Add full combo (e.g., for "1+1", add 2 items; for "2+1", add 3 items)
            for (let i = 0; i < offerPattern.comboSize; i++) {
                dispatch(addItem(item));
            }
        } else {
            dispatch(addItem(item));
        }
    };

    const handleDelItem = (item) => {
        const offerPattern = item.offerQty ? parseOfferPattern(item.offerQty) : null;
        if (offerPattern) {
            // Remove full combo
            for (let i = 0; i < offerPattern.comboSize; i++) {
                dispatch(removeCartItem(item));
            }
        } else {
            dispatch(removeCartItem(item));
            const cart = JSON.parse(localStorage.getItem("cart")) || [];
            localStorage.setItem("cart", JSON.stringify(cart.filter((cartProduct) => cartProduct.productCode !== item.productCode)));
        }
    };

    const otpVerifyHandler = () => {
        if (otp.length !== 4) return message.error("Please enter valid OTP");
        if (otp !== "1111") return message.error("Invalid OTP");
        setIsOtpLoading(true);
        setTimeout(() => {
            setIsOtpLoading(false);
            setIsShowOtp(false);
            setIsRemove(true);
            message.success("OTP Verified Successfully");
        }, 1000);
    };

    const handleCollectPayment = async (userOrderId, totalPayableAmount) => {
        try {
            const res = await CollectPickupCodPayment({ userOrderId, amountPaid: totalPayableAmount }, token || accessToken);
            if (res.status === 201) {
                message.success(res.data.message);
                showOrderList();
            } else {
                message.error(res.data.message);
            }
        } catch (error) {
            message.error(error?.message || "Unable to collect payment");
        }
    };

    const renderReadOnlyItemsCard = (title, items) => {
        if (!items?.length) return null;
        return (
            <div className="show_transition_list" style={{ margin: "10px" }}>
                <Card title={title} className="card_body_properties order-data-card">
                    <List
                        itemLayout="horizontal"
                        dataSource={items}
                        renderItem={(item) => (
                            <List.Item className="remove_items_select" actions={[<b>{formatCurrency(getOrderItemAmount(item))}</b>]}>
                                <List.Item.Meta
                                    avatar={item.imageUrl ? <Image src={item.imageUrl || BKDLogo} className="order_images" width={50} /> : <Avatar size={50} shape="square" src={DefaulImg} className="order_images" />}
                                    title={<p><span>{item.productName}</span></p>}
                                    description={<div className="order-product-meta-row"><span>{item.packSize}</span><span>Qty. {item.quantity}</span></div>}
                                />
                            </List.Item>
                        )}
                    />
                </Card>
            </div>
        );
    };

    return (
        <>
            <section className="main_Section order-details-page">
                <Breadcrumb style={{ marginBottom: "8px" }} items={[{ title: "Dashboard" }, { title: location.pathname }]} />

                <div className="content_head order-details-toolbar">
                    <div className="order_content_title">
                        <Card className="card_body order-toolbar-card">
                            <div className="order_status_titiles order-toolbar-inner">
                                <div className="order_title order-toolbar-title">
                                    <Space style={{ alignItems: "start" }}>
                                        <Button shape="circle" onClick={() => navigate(-1)}>
                                            <MdOutlineKeyboardBackspace className="back_icon" />
                                        </Button>
                                        <Typography.Title level={4} style={{ marginBottom: 0 }}>Order Details</Typography.Title>
                                    </Space>
                                </div>
                                <Space className="order-toolbar-actions">
                                    <OrderComplaintAction
                                        order={{ ...orderData, _id: orderData?._id || id }}
                                        label="Complaint"
                                        buttonProps={{
                                            shape: "round",
                                            size: isMobile ? "small" : "middle",
                                            className: "order-complaint-button",
                                            disabled: !id,
                                        }}
                                    />
                                    <Button
                                        shape="circle"
                                        icon={<ReloadOutlined />}
                                        loading={isLoading || isVendorReturnPinLoading}
                                        onClick={() => {
                                            showOrderList();
                                            showAvailableSlotList();
                                            loadVendorReturnPin();
                                        }}
                                        title="Refresh"
                                        size={isMobile ? "small" : "middle"}
                                    />
                                    {canCancelOrder ? (
                                        <Button danger shape="round" onClick={() => error(id)} size={isMobile ? "small" : "middle"}>Cancel Order</Button>
                                    ) : null}
                                    {getStatusActions()}
                                </Space>
                            </div>
                        </Card>
                    </div>
                </div>

                {orderData?.reasonStatusDetails?.reason ? <Alert className="my-2" type="error" banner message={`Cancel Reason : ${orderData?.reasonStatusDetails?.reason}`} /> : null}

                {isLoading ? (
                    <div className="loader_main" style={{ alignItems: "center", height: "50vh" }}><span class="loader2"></span></div>
                ) : (
                    <Row className="order-details-layout">
                        <Col md={8} style={{ paddingRight: isMobile ? "12px" : "7px", marginTop: isMobile ? "10px" : "" }}>
                            <div className="order_details order-details-main">
                                <div className="order_details_title order-summary-card">
                                    <div className="order_del_img order-summary-identity">
                                        <img src={LogImng} alt="Order" />
                                        <div className="order_detials_id">
                                            <div className="order-id-row">
                                                <p>{orderData?.orderCode}</p>
                                                <Tag color={getStatusColor(orderData?.status)}>{getDisplayStatusLabel(orderData?.status)}</Tag>
                                            </div>
                                            <p>Placed on : {orderData?.addedDate}</p>
                                            {orderData?.isPoolOrder ? <Tag bordered={false} color="blue">POOL ORDER</Tag> : null}
                                        </div>
                                    </div>
                                    <div className="order_title_actions order-summary-actions">
                                        <KotDetails orderId={id} />
                                        <InvoiceDetials orderId={id} isLoadInvoice={isLoadInvoice} />
                                    </div>
                                </div>

                                <div className="location-wrapper">
                                    <div className="location_box order-location-card">
                                        <div className="location_header">
                                            <MdStorefront className="delivery_icons" />
                                            <p>Pick-up Location</p>
                                        </div>

                                        <Descriptions column={1} className="location_column">
                                            <Descriptions.Item label="Branch Name">
                                                {orderData?.branchId?.branchName || "N/A"}
                                            </Descriptions.Item>
                                            <Descriptions.Item label="Full Address">
                                                {orderData?.branchId?.fullAddress || "N/A"}
                                            </Descriptions.Item>
                                        </Descriptions>
                                    </div>

                                    {orderData?.deliveryOption !== "PICKUP" && (
                                        <div className="location_box order-location-card">
                                            <div className="location_header">
                                                <MdLocationPin className="delivery_icons" />
                                                <p>Delivery Location</p>
                                            </div>

                                            <Descriptions column={1} className="location_column">
                                                <Descriptions.Item label="Address Type">
                                                    {orderData?.userLocationId?.addressType || "N/A"}
                                                </Descriptions.Item>
                                                <Descriptions.Item label="Full Address">
                                                    {orderData?.userLocationId?.fullAddress || "N/A"}
                                                </Descriptions.Item>
                                            </Descriptions>
                                        </div>
                                    )}
                                </div>

                                <Card
                                    className="card_body card_header order-products-card"
                                    title={
                                        <div className="product_order_item order-products-head">
                                            <p>No. of Item {orderData?.productInfo?.length}</p>
                                            <Space>{orderData?.isPoolOrder ? <Tag color="blue" bordered={false}>POOL ORDER</Tag> : null}
                                                {canEditOrder ?
                                                    <Button
                                                        size={isMobile ? "small" : "middle"}
                                                        type="primary"
                                                        shape="round"
                                                        onClick={handleEditItem}
                                                    >
                                                        Edit Order
                                                    </Button>
                                                    : null}
                                            </Space>
                                        </div>
                                    }>
                                    {/* {isRemove ? (
                                        <div className="order_list_items order_scroll_wrapper">
                                            <List
                                                itemLayout="horizontal"
                                                dataSource={cartItem}
                                                renderItem={(item) => {
                                                    const offerPattern = item.offerQty ? parseOfferPattern(item.offerQty) : null;
                                                    const currentQty = item.unit || 0;

                                                    let displayBillingQty = currentQty;
                                                    let displayFreeQty = 0;

                                                    if (offerPattern && currentQty > 0) {
                                                        const numCombos = Math.floor(currentQty / offerPattern.comboSize);
                                                        displayBillingQty = numCombos * offerPattern.billingPerCombo;
                                                        displayFreeQty = numCombos * offerPattern.freePerCombo;
                                                    }

                                                    return (
                                                        <List.Item
                                                            className={item.status === "REMOVED" || item.unit === 0 ? "remove_items_select" : ""}
                                                            actions={[
                                                                <Space>
                                                                    <div className="price_action">
                                                                        <b>{formatCurrency(getOrderItemAmount(item))}</b>
                                                                        {cartItem.map((cartProduct) =>
                                                                            cartProduct.productCode === item.productCode ? (
                                                                                <Button.Group key={cartProduct.productCode}>
                                                                                    <Button
                                                                                        type="primary"
                                                                                        disabled={cartProduct.unit === 0}
                                                                                        onClick={() => handleDelItem(item)}
                                                                                    >
                                                                                        -
                                                                                    </Button>
                                                                                    <Button type="primary">
                                                                                        {displayBillingQty}
                                                                                        {displayFreeQty > 0 && (
                                                                                            <span style={{ fontSize: '10px', marginLeft: '2px' }}>
                                                                                                +{displayFreeQty}
                                                                                            </span>
                                                                                        )}
                                                                                    </Button>
                                                                                    <Button type="primary" onClick={() => handleAddItem(item)}>
                                                                                        +
                                                                                    </Button>
                                                                                </Button.Group>
                                                                            ) : null
                                                                        )}
                                                                    </div>
                                                                </Space>
                                                            ]}
                                                        >
                                                            <List.Item.Meta
                                                                avatar={
                                                                    item.imageUrl ? (
                                                                        <Image src={item.imageUrl || BKDLogo} className="order_images" width={50} />
                                                                    ) : (
                                                                        <Avatar size={50} shape="square" src={DefaulImg} className="order_images" />
                                                                    )
                                                                }
                                                                title={<p><span>{item.productName}</span></p>}
                                                                description={
                                                                    <div>
                                                                        <Space>
                                                                            <p>{item.packSize}</p>
                                                                            <p>
                                                                                Qty. {displayBillingQty}
                                                                                {displayFreeQty > 0 && (
                                                                                    <span style={{ color: '#52c41a', marginLeft: '4px' }}>
                                                                                        + {displayFreeQty} Free
                                                                                    </span>
                                                                                )}
                                                                            </p>
                                                                            <strong>{formatCurrency(getOrderItemAmount(item))}</strong>
                                                                        </Space>
                                                                        {item.offerProduct && (
                                                                            <div style={{ fontSize: '12px', color: '#1890ff', marginTop: '4px' }}>
                                                                                Offer: {item.offerQty || 'Special Offer'}
                                                                            </div>
                                                                        )}
                                                                    </div>
                                                                }
                                                            />
                                                        </List.Item>
                                                    );
                                                }}
                                            />
                                        </div>
                                    ) : ( */}
                                    <div className="order-product-table-wrap order_list_items">
                                        <Table
                                            columns={orderProductColumns}
                                            dataSource={orderData?.productInfo || []}
                                            rowKey={(item) => item?._id || item?.productCode}
                                            pagination={false}
                                            scroll={{ x: 900 }}
                                            className="order-product-table"
                                        />
                                    </div>
                                    {/* )} */}
                                </Card>

                                <Card className="card_body_properties order-info-card" title="Order Information">
                                    <Descriptions bordered layout="vertical" className="order-info-grid">
                                        <Descriptions.Item label="Alternative Name">{orderData?.alternativeCustomerName || "N/A"}</Descriptions.Item>
                                        <Descriptions.Item label="Alternative Mobile">{orderData?.alternativeMobileNo || "N/A"}</Descriptions.Item>
                                        <Descriptions.Item label="Order Code">{orderData?.orderCode || "N/A"}</Descriptions.Item>
                                        <Descriptions.Item label="Order Source">{getOrderSourceTag(orderData?.orderSource)}</Descriptions.Item>
                                        <Descriptions.Item label="Place Date">{orderData?.addedDate}{orderData?.addedTime ? `, ${orderData?.addedTime}` : ""}</Descriptions.Item>
                                        <Descriptions.Item label="Delivery Date">{orderData?.deliveryDate || "N/A"}</Descriptions.Item>
                                        <Descriptions.Item label="Delivery Slot">{orderData?.timeSlotFrom && orderData?.timeSlotTo ? `${orderData?.timeSlotFrom} - ${orderData?.timeSlotTo}` : "N/A"}</Descriptions.Item>
                                        <Descriptions.Item label="Branch Code">{orderData?.branchCode || "N/A"}</Descriptions.Item>
                                        <Descriptions.Item label="Branch Alias">{orderData?.branchId?.branchAlias || "N/A"}</Descriptions.Item>
                                        <Descriptions.Item label="Payment Status"><Tag color={orderData?.isPaymentDone ? "#7ABA78" : "#387ADF"}>{orderData?.isPaymentDone ? "Done" : "Pending"}</Tag></Descriptions.Item>
                                        <Descriptions.Item label="Delivery Type"><Tag color={orderData?.deliveryOption !== "DELIVERY" ? "#387ADF" : "#7ABA78"}>{orderData?.deliveryOption}</Tag></Descriptions.Item>
                                        <Descriptions.Item label="Payment Mode"><Tag color={orderData?.paymentMode !== "COD" ? "#7ABA78" : "#F57D1F"}>{orderData?.paymentMode}</Tag></Descriptions.Item>
                                        <Descriptions.Item label="Status"><Tag color={getStatusColor(orderData?.status)}>{getDisplayStatusLabel(orderData?.status)}</Tag></Descriptions.Item>
                                    </Descriptions>
                                </Card>

                                {renderReadOnlyItemsCard("Partial Return By User", orderData?.removedByUser?.productInfo)}
                                {renderReadOnlyItemsCard("Partial Return By Branch", orderData?.removedByBranch?.productInfo)}

                                <div>
                                    <Card
                                        title="Edited History"
                                        className="card_body_properties order-data-card"
                                    >
                                        {isOrderHistoryLoading ?
                                            <div className="loader_main">
                                                <span class="loader2"></span>
                                            </div>
                                            :
                                            <Table
                                                columns={editedHistoryColumns}
                                                dataSource={orderEditHistoryData || []}
                                                scroll={{ x: true }}
                                                pagination={false}
                                                rowKey={(item) => item?._id}
                                            />
                                        }
                                    </Card>
                                </div>

                                <Card
                                    title="Transaction History"
                                    className="card_body_properties order-data-card"
                                >
                                    {isLoading ?
                                        <div className="loader_main">
                                            <span class="loader2"></span>
                                        </div>
                                        :
                                        <Table
                                            columns={paymentColumns}
                                            dataSource={orderData?.userPaymentInfo}
                                            scroll={{ x: true }}
                                            pagination={false}
                                            rowKey={(item) => item?._id || item?.paidDateTime}
                                        />}
                                </Card>

                                <Card
                                    title="Order Status Action"
                                    className="card_body_properties order-data-card"
                                >
                                    {isLoading ?
                                        <div className="loader_main">
                                            <span class="loader2"></span>
                                        </div>
                                        :
                                        <Table
                                            columns={statusColumns}
                                            dataSource={orderData?.statusDetails}
                                            scroll={{ x: true }}
                                            pagination={false}
                                            rowKey={(item) => item?._id || `${item?.orderStatus}-${item?.addedDate}-${item?.addedTime}`}
                                        />
                                    }
                                </Card>
                            </div>
                        </Col>

                        <Col md={4} style={{ paddingLeft: "7px", display: "flex", flexDirection: "column", gap: "10px", marginTop: isMobile ? "10px" : "" }}>
                            {orderData?.deliveryOption !== "PICKUP" ? <div className="show_qr_code"><Card className="card_body order-data-card"><QRCode value={orderData?.orderCode} status={!orderData?.isVendorScan ? "active" : "scanned"} /></Card></div> : null}

                            {vendorReturnPin ? (
                                <Card
                                    size="small"
                                    className="vendor-return-pin-card"
                                    styles={{ body: { padding: 12 } }}
                                    style={{
                                        background: "linear-gradient(135deg, #fff7e6 0%, #fff1d6 100%)",
                                        border: "1px solid #ffa940",
                                    }}
                                >
                                    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6, marginBottom: 8 }}>
                                        <ExclamationCircleFilled style={{ color: "#fa8c16", fontSize: 16 }} />
                                        <Typography.Text strong style={{ fontSize: 13 }}>
                                            Delivery Rider Return PIN
                                        </Typography.Text>
                                    </div>
                                    <div style={{ display: "flex", gap: 6, justifyContent: "center", marginBottom: 6 }}>
                                        {String(vendorReturnPin)
                                            .padStart(6, "0")
                                            .split("")
                                            .map((digit, idx) => (
                                                <span
                                                    key={idx}
                                                    style={{
                                                        display: "inline-flex",
                                                        alignItems: "center",
                                                        justifyContent: "center",
                                                        width: 28,
                                                        height: 34,
                                                        borderRadius: 6,
                                                        background: "#fff",
                                                        border: "1px solid #ffa940",
                                                        color: "#d46b08",
                                                        fontSize: 16,
                                                        fontWeight: 700,
                                                    }}
                                                >
                                                    {digit}
                                                </span>
                                            ))}
                                    </div>
                                    <Typography.Text type="secondary" style={{ fontSize: 11, display: "block", textAlign: "center" }}>
                                        Read out this PIN to the delivery rider.
                                    </Typography.Text>
                                </Card>
                            ) : null}

                            <Card size="small" title="Payment Details" className="order-payment-card">
                                <div className="amount_item order-amount-row">
                                    <p><b>MRP Total Amount</b></p>
                                    <p><b>{formatCurrency(orderData?.mrpTotalProductAmount)}</b></p>
                                </div>
                                {orderData?.totalSaving != 0 &&
                                    <div className="amount_item order-amount-row">
                                        <p style={{ color: "#5AC268" }}><b>BKD Discount</b></p>
                                        <p style={{ color: "#5AC268" }}><b>{formatCurrency(orderData?.totalSaving)}</b></p>
                                    </div>
                                }
                                <div className="amount_item order-amount-row">
                                    <p><b> Total Amount  </b></p>
                                    <p><b>{formatCurrency(orderData?.totalProductAmount)}</b></p>
                                </div>
                                {Number(orderData?.discountAmount) > 0 &&
                                    <div className="amount_item order-amount-row">
                                        <p>
                                            Discount / Referral
                                            {orderData?.discountType ? (
                                                orderData?.discountType !== "FLAT"
                                                    ? <span> ({orderData?.discountValue}%)</span>
                                                    : <span> ({formatCurrency(orderData?.discountValue)} off)</span>
                                            ) : null}
                                        </p>
                                        <p>{formatCurrency(orderData?.discountAmount)}</p>
                                    </div>
                                }
                                {(orderData?.couponCode || Number(orderData?.couponDiscountAmount) > 0) &&
                                    <div className="amount_item order-amount-row">
                                        <p>
                                            {orderData?.couponCode ? `Coupon (${orderData?.couponCode})` : "Coupon Applied"}
                                            {orderData?.couponDiscountValueType ? (
                                                orderData?.couponDiscountValueType === "percentage"
                                                    ? <span> ({orderData?.couponDiscountValue}% off)</span>
                                                    : <span> ({formatCurrency(orderData?.couponDiscountValue)} off)</span>
                                            ) : null}
                                        </p>
                                        <p>{formatCurrency(orderData?.couponDiscountAmount)}</p>
                                    </div>
                                }
                                <div className="amount_item order-amount-row">
                                    <p>Delivery Charge  </p>
                                    <p>
                                        {Number(orderData?.deliveryCharge) > 0 ?
                                            formatCurrency(orderData?.deliveryCharge)
                                            :
                                            <span className="offer_product">Free</span>
                                        }
                                    </p>
                                </div>
                                <div className="amount_item order-amount-row payable">
                                    <p><b>Payable Amount  </b></p>
                                    <p><b>{formatCurrency(orderData?.totalPayableAmount)}</b></p>
                                </div>
                            </Card>

                            {orderData?.deliveryOption === "PICKUP" ? (
                                <div className="order_user_info"><Card title="Pickup OTP Verification" className="order-info-card"><Alert type="info" message="Verify OTP given by user to close this order" banner /><div className="my-2"><Popconfirm title="Collect the Payment" description={`Are you sure to receive ${formatCurrency(orderData?.totalPayableAmount)} from the delivery rider?`} onConfirm={() => handleCollectPayment(id, orderData?.totalPayableAmount)} onCancel={() => message.error("You selected No")} okText="Yes" cancelText="No" placement="topLeft"><Button block shape="round" disabled={orderData?.isPaymentDone} className="collect_pay">{formatCurrency(orderData?.totalPayableAmount)} {orderData?.isPaymentDone ? "Collected" : "Collect"}</Button></Popconfirm></div><PickupOtpVerify /></Card></div>
                            ) : null}

                            <Card
                                size="small"
                                title="User Details"
                                className="order-profile-card"
                            >
                                <div className="order-profile-card-row">
                                    <div className="order-profile-img-wrap">
                                        <img
                                            className="order_profile_img"
                                            style={{ objectFit: 'contain' }}
                                            alt="user profile"
                                            src={orderData?.userId?.profilePic || DefaultImg}
                                            onError={(e) => e.currentTarget.src = DefaultImg}
                                        />
                                    </div>
                                    <div className="order-profile-card-details">
                                        <p className="order-profile-card-name">{orderData?.userId?.fullName || "N/A"}</p>
                                        <p>Number : {orderData?.userId?.mobileNo || "N/A"}</p>
                                        <p>Email : {orderData?.userId?.email || "N/A"}</p>
                                        <p>Gender : {orderData?.userId?.gender || "N/A"}</p>
                                        <p>DOB : {orderData?.userId?.dob ? dayjs(orderData?.userId?.dob).format("DD MMM YYYY") : "N/A"}</p>
                                    </div>
                                </div>
                            </Card>

                            <Card className="order-info-card" title="Update Slot">
                                <Form form={form} onFinish={handleSlotChange} onFinishFailed={() => { }} layout="vertical" name="order-assign">
                                    <Form.Item label="Delivery Date" name="deliveryDate" rules={[{ required: true, message: "Please Choose Delivery date" }]}><DatePicker onChange={onDateChange} style={{ width: "100%" }} format="DD/MM/YYYY" disabledDate={disabledDate} /></Form.Item>
                                    <Form.Item label="Delivery Slot" name="branchSlotId" rules={[{ required: true, message: "Please Select Delivery Date" }]}>
                                        <Select placeholder="Select Slot">{slotList?.map((item) => <Select.Option key={item._id} value={item._id}>{item.timeSlotFrom}-{item.timeSlotTo}</Select.Option>)}</Select>
                                    </Form.Item>
                                    <Form.Item style={{ marginBottom: 0 }}><Button loading={isChangeSlot} htmlType="submit" shape="round" block className="submitBtn">Update Delivery Slot</Button></Form.Item>
                                </Form>
                            </Card>

                            {orderData?.deliveryOption !== "PICKUP" ? (
                                <div className="order_user_info">
                                    <div className="vendor_Reassing"><h6>Delivery Rider Details</h6></div>
                                    {orderData?.vendorId != null ? <div className="order_user_title"><OrderInfo vendorData={orderData?.vendorId} ShowOrderList={showOrderList} dispatchStatus={orderData?.status} /></div> : <Card className="card_body order-profile-card"><Empty style={{ padding: "1rem" }} image={Empty.PRESENTED_IMAGE_SIMPLE} description={<div><p className="mb-2">Delivery Rider not assigned</p><VendorAssignModel ShowOrderList={showOrderList} orderId={id} title={orderData?.vendorId != null ? "Reassign Delivery Rider" : "Assign Delivery Rider"} /></div>} /></Card>}
                                </div>
                            ) : null}

                            {orderData?.deliveryOption != "PICKUP" ?
                                <div className="delivered_Image">
                                    <Card
                                        title="Order Delivered Image"
                                        className="order-proof-card"
                                        cover={orderData?.deliveredImage?.length ?
                                            <Image.PreviewGroup items={orderData?.deliveredImage || []}>
                                                <Image
                                                    height={200}
                                                    src={orderData?.deliveredImage?.[0]}
                                                    onError={(e) => e.currentTarget.src = BKDLogo}
                                                />
                                            </Image.PreviewGroup> : <Image
                                                height={200}
                                                src={DefaultImage}
                                            />
                                        }
                                    >
                                    </Card>
                                </div> : null}
                        </Col>
                    </Row>
                )}
            </section>

            <Modal open={isShowOtp} footer={null} onCancel={() => setIsShowOtp(false)} title="Verify OTP">
                <div className="verify_otp_setion">
                    <h5>Verify OTP to Edit This Order</h5>
                    <div className="new_otp_item new_otp_main">
                        <OTPInput value={otp} onChange={setOtp} numInputs={4} inputType="numeric" renderInput={(props) => <Input {...props} style={{ width: "2.5rem", height: "2.5rem", textAlign: "center" }} placeholder="0" inputMode="numeric" />} />
                    </div>
                    <div className="verify_otp_btn"><Button loading={isOtpLoading} type="primary" onClick={otpVerifyHandler}>Submit</Button></div>
                </div>
            </Modal>

            {openRemoveModal ?
                <RemoveItemDetails
                    isRemove={isRemove}
                    ShowOrderList={showOrderList}
                    open={openRemoveModal}
                    setOpen={setOpenRemoveModal}
                    setIsRemove={setIsRemove}
                />
                : null
            }

            {isEditModal &&
                <EditProductsModal
                    open={isEditModal}
                    onClose={toggleEditModal}
                    ShowOrderList={showOrderList}
                    orderDetailsData={orderData || []}
                />
            }

            {openHistoryModal &&
                <EditProductsHistoryModal
                    open={openHistoryModal}
                    onClose={toggleOrderHistoryModal}
                    selectedProducts={selectedProducts || []}
                    historyTitle={historyTitle}
                />
            }
        </>
    );
}

export default OrderDetails;
