const DATE_FORMATS = [
    "DD MMM YYYY",
    "D MMM YYYY",
    "DD MMMM YYYY",
    "D MMMM YYYY",
    "DD/MM/YYYY",
    "D/M/YYYY",
    "DD-MM-YYYY",
    "D-M-YYYY",
    "YYYY-MM-DD",
    "YYYY/MM/DD",
];

const parseOrderDateTime = (dateValue, timeValue) => {
    const dateText = String(dateValue || "").trim();
    const timeText = String(timeValue || "").trim();

    if (!dateText) return null;

    if (timeText) {
        for (const dateFormat of DATE_FORMATS) {
            for (const timeFormat of ["hh:mm A", "h:mm A", "HH:mm"]) {
                const parsed = dayjs(`${dateText} ${timeText}`, `${dateFormat} ${timeFormat}`, true);
                if (parsed.isValid()) return parsed.valueOf();
            }
        }
    }

    for (const dateFormat of DATE_FORMATS) {
        const parsed = dayjs(dateText, dateFormat, true);
        if (parsed.isValid()) return parsed.valueOf();
    }

    const fallbackParsed = dayjs(timeText ? `${dateText} ${timeText}` : dateText);
    return fallbackParsed.isValid() ? fallbackParsed.valueOf() : null;
};

const getObjectIdTimestamp = (id) => {
    if (typeof id !== "string" || !/^[a-f\d]{24}$/i.test(id)) return null;
    return parseInt(id.slice(0, 8), 16) * 1000;
};

const getOrderLatestSortValue = (order) => (
    parseOrderDateTime(order?.addedDate, order?.addedTime)
    ?? getObjectIdTimestamp(order?._id)
    ?? 0
);

const getOrderDeliverySortValue = (order) => (
    parseOrderDateTime(order?.deliveryDate, order?.timeSlotFrom)
    ?? Number.MAX_SAFE_INTEGER
);

const compareOrdersByLatest = (a, b) => {
    const dateDiff = getOrderLatestSortValue(b) - getOrderLatestSortValue(a);
    if (dateDiff !== 0) return dateDiff;
    return String(b?.orderCode || "").localeCompare(String(a?.orderCode || ""));
};

const compareOrdersByEarliest = (a, b) => {
    const dateDiff = getOrderLatestSortValue(a) - getOrderLatestSortValue(b);
    if (dateDiff !== 0) return dateDiff;
    return String(a?.orderCode || "").localeCompare(String(b?.orderCode || ""));
};

const compareOrdersByDeliveryTime = (a, b) => {
    const deliveryDiff = getOrderDeliverySortValue(a) - getOrderDeliverySortValue(b);
    if (deliveryDiff !== 0) return deliveryDiff;
    return compareOrdersByLatest(a, b);
};

const sortOrdersByMode = (orders = [], sortMode) => {
    const ordersToSort = [...orders];
    if (sortMode === ORDER_SORT_TYPES.EARLIEST) {
        ordersToSort.sort(compareOrdersByEarliest);
    } else if (sortMode === ORDER_SORT_TYPES.DELIVERY_TIME) {
        ordersToSort.sort(compareOrdersByDeliveryTime);
    } else {
        ordersToSort.sort(compareOrdersByLatest);
    }
    return ordersToSort;
};

