import React, { useEffect, useState } from 'react';
import { Button, Modal, Skeleton, Spin } from 'antd';
import { fetchBillAllDetails, fetchKotAllDetails } from '../../service/api_services';
import KOT from './KOT';
import { HiOutlineDownload } from 'react-icons/hi';
import { useAuth } from '../../authentication/context/authContext';
import { useLocation } from 'react-router-dom';
import InvoiceFormate from './InvoiceFormate';
import { useScreen } from '../../authentication/context/AuthScreen';



const InvoiceDetials = ({ orderId, isLoadInvoice }) => {
    const { screenWidth } = useScreen();
    const location = useLocation()
    console.log("location", location)
    const { token } = useAuth()
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [kotData, setKotData] = useState([]);
    const [isLoading, setIsLoading] = useState(false)
    const showModal = () => {
        setIsModalOpen(true);
    };
    const handleOk = () => {
        setIsModalOpen(false);
    };
    const handleCancel = () => {
        setIsModalOpen(false);
    };


    const ShowKotDetails = async () => {
        setIsLoading(true)

        try {
            await fetchBillAllDetails(token, orderId)
                .then((res) => {
                    console.log("bill info", res);
                    if (res.status == 200) {
                        setKotData(res.data.data);
                        setIsLoading(false)
                    }
                })
                .catch((err) => {
                    console.log(err.message);
                    setIsLoading(false)

                });
        } catch (error) {
            console.log(error);
            setIsLoading(false)
        }
    };

    useEffect(() => {
        ShowKotDetails();
    }, []);


    return (
        <>
            <Button
                size={screenWidth < 768 ? "small" : "middle"}
                disabled={!isLoadInvoice}
                onClick={showModal}
                shape="round"
            >
                Print Invoice
            </Button>

            <Modal style={{
                top: 20,
            }} width={800} footer={false}
                open={isModalOpen} onOk={handleOk} onCancel={handleCancel}>
                <div className="bill-container">
                    {isLoading ? <Skeleton active /> : <InvoiceFormate data={kotData} handleCancel={handleCancel} />}
                </div>
            </Modal>
        </>
    );
};

export default InvoiceDetials