
import React, { useEffect, useState, useRef } from 'react';
import { Avatar, Button, Form, Input, List, message, Modal, Spin } from 'antd';
import "../../style/order.css";
import { fetchAllDeliveryBoyList, OrderAssignToVendor, vendorReassignVerify, VendorTrackData } from '../../service/api_services';
import { Collapse, Steps } from 'antd';
import { useAuth } from '../../authentication/context/authContext';
import dayjs from 'dayjs';
import OtpInput from "react-otp-input";
import customParseFormat from "dayjs/plugin/customParseFormat";
import { HiSearch } from 'react-icons/hi';
import { MdLocationOn } from 'react-icons/md';

dayjs.extend(customParseFormat);


const VendorAssignModel = ({ orderId, status, ShowOrderList, title, dispatchStatus }) => {
    const { token, role } = useAuth();
    const [isvendorAssign, setIsVendorAssign] = useState(false)
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [venderData, setVendorData] = useState([]); // Delivery boy list
    const [vendorId, setVendorId] = useState(null); // Selected vendor
    const [partnerTrack, setPartnerTrack] = useState([]);
    const [isShowOtp, setIsShowOtp] = useState(false);
    const [otp, setOtp] = useState(null)
    const [isOtp, setSetOtp] = useState(null)
    const [searchVendor, setSearchVendor] = useState("");
    const focusOtp = useRef()


    const showPartnerTracData = async () => {
        try {
            const res = await VendorTrackData(token, orderId);
            console.log("vendor track", res);
            setPartnerTrack(res.data.data.vendorReAssginList || []);
            setIsShowOtp(res.data.data.isOtpScreen || false);
        } catch (error) {
            console.log(error);
        }
    };



    const stepItems = partnerTrack.map((item, index) => ({
        title: `From : ${item.fromVendorName || "N/A"} - To : ${item.toVendorName || "N/A"}`,
        description: `Assigned on: ${item.addedDate ? dayjs(item.addedDate, "DD/MM/YYYY, hh:mm A").format("DD MMM YYYY, hh:mm A") : "N/A"}`,
    }));




    console.log("filterDelvieryPartner".filterDelvieryPartner)



    // Show Modal and load initial data
    const showModal = () => {
        setIsModalOpen(true);
        ShowDeliveryBoyList(); // Fetch data when page updates
        showPartnerTracData();

    };

    const handleCancel = () => {
        setIsModalOpen(false);
    };


    const ShowDeliveryBoyList = async () => {

        setIsLoading(true);
        try {
            const res = await fetchAllDeliveryBoyList(token);
            console.log("res", res)
            if (res?.data?.data) {
                const newData = res.data.data;
                setVendorData(newData)
            }
        } catch (error) {
            console.log('Error:', error.message);
        } finally {
            setIsLoading(false);
        }
    };




    const assignVendorHandler = async () => {
        setIsVendorAssign(true)
        const body = {
            userOrderId: orderId,
            vendorId: vendorId,
        };
        try {
            const res = await OrderAssignToVendor(body, token);

            if (res.status === 201) {
                if (dispatchStatus === "DISPATCHED") {
                    showPartnerTracData();
                    setIsVendorAssign(false)
                } else {
                    message.success(res.data.message);
                    setIsModalOpen(false);
                    setVendorId(null);
                    ShowOrderList();
                    setIsVendorAssign(false)
                }
            } else if (res.status === 200) {
                if (dispatchStatus === "DISPATCHED") {
                    showPartnerTracData();
                    setIsVendorAssign(false)
                } else {
                    message.info(res.data.message);
                    setIsVendorAssign(false)
                }


            }
        } catch (error) {
            console.log(error);
            setIsVendorAssign(false)

        }
    };

    const OtpVerifyHandler = async () => {
        setSetOtp(true)
        const body = {
            userOrderId: orderId,
            reAssignOtp: otp,
        };
        try {
            const res = await vendorReassignVerify(body, token);
            if (res.status === 201) {
                message.success(res.data.message);
                setIsModalOpen(false);
                setVendorId(null);
                ShowOrderList();
                setSetOtp(false)
            } else if (res.status === 200) {
                message.info(res.data.message);
                setSetOtp(false)
            }
        } catch (error) {
            console.log(error);
            setSetOtp(false)

        }
    };

    const handleShowModal = () => {
        if (status === "ASSIGNED") {
            message.error("Please Accept This Order First");
        } else {
            showModal()
        }
    }

    const filterDeliveryPartner = venderData?.filter((vendor) =>
        vendor.fullName?.toLowerCase().includes(searchVendor.toLowerCase())
    );

    // Observer to detect when scrolling reaches the bottom
    useEffect(() => {
        if (focusOtp.current) {
            focusOtp.current.focus();
        }
    }, []);

    const openVendorLocation = (lat, lng) => {
        if (!lat || !lng) return;

        window.open(`https://www.google.com/maps?q=${lat},${lng}`, "_blank");
        // window.open(`https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}`, "_blank");
    };

    return (
        <div className='vendor_list'>
            <Button disabled={title === "Reassign Delivery Rider" && !(role === "BranchAdmin" || role === "BranchManager")} className='reassing_vendor' onClick={() => handleShowModal()} shape='round'>
                {title}
            </Button>

            <Modal
                style={{
                    top: 20
                }}
                title="Delivery Rider List"
                open={isModalOpen}
                onCancel={handleCancel}
                footer={false}
            >
                <div className="vendor_search_box">
                    <Input
                        placeholder="Search Delivery Rider..."
                        prefix={<HiSearch style={{ color: 'rgba(0,0,0,.25)' }} />}
                        value={searchVendor}
                        onChange={(e) => setSearchVendor(e.target.value)}
                        allowClear
                    />
                </div>
                <div className="vendor_track">
                    {partnerTrack.length === 0 ? (
                        null
                    ) : (
                        <Collapse expandIconPosition='right' style={{ marginBottom: '5px' }}>
                            <Collapse.Panel header="Delivery Rider Tracks" key="1">
                                <Steps
                                    className='custom-steps'
                                    progressDot
                                    current={partnerTrack.length - 1} // last step as current

                                    direction="vertical"
                                    items={stepItems}
                                />
                            </Collapse.Panel>
                        </Collapse>

                    )}
                </div>
                {isShowOtp ? <div className='verify_otp_setion'>
                    <h5>Verify OTP </h5>
                    {/* <p><span>(Ask the OTP previous delivery partner to verify  )</span></p> */}
                    <div className="new_otp_item">
                        <OtpInput
                            value={otp}
                            onChange={setOtp}
                            numInputs={4}
                            placeholder={0}
                            inputType="numeric"
                            // renderSeparator={<span>-</span>}
                            renderInput={(props, index) => (
                                <div className="otp_field">

                                    <Input ref={focusOtp}  {...props} style={{ width: "2.5rem", height: "2.5rem" }} placeholder="0" variant="filled"
                                        // type="number"
                                        inputMode="numeric"
                                        pattern="[0-9]*" />

                                </div>
                            )}
                        />
                    </div>
                    <div className="verify_otp_btn">
                        <Button loading={isOtp} type='primary' onClick={() => OtpVerifyHandler()}>Submit</Button>
                    </div>

                </div> :
                    <div className="vendor_modal_body">
                        <div className="vendor_scroll_area">
                            <List
                                loading={isLoading}
                                itemLayout="horizontal"
                                dataSource={filterDeliveryPartner}
                                renderItem={(item, index) => (
                                    <List.Item
                                        // Attach observer to last item
                                        actions={[
                                            <div className={vendorId === item._id ? "assign_btn" : ""}>
                                                <Button onClick={() => setVendorId(item._id)}>
                                                    {vendorId === item._id ? "Selected" : "Select"}
                                                </Button>
                                            </div>
                                        ]}
                                    >
                                        <List.Item.Meta
                                            avatar={
                                                <Avatar
                                                    src={
                                                        item.profilePic != null
                                                            ? item.profilePic
                                                            : `https://api.dicebear.com/7.x/miniavs/svg?seed=${item._id}`
                                                    }
                                                    size={40}
                                                />
                                            }
                                            title={<p>{item.fullName}</p>}
                                            description={
                                                <div>
                                                    <p>Num Orders Assigned: {item.totalOrderAssigned} </p>

                                                    {item?.vendorLiveLocation?.lat && item?.vendorLiveLocation?.long ? (
                                                        <div
                                                            className="vendor-location-info"
                                                            onClick={() =>
                                                                openVendorLocation(item?.vendorLiveLocation?.lat, item?.vendorLiveLocation?.long)
                                                            }
                                                        >
                                                            <MdLocationOn />

                                                            <div className="vendor-location-details">
                                                                <span>Distance: {item?.distanceFromBranchKm?.toFixed(2)} km away</span>
                                                                <small>Last updated: {item.vendorLiveLocation?.updatedAt ? dayjs(item.vendorLiveLocation?.updatedAt).format("DD MMM YYYY, hh:mm A") : "N/A"}</small>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <div className="vendor-location-info no-location">
                                                            <MdLocationOn style={{ color: 'rgba(0,0,0,0.25)' }} />
                                                            <span>No live location available</span>
                                                        </div>
                                                    )}
                                                </div>
                                            }
                                        />
                                    </List.Item>
                                )}
                            />
                            {/* {isLoading && <div className='text-center'><Spin /></div>}
                    {!hasMore && <div>No more data</div>} */}
                        </div>

                        {filterDeliveryPartner?.length !== 0 && (
                            <div className="vendor_fixed_footer assign_vendor">
                                {filterDeliveryPartner?.length != 0 &&
                                    <Button
                                        loading={isvendorAssign}
                                        onClick={() => assignVendorHandler()}
                                        style={{ width: '100%' }}
                                    >
                                        Assign Delivery Rider
                                    </Button>
                                }
                            </div>
                        )}
                    </div>
                }
            </Modal>
        </div>
    );
};

export default VendorAssignModel;
