export const downloadCsvFile = (fileName, columns, rows) => {
  const safeColumns = Array.isArray(columns) ? columns : [];
  const safeRows = Array.isArray(rows) ? rows : [];

  const escapeCsvValue = (value) => {
    if (value === null || value === undefined) {
      return "";
    }

    const stringValue = String(value);
    const escapedValue = stringValue.replace(/"/g, '""');
    return /[",\n]/.test(escapedValue) ? `"${escapedValue}"` : escapedValue;
  };

  const headerRow = safeColumns
    .map((column) => escapeCsvValue(column.header))
    .join(",");
  const dataRows = safeRows.map((row) =>
    safeColumns.map((column) => escapeCsvValue(row?.[column.key])).join(",")
  );

  const csvContent = ["\uFEFF" + headerRow, ...dataRows].join("\n");
  const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
  const downloadUrl = window.URL.createObjectURL(blob);
  const link = document.createElement("a");

  link.href = downloadUrl;
  link.setAttribute("download", fileName);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  window.URL.revokeObjectURL(downloadUrl);
};
