import { Card, message, Skeleton } from 'antd'
import React, { useEffect, useState } from 'react'
import { Col, Row } from 'react-bootstrap'
import './dashboard.css'
import CountUp from 'react-countup'
import DelImg from '../../assest/png/delivery.gif'
import BKDLogo from '../../assest/chat/logo.png'
import { fetchDashboardCount } from '../../service/api_services'
import { useAuth } from '../../authentication/context/authContext'
import COUNTBG from "../../assest/png/dashboard_card_bg.png"



function UserData() {
    const { token } = useAuth()

    const [countData, setCountData] = useState([])
    console.log("countData", countData)
    const [isCountLoading, setIsCountLoading] = useState(false)

    const userChartInfo = [
        {
            id: 1,
            title: "Pending",
            count: countData?.deliveryOrders?.pending ?? 0,
            url: DelImg,
        },
        {
            id: 2,
            title: "Accepted",
            count: countData?.deliveryOrders?.accepted ?? 0,
            url: DelImg
        },
        {
            id: 3,
            title: "Order Packed",
            count: countData?.deliveryOrders?.orderPacked ?? 0,
            url: DelImg

        },
        {
            id: 4,
            title: "Dispatched",
            count: countData?.deliveryOrders?.dispatched ?? 0,
            url: DelImg
        },
        {
            id: 5,
            title: "Reached",
            count: countData?.deliveryOrders?.reached ?? 0,
            url: DelImg
        },
    ]

    async function fetchCountData() {
        setIsCountLoading(true)
        try {
            const response = await fetchDashboardCount(token)
            if (response.status === 200) {
                console.log(response)
                setCountData(response.data.data)
                setIsCountLoading(false)
            }
        } catch (error) {
            message.error(error);
            setIsCountLoading(false)
        }
    }

    useEffect(() => {
        fetchCountData()
    }, [])

    return (
        <div className='show_user_chat'>
            <Row gutter={[16, 16]}>
                {userChartInfo.map((item) => (
                    <Col
                        xs={12}
                        sm={12}
                        md={8}
                        lg={6}
                        xl={6}
                        className="dashboard_col"
                    >
                        <div className="user_counts">

                            {isCountLoading ? (
                                <div>
                                    <Skeleton.Button active block style={{ height: 120 }} />
                                </div>
                            ) : (
                                <Card hoverable>
                                    <>
                                        <div className='user_data_item'>
                                            <div className="user_chart_logo">
                                                <img
                                                    src={item.url || BKDLogo}
                                                    onError={(e) => e.currentTarget.src = BKDLogo}
                                                />
                                            </div>
                                            <div className="user_chart_text">
                                                <p>{item.title}</p>
                                                {/* <p>{item.count}</p> */}
                                                <CountUp delay={1} end={item.count} style={{ fontSize: "1.5rem", fontWeight: "600" }} />
                                            </div>
                                        </div>
                                        <div className="order_car_design">
                                            <img
                                                src={COUNTBG}
                                            />
                                        </div>
                                    </>
                                </Card>
                            )}
                        </div>
                    </Col>
                )
                )}
            </Row>
        </div >
    )
}

export default UserData