import React, { useEffect, useState } from 'react';
import "./dashboard.css"
import { UploadOutlined, UserOutlined, VideoCameraOutlined } from '@ant-design/icons';
import { Badge, Drawer, Input, Layout, Menu, message, Space, theme } from 'antd';
import SideBarList from '../sidebar/SideBarList';
import { Navigate, Outlet } from 'react-router-dom';
import { useAuth } from '../../authentication/context/authContext';
import { fetchOutstandingBalance, fetchUserProfile } from '../../service/api_services';
import { useCurrentUser } from '../../authentication/context/userContext';
import { useScreen } from '../../authentication/context/AuthScreen';
import { MenuOutlined } from "@ant-design/icons";
import SidebarContent from '../sidebar/SidebarContent';
const { Header, Content, Footer, Sider } = Layout;
const items = [UserOutlined, VideoCameraOutlined, UploadOutlined, UserOutlined].map(
  (icon, index) => ({
    key: String(index + 1),
    icon: React.createElement(icon),
    label: `nav ${index + 1}`,
  }),
);
const MainLayout = () => {
  const { screenWidth } = useScreen();
  const { logout, branchData, token, login, getRole, getPermissions, getBranchData } = useAuth()
  const { userProfileInfo } = useCurrentUser()
  const [colorChange, setColorchange] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [balance, setBalance] = useState([])
  const [drawerOpen, setDrawerOpen] = useState(false);
  const isMobile = screenWidth < 768;

  const accessToken = new URLSearchParams(window.location.search).get("code");
  const accessBracnhName = new URLSearchParams(window.location.search).get("branchName");
  const accessBranchCode = new URLSearchParams(window.location.search).get("branchCode");

  console.log("accessToken", accessToken)

  useEffect(() => {
    if (accessToken) {
      login(accessToken);
      localStorage.setItem("token", accessToken);
      localStorage.setItem("branchData", JSON.stringify({ branchCode: accessBranchCode, branchName: accessBracnhName }));
      getBranchData({ branchCode: accessBranchCode, branchName: accessBracnhName })
    }
  }, [accessToken])

  useEffect(() => {
    // Event listener for online/offline changes
    const handleOnlineStatusChange = () => {
      setIsOnline(navigator.onLine);
    };

    // Add event listeners when the component mounts
    window.addEventListener('online', handleOnlineStatusChange);
    window.addEventListener('offline', handleOnlineStatusChange);

    // Remove event listeners when the component unmounts
    return () => {
      window.removeEventListener('online', handleOnlineStatusChange);
      window.removeEventListener('offline', handleOnlineStatusChange);
    };
  }, []);

  const showOutStandingBalance = async () => {
    try {
      await fetchOutstandingBalance(token).then((res) => {
        console.log("out statnding ", res)
        if (res.status === 200) {
          setBalance(res.data.data)
        } else if (res.data === 283) {
          message.error(res.data.message)
          logout()
        }
      }).catch((err) => {
        console.log(err.message)
      })
    } catch (error) {
      console.log(error)
    }
  }

  useEffect(() => {
    showOutStandingBalance()
  }, [])

  const ShowProfileInfo = async () => {
    try {
      await fetchUserProfile(token)
        .then((res) => {
          console.log("user profile", res);
          if (res.status == 200) {
            userProfileInfo(res.data.data)
            const fetchData = res.data.data
            localStorage.setItem('role', fetchData?.role?.rolename);
            getRole(fetchData?.role?.rolename);
            localStorage.setItem('permissions', JSON.stringify(fetchData.role?.permissions));
            getPermissions(fetchData.role?.permissions);
            localStorage.setItem("userData", JSON.stringify(res.data.data));
          } else if (res.status == 283) {
            logout()
          }

        })
        .catch((err) => {
          console.log(err.message);
        });
    } catch (error) {
      console.log(error);
    }
  };

  useEffect(() => {
    if (token) {
      ShowProfileInfo();
    }
  }, [token]);

  const {
    token: { colorBgContainer, borderRadiusLG },
  } = theme.useToken();

  if (!token) {
    return <Navigate replace to="/" />;
  } else {



    return (
      <div className='main_layout'>
        <Layout >
          {isMobile ? (
            <Drawer
              placement="left"
              open={drawerOpen}
              onClose={() => setDrawerOpen(false)}
              bodyStyle={{ padding: 0 }}
              width={260}
            >
              <SidebarContent setDrawerOpen={setDrawerOpen} />
            </Drawer>
          ) : (
            <SideBarList />
          )}
          <Layout style={{ background: '#f5f5f5' }}>
            {isMobile && (
              <Header
                className={
                  colorChange
                  && "colorChange"
                }
                style={{
                  position: 'sticky',
                  top: 0,
                  zIndex: 3,
                  display: 'flex',
                  alignItems: 'center',
                  padding: 0,
                  background: colorBgContainer,
                }}
              >
                <div className="head_menu">
                  <button className="mobile_menu_btn" onClick={() => setDrawerOpen(true)} type="button">
                    <MenuOutlined />
                  </button>

                  <div className="head_branch_chip">
                    <span>{branchData?.branchCode || "Branch"}</span>
                    <p>{branchData?.branchName}</p>
                  </div>
                  {/* <div className="logged_user">
                    {isOnline && <Space  >
                      <img src='https://cdn-icons-png.freepik.com/512/211/211762.png' />
                      <p>Outstanding balance</p> :
                      <p><span>₹</span> <CountUp delay={1} end={balance?.outStandingBalance} /></p>
                    </Space>}
                  </div> */}
                </div>
              </Header>
            )}
            <Content
              // style={{
              //   margin: '0 16px',
              //   marginTop: "1rem",
              //   marginBottom: "1rem"
              // }}
            >
              <div
                style={{
                  padding: isMobile ? 14 : 24,
                  background: colorBgContainer,
                  borderRadius: borderRadiusLG,
                  // background: "#ECF3FE",
                  minHeight: 500,
                }}
              >
                <Outlet />
              </div>
            </Content>

          </Layout>
        </Layout>
      </div>
    );
  }
};
export default MainLayout;
