import React, { useEffect, useState } from "react";
import {
  Alert,
  Avatar,
  Breadcrumb,
  Button,
  Card,
  Descriptions,
  Divider,
  Empty,
  Image,
  List,
  message,
  Modal,
  Space,
  Table,
  Tag,
  Typography,
} from "antd";
import "../../style/order.css";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import { Col, Row } from "react-bootstrap";
import { HiArrowNarrowLeft, HiOutlineShoppingBag } from "react-icons/hi";
import { fetchOrderDetails, fetchOrderEditHistory } from "../../service/api_services";
import { useAuth } from "../../authentication/context/authContext";
import InvoiceDetials from "../OrderManage/InvoiceDetials";
import DefaultImg from "../../assest/chat/user.png";
import LogImng from "../../assest/png/logoIcon.png";
import DefaultImage from "../../assest/png/default-image.jpg";
import BKDLogo from "../../assest/icon/bkd logo (1).png";
import dayjs from "dayjs";
import { InfoCircleOutlined } from "@ant-design/icons";
import EditProductsHistoryModal from "../OrderManage/EditProductsHistoryModal";
import { getDisplayStatusLabel } from "../../utils/statusDisplay";
import OrderComplaintAction from "../OrderManage/OrderComplaintAction";

function OrderHistoryDetails() {
  const navigate = useNavigate();
  const location = useLocation();
  const { id } = useParams();
  const { token, logout } = useAuth();
  const { Title, Text } = Typography;

  const [orderData, setOrderData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isOrderHistoryLoading, setIsOrderHistoryLoading] = useState(false);
  const [orderEditHistoryData, setOrderEditHistoryData] = useState([]);
  const [openHistoryModal, setOpenHistoryModal] = useState(false);
  const [selectedProducts, setSelectedProducts] = useState([]);
  const [historyTitle, setHistoryTitle] = useState("");

  const toggleOrderHistoryModal = () => setOpenHistoryModal(!openHistoryModal)

  const handleOpenHistoryProducts = (products, title) => {
    setSelectedProducts(products || []);
    setHistoryTitle(title)
    toggleOrderHistoryModal();
  };

  const getOrderSourceTag = (orderSource) => (
    <Tag color={orderSource === "WEB" ? "geekblue" : "green"}>
      {orderSource || "APP"}
    </Tag>
  );

  const formatCurrency = (value) => {
    const amount = Number(value);
    return Number.isFinite(amount) ? `Rs. ${amount.toFixed(2)}` : "Rs. 0.00";
  };

  const getOrderListStatus = (status) => {
    const statusColors = {
      RETURNVENDORASSIGNED: "#EB5B00",
      REPLACEVENDORACCEPTED: "#FFA24C",
      RETURNACCEPTED: "#90D26D",
      REPLACEACCEPTED: "#90D26D",
      REPLACEASSIGNED: "#0D92F4",
      RETURNVENDORACCEPTED: "#FFA24C",
      RETURNASSIGNED: "#0D92F4",
      REPLACEREJECTED: "#FF204E",
      RETURNREJECTED: "#FF204E",
      REPLACED: "#347928",
      RETURNED: "#347928",
      PENDING: "#686D76",
      ACCEPTED: "#7ABA78",
      ORDERPACKED: "#03AED2",
      ASSIGNED: "#10375C",
      DISPATCHED: "#FFAF61",
      REACHED: "#7E60BF",
      DELIVERED: "#059212",
      PARTIALDELIVERED: "#87A922",
      CANCELLED: "#EE4E4E",
      CLOSED: "#C62E2E",
    };

    return statusColors[status] || "#B3A398";
  };

  const getOrderItemAmount = (item) => {
    const amount = Number(item?.offerProduct ? item?.requiredOfferedBillingPrice : item?.bkdAmount);
    return Number.isFinite(amount) ? amount : 0;
  };

  const paymentColumns = [
    {
      title: "Pay Action",
      dataIndex: "actionOn",
      key: "actionOn",
      render: (actionOn) => (
        <Tag bordered={false} color={actionOn !== "ORDER" ? "red" : "green"}>
          {actionOn}
        </Tag>
      ),
    },
    {
      title: "Payment Date",
      dataIndex: "paidDateTime",
      key: "paidDateTime",
      render: (paidDateTime) => <span>{paidDateTime || "N/A"}</span>,
    },
    {
      title: "Payment Mode",
      dataIndex: "paymentMode",
      key: "paymentMode",
      render: (paymentMode) => <span>{paymentMode || "N/A"}</span>,
    },
    {
      title: "Status",
      dataIndex: "status",
      key: "status",
      render: (_, { status }) => <Tag color={status === "success" ? "blue" : "#059212"}>{status}</Tag>,
    },
  ];

  const editedHistoryColumns = [
    {
      title: "Old Product Count",
      dataIndex: "oldProductInfo",
      key: "oldProductInfo",
      render: (oldProductInfo) => (
        <Space>
          <span>{oldProductInfo?.length || "0"}</span>
          <div
            style={{ cursor: 'pointer', color: "#1677ff" }}
            onClick={() => handleOpenHistoryProducts(oldProductInfo, "Old Product List")}
          >
            <InfoCircleOutlined />
          </div>
        </Space>
      ),
    },
    {
      title: "New Product Count",
      dataIndex: "newProductInfo",
      key: "newProductInfo",
      render: (newProductInfo) => (
        <Space>
          <span>{newProductInfo?.length || "0"}</span>
          <div
            style={{ cursor: 'pointer', color: "#1677ff" }}
            onClick={() => handleOpenHistoryProducts(newProductInfo, "New Product List")}
          >
            <InfoCircleOutlined />
          </div>
        </Space>
      ),
    },
    {
      title: "Edited Date",
      dataIndex: "modifiedDate",
      key: "modifiedDate",
      render: (modifiedDate) => <span>{modifiedDate ? dayjs(modifiedDate).format("DD MMM YYYY, hh:mm A") : "N/A"}</span>,
    },
    {
      title: "Old Total Payment",
      dataIndex: "oldPaymentDetails",
      key: "oldPaymentDetails",
      render: (oldPaymentDetails) => <span>{formatCurrency(oldPaymentDetails.totalPayableAmount)}</span>,
    },
    {
      title: "New Total Payment",
      dataIndex: "newPaymentDetails",
      key: "newPaymentDetails",
      render: (newPaymentDetails) => <span>{formatCurrency(newPaymentDetails.totalPayableAmount)}</span>,
    },
  ];

  const getActionByLabel = (value) => {
    if (value === "VENDOR") {
      return "Delivery Rider";
    }

    return value || "N/A";
  };

  const statusColumns = [
    {
      title: "Order Status",
      dataIndex: "orderStatus",
      key: "orderStatus",
      render: (orderStatus) => (
        <Tag bordered={false} color={getOrderListStatus(orderStatus)}>
          {getDisplayStatusLabel(orderStatus)}
        </Tag>
      ),
    },
    {
      title: "Name",
      dataIndex: "addedName",
      key: "addedName",
      render: (value) => <span>{value || "N/A"}</span>,
    },
    {
      title: "Action Date",
      dataIndex: "addedDate",
      key: "addedDate",
      render: (value) => <span>{value || "N/A"}</span>,
    },
    {
      title: "Action Time",
      dataIndex: "addedTime",
      key: "addedTime",
      render: (value) => <span>{value || "N/A"}</span>,
    },
    {
      title: "Action By",
      dataIndex: "addedVia",
      key: "addedVia",
      render: (value) => <span>{getActionByLabel(value)}</span>,
    },
  ];

  const orderProductColumns = [
    {
      title: "Img",
      dataIndex: "imageUrl",
      key: "imageUrl",
      width: 88,
      render: (_, item) =>
        item?.imageUrl ? (
          <Image
            src={item.imageUrl}
            alt={item?.productName || "Product"}
            preview={false}
            className="order_images"
            width={50}
            height={50}
            fallback={BKDLogo}
          />
        ) : (
          <Avatar size={50} shape="square" src={BKDLogo} className="order_images" />
        ),
    },
    {
      title: "Product Name",
      dataIndex: "productName",
      key: "productName",
      render: (_, item) => (
        <div className="order-table-name-cell">
          <div className="order-table-name-title">
            <span>{item?.productName}</span>
            {item?.isRefridgerator ? (
              <Tag icon={<HiOutlineShoppingBag className="bags" />} color="blue" bordered={false}>
                Frozen
              </Tag>
            ) : (
              <Tag icon={<HiOutlineShoppingBag className="bags" />} bordered={false}>
                Normal
              </Tag>
            )}
          </div>
          <div className="order-table-name-meta">
            <span>{item?.packSize || "N/A"}</span>
          </div>
          <div className="order-table-alerts">
            <Alert banner message="Return" type={!item?.nonReturnable ? "success" : "error"} showIcon />
            <Alert banner message="Replace" type={!item?.nonReplaceable ? "success" : "error"} showIcon />
          </div>
          {item?.offerProduct ? (
            <div className="order-offer-line">
              <div className="order-offer-title">{item.offerProduct.productName}</div>
              <div className="order-product-meta-row order-offer-meta">
                <span>{item.offerProduct.packSize}</span>
                <span>Qty. {item.offerProduct.quantity}</span>
                <span><del>{formatCurrency(item.offerProduct.mrpPrice)}</del></span>
                {Number(item.offerProduct.productPrice) === 0 ? <span className="offer_product">Free</span> : null}
              </div>
            </div>
          ) : null}
        </div>
      ),
    },
    {
      title: "Qty",
      dataIndex: "quantity",
      key: "quantity",
      width: 80,
      render: (qty) => <span>{qty}</span>,
    },
    {
      title: "MRP",
      key: "mrpPrice",
      width: 120,
      render: (_, item) => <span><del>{formatCurrency(item?.mrpPrice)}</del></span>,
    },
    {
      title: "Sell Price",
      key: "productPrice",
      width: 120,
      render: (_, item) => <span>{formatCurrency(item?.productPrice)}</span>,
    },
    {
      title: "Total Amount",
      key: "totalAmount",
      width: 150,
      render: (_, item) => (
        <div className="order-table-total-cell">
          {item?.status === "REMOVED" || item?.status === "RETURN" || item?.status === "REPLACE" ? (
            <Tag color={item.status === "RETURN" ? "orange" : item.status === "REMOVED" ? "red" : "blue"}>
              {item.status}
            </Tag>
          ) : null}
          <span>{formatCurrency(getOrderItemAmount(item))}</span>
        </div>
      ),
    },
  ];

  const showOrderList = async () => {
    setIsLoading(true);
    try {
      const res = await fetchOrderDetails(token, id);
      if (res?.status === 200) {
        setOrderData(res.data.data);
      } else if (res?.data?.code === 283) {
        message.error(res.data.message);
        logout();
      }
    } catch (error) {
      console.log(error);
      message.error(error?.message || "Failed to fetch order details");
    } finally {
      setIsLoading(false);
    }
  };

  const showOrderEditHistory = async () => {
    if (!token) return;
    setIsOrderHistoryLoading(true);
    try {
      const res = await fetchOrderEditHistory(token, id);
      if (res.status === 200) {
        const productItem = res.data.data.list || [];
        setOrderEditHistoryData(productItem);
      } else if (res.data.code === 283) {
        message.error(res.data.message);
        logout();
      }
    } catch (error) {
      message.error(error?.message || "Unable to fetch order details");
    } finally {
      setIsOrderHistoryLoading(false);
    }
  };

  useEffect(() => {
    showOrderList();
    showOrderEditHistory();
  }, []);

  const renderReadOnlyItemsCard = (title, items) => {
    if (!items?.length) {
      return null;
    }

    return (
      <Card className="card_body card_header order-products-card" style={{ margin: "10px" }} title={title}>
        <div className="product_iten_list order_scroll_wrapper">
          <List
            itemLayout="horizontal"
            dataSource={items}
            renderItem={(item) => (
              <List.Item className="order-line-item remove_items_select">
                <List.Item.Meta
                  avatar={
                    item?.imageUrl ? (
                      <Image
                        src={item.imageUrl}
                        alt={item?.productName || "Product"}
                        preview={false}
                        className="order_images"
                        width={50}
                        height={50}
                        fallback={BKDLogo}
                      />
                    ) : (
                      <Avatar size={50} shape="square" src={BKDLogo} className="order_images" />
                    )
                  }
                  title={
                    <p>
                      <span>{item?.productName} </span>
                      {item?.isRefridgerator ? (
                        <Tag icon={<HiOutlineShoppingBag className="bags" />} color="blue" bordered={false}>
                          Frozen
                        </Tag>
                      ) : (
                        <Tag icon={<HiOutlineShoppingBag className="bags" />} bordered={false}>
                          Normal
                        </Tag>
                      )}
                    </p>
                  }
                  description={
                    <div>
                      <div className="order-product-meta-row">
                        <span>{item?.packSize || "N/A"}</span>
                        <span>Qty. {item?.quantity || 0}</span>
                      </div>
                      <div className="show_replacement">
                        <Space>
                          <Alert banner message="Return" type={!item?.nonReturnable ? "success" : "error"} showIcon />
                          <Alert banner message="Replace" type={!item?.nonReplaceable ? "success" : "error"} showIcon />
                        </Space>
                      </div>
                    </div>
                  }
                />
                <b>{formatCurrency(getOrderItemAmount(item))}</b>
              </List.Item>
            )}
          />
        </div>
      </Card>
    );
  };

  return (
    <>
      <section className="main_Section order-details-page">
        <Breadcrumb
          style={{ marginBottom: "8px" }}
          items={[
            { title: "Dashboard" },
            { title: location.pathname },
          ]}
        />

        <div className="content_head order-details-toolbar">
          <div className="order_content_title">
            <Card className="card_body order-toolbar-card">
              <div className="order_status_titiles order-toolbar-inner">
                <div className="order_title order-toolbar-title">
                  <Space style={{ alignItems: "start" }}>
                    <Button type="circle" onClick={() => navigate(-1)}>
                      <HiArrowNarrowLeft className="back_icon" />
                    </Button>
                    <Title level={4} style={{ marginBottom: 0 }}>
                      Order History Details
                    </Title>
                  </Space>
                </div>
                <Space className="order-toolbar-actions">
                  <OrderComplaintAction
                    order={{ ...orderData, _id: orderData?._id || id }}
                    label="Complaint"
                    buttonProps={{
                      shape: "round",
                      className: "order-complaint-button",
                      disabled: !id,
                    }}
                  />
                  <Tag className="h6" color="blue" bordered={false}>
                    Branch OTP : {orderData?.partialOrCancelOtp || "N/A"}
                  </Tag>
                </Space>
              </div>
            </Card>
          </div>
        </div>

        {isLoading ? (
          <div className="loader_main" style={{ alignItems: "center", height: "50vh" }}>
            <span className="loader2"></span>
          </div>
        ) : (
          <>
            {orderData?.reasonStatusDetails?.reason ? (
              <Alert
                className="my-2"
                type="error"
                banner
                message={`Cancel Reason : ${orderData?.reasonStatusDetails?.reason}`}
              />
            ) : null}

            <Row className="order-details-layout">
              <Col md={8} style={{ paddingRight: "7px" }}>
                <div className="order_details order-details-main">
                  <div className="order_details_title order-summary-card">
                    <div className="order_del_img order-summary-identity">
                      <img src={LogImng} alt="Order" />
                      <div className="order_detials_id">
                        <div className="order-id-row">
                          <p>{orderData?.orderCode}</p>
                          <Tag color={getOrderListStatus(orderData?.status)}>{getDisplayStatusLabel(orderData?.status)}</Tag>
                        </div>
                        <p>Placed on : {orderData?.addedDate}</p>
                      </div>
                    </div>
                    <div className="order_title_actions order-summary-actions">
                      {orderData?.isPoolOrder ? <Tag color="blue" bordered={false}>POOL ORDER</Tag> : null}
                      <InvoiceDetials orderId={id} />
                    </div>
                  </div>

                  <Divider style={{ margin: "10px 0" }} />

                  <Row className="order-location-row">
                    <Col md={orderData?.deliveryOption !== "PICKUP" ? 6 : 12}>
                      <div className="location_box order-location-card">
                        <div className="location_header">
                          <Text strong>Pick-up Location</Text>
                        </div>
                        <Descriptions column={1} className="location_column">
                          <Descriptions.Item label="Branch Code">
                            {orderData?.branchId?.branchCode || orderData?.branchCode || "N/A"}
                          </Descriptions.Item>
                          <Descriptions.Item label="Branch Name">
                            {orderData?.branchId?.branchName || "N/A"}
                          </Descriptions.Item>
                          <Descriptions.Item label="Full Address">
                            {orderData?.branchId?.fullAddress || "N/A"}
                          </Descriptions.Item>
                        </Descriptions>
                      </div>
                    </Col>

                    {orderData?.deliveryOption !== "PICKUP" ? (
                      <Col md={6}>
                        <div className="location_box order-location-card">
                          <div className="location_header">
                            <Text strong>Delivery Location</Text>
                          </div>
                          <Descriptions column={1} className="location_column">
                            <Descriptions.Item label="Address Type">
                              {orderData?.userLocationId?.addressType || "N/A"}
                            </Descriptions.Item>
                            <Descriptions.Item label="Full Address">
                              {orderData?.userLocationId?.fullAddress || "N/A"}
                            </Descriptions.Item>
                          </Descriptions>
                        </div>
                      </Col>
                    ) : null}
                  </Row>

                  <Divider style={{ margin: "10px 0" }} />

                  <Card
                    className="card_body card_header order-products-card"
                    style={{ margin: "10px" }}
                    title={
                      <div className="product_order_item order-products-head">
                        <p>No. of Item {orderData?.productInfo?.length || 0}</p>
                      </div>
                    }
                  >
                    <div className="order-product-table-wrap">
                      <Table
                        columns={orderProductColumns}
                        dataSource={orderData?.productInfo || []}
                        rowKey={(item) => item?._id || item?.productCode}
                        pagination={false}
                        scroll={{ x: 900 }}
                        className="order-product-table"
                      />
                    </div>
                  </Card>

                  {renderReadOnlyItemsCard("Partial Return By User", orderData?.removedByUser?.productInfo)}
                  {renderReadOnlyItemsCard("Partial Return By Branch", orderData?.removedByBranch?.productInfo)}

                  <Card className="card_body_properties order-info-card" style={{ margin: "10px" }} title="Order Information">
                    <Descriptions bordered layout="vertical" className="order-info-grid">
                      <Descriptions.Item label="Alternative Name">
                        {orderData?.alternativeCustomerName || "N/A"}
                      </Descriptions.Item>
                      <Descriptions.Item label="Alternative Mobile">
                        {orderData?.alternativeMobileNo || "N/A"}
                      </Descriptions.Item>
                      <Descriptions.Item label="Order Code">{orderData?.orderCode || "N/A"}</Descriptions.Item>
                      <Descriptions.Item label="Place Date">
                        {orderData?.addedDate || "N/A"},{orderData?.addedTime || "N/A"}
                      </Descriptions.Item>
                      <Descriptions.Item label="Delivery Date">{orderData?.deliveryDate || "N/A"}</Descriptions.Item>
                      <Descriptions.Item label="Delivery Slot">
                        {orderData?.timeSlotFrom || "N/A"} - {orderData?.timeSlotTo || "N/A"}
                      </Descriptions.Item>
                      <Descriptions.Item label="Branch Code">{orderData?.branchCode || "N/A"}</Descriptions.Item>
                      <Descriptions.Item label="Payment Status">
                        <Tag color={orderData?.isPaymentDone !== true ? "#387ADF" : "#7ABA78"}>
                          {orderData?.isPaymentDone !== true ? "Pending" : "Done"}
                        </Tag>
                      </Descriptions.Item>
                      <Descriptions.Item label="Payment Mode">
                        <Tag color={orderData?.paymentMode !== "COD" ? "#7ABA78" : "#F57D1F"}>
                          {orderData?.paymentMode || "N/A"}
                        </Tag>
                      </Descriptions.Item>
                      <Descriptions.Item label="Status">
                        <Tag color={getOrderListStatus(orderData?.status)}>{getDisplayStatusLabel(orderData?.status)}</Tag>
                      </Descriptions.Item>
                    </Descriptions>
                  </Card>

                  <div className="show_transition_list" style={{ margin: "10px" }}>
                    <Card
                      title="Edited History"
                      className="card_body_properties order-data-card"
                    >
                      <Table
                        columns={editedHistoryColumns}
                        dataSource={orderEditHistoryData || []}
                        scroll={{ x: true }}
                        pagination={false}
                        rowKey={(item) => item?._id}
                      />
                    </Card>
                  </div>

                  <div className="show_transition_list" style={{ margin: "10px" }}>
                    <Card title="Transaction History" className="card_body_properties order-data-card">
                      <Table columns={paymentColumns} dataSource={orderData?.userPaymentInfo || []} scroll={{ x: true }} pagination={false} />
                    </Card>
                  </div>

                  <div className="show_transition_list" style={{ margin: "10px" }}>
                    <Card title="Order Status Action" className="card_body_properties order-data-card">
                      <Table columns={statusColumns} dataSource={orderData?.statusDetails || []} scroll={{ x: true }} pagination={false} />
                    </Card>
                  </div>
                </div>
              </Col>

              <Col md={4} style={{ paddingLeft: "7px", display: "flex", flexDirection: "column", gap: "10px" }}>
                <Card size="small" title="Payment Details" className="order-payment-card">
                  <div className="amount_item order-amount-row">
                    <p><b>MRP Total Amount</b></p>
                    <p><b>{formatCurrency(orderData?.mrpTotalProductAmount)}</b></p>
                  </div>
                  <div className="amount_item order-amount-row">
                    <p><b>Sub Total</b></p>
                    <p><b>{formatCurrency(orderData?.totalProductAmount)}</b></p>
                  </div>
                  {orderData?.discountAmount != null ? (
                    <div className="amount_item order-amount-row">
                      <p>
                        Discount {orderData?.discountType !== "FLAT" ? <span>({orderData?.discountValue}%)</span> : <span>({formatCurrency(orderData?.discountValue)})</span>}
                      </p>
                      <p>{formatCurrency(orderData?.discountAmount)}</p>
                    </div>
                  ) : null}
                  <div className="amount_item order-amount-row">
                    <p>Delivery Charge</p>
                    <p>
                      {Number(orderData?.deliveryCharge) > 0 ? formatCurrency(orderData?.deliveryCharge) : <span className="offer_product">Free</span>}
                    </p>
                  </div>
                  <Divider />
                  <div className="amount_item order-amount-row payable">
                    <p><b>Payable Amount</b></p>
                    <p><b>{formatCurrency(orderData?.totalPayableAmount)}</b></p>
                  </div>
                  <Divider dashed />
                  {Number(orderData?.totalSaving) !== 0 ? (
                    <Alert className="order-saving-alert" type="success" banner message={`Saved amount on this Order ${formatCurrency(orderData?.totalSaving)}`} />
                  ) : null}
                </Card>

                <Card
                  size="small"
                  title="User Details"
                  className="order-profile-card"
                  cover={
                    <div className="order-profile-cover">
                      <img
                        className="order_order_img"
                        style={{ objectFit: "contain" }}
                        alt="User"
                        src={orderData?.userId?.profilePic || DefaultImg}
                        onError={(e) => {
                          e.currentTarget.src = DefaultImg;
                        }}
                      />
                    </div>
                  }
                >
                  <Card.Meta
                    title={<p>{orderData?.userId?.fullName || "N/A"}</p>}
                    description={
                      <div>
                        <p>Number : {orderData?.userId?.mobileNo || "N/A"}</p>
                        <p>Email : {orderData?.userId?.email || "N/A"}</p>
                      </div>
                    }
                  />
                </Card>

                {orderData?.deliveryOption !== "PICKUP" ? (
                  orderData?.vendorId ? (
                    <Card
                      size="small"
                      title="Delivery Rider Details"
                      className="order-profile-card"
                      cover={
                        <div className="order-profile-cover">
                          <img
                            className="order_order_img"
                            style={{ objectFit: "contain" }}
                            alt="Delivery Rider"
                            src={orderData?.vendorId?.profilePic || DefaultImg}
                            onError={(e) => {
                              e.currentTarget.src = DefaultImg;
                            }}
                          />
                        </div>
                      }
                    >
                      <Card.Meta
                        title={<p>{orderData?.vendorId?.fullName || "N/A"}</p>}
                        description={
                          <div>
                            <p>Number : {orderData?.vendorId?.mobileNo || "N/A"}</p>
                            <p>Gender : {orderData?.vendorId?.gender || "N/A"}</p>
                            <p>Vehicle Type : {orderData?.vendorId?.vehicle || "N/A"}</p>
                            <p>License No. : {orderData?.vendorId?.drivingLicenseNo || "N/A"}</p>
                          </div>
                        }
                      />
                    </Card>
                  ) : (
                    <Card title="Delivery Rider Details" className="order-profile-card">
                      <Empty
                        image="https://gw.alipayobjects.com/zos/antfincdn/ZHrcdLPrvN/empty.svg"
                        description={<Typography.Text>Delivery Rider not assigned</Typography.Text>}
                      />
                    </Card>
                  )
                ) : null}

                <Card
                  title="Order Delivered Image"
                  className="order-proof-card"
                  cover={
                    Array.isArray(orderData?.deliveredImage) && orderData.deliveredImage.length > 0 ? (
                      <Image.PreviewGroup items={orderData.deliveredImage}>
                        <Image height={200} src={orderData.deliveredImage[0]} fallback={DefaultImage} />
                      </Image.PreviewGroup>
                    ) : (
                      <Image src={DefaultImage} fallback={DefaultImage} />
                    )
                  }
                />
              </Col>
            </Row>
          </>
        )}
      </section>

      {openHistoryModal &&
        <EditProductsHistoryModal
          open={openHistoryModal}
          onClose={toggleOrderHistoryModal}
          selectedProducts={selectedProducts || []}
          historyTitle={historyTitle}
        />
      }
    </>
  );
}

export default OrderHistoryDetails;
