/**
 * Console utility to disable console logs in production
 * This prevents sensitive information from being exposed in browser console
 */

const disableConsole = () => {
    if (process.env.NODE_ENV === 'production') {
        console.log = () => { };
        console.debug = () => { };
        console.info = () => { };
        console.warn = () => { };
        // Keep console.error for critical errors, or disable it too for strict security
        // console.error = () => {};
    }
};

/**
 * Safe logger that only works in development
 */
export const logger = {
    log: (...args) => {
        if (process.env.NODE_ENV !== 'production') {
            console.log(...args);
        }
    },
    warn: (...args) => {
        if (process.env.NODE_ENV !== 'production') {
            console.warn(...args);
        }
    },
    error: (...args) => {
        if (process.env.NODE_ENV !== 'production') {
            console.error(...args);
        }
    },
    info: (...args) => {
        if (process.env.NODE_ENV !== 'production') {
            console.info(...args);
        }
    },
    debug: (...args) => {
        if (process.env.NODE_ENV !== 'production') {
            console.debug(...args);
        }
    }
};

export default disableConsole;
