import React from "react";
import { Avatar, Image, Modal, Table, Tag } from "antd";
import BKDLogo from "../../assest/chat/logo.png";
import DefaulImg from "../../assest/chat/logo.png";
import { formatCurrency } from "./EditProductsModal";

function EditProductsHistoryModal({
    open,
    onClose,
    selectedProducts = [],
    historyTitle = "Product List",
}) {

    const columns = [
        {
            title: "Product Name",
            dataIndex: "productName",
            key: "productName",
            render: (_, item) => (
                <div>
                    <div
                        style={{
                            fontWeight: 600,
                            marginBottom: "4px",
                        }}
                    >
                        {item?.productName || "N/A"}
                    </div>

                    <div
                        style={{
                            fontSize: "12px",
                            color: "#666",
                        }}
                    >
                        {item?.productPackSize || "N/A"}
                    </div>

                    {item?.offerProduct ? (
                        <div style={{ marginTop: "4px" }}>
                            <Tag color="blue">
                                {item?.offerType || "Offer"}
                            </Tag>
                        </div>
                    ) : null}
                </div>
            ),
        },
        {
            title: "Qty",
            key: "quantity",
            width: 120,
            render: (_, item) => {
                const billingQty = Number(item?.requiredOfferedBillingQty || 0);
                const totalQty = Number(item?.quantity || 0);
                const freeQty = Number(item?.offerProduct?.quantity || 0);

                return (
                    <div>
                        <div><b>{billingQty || totalQty} </b> </div>

                        {freeQty > 0 ? (
                            <div
                                style={{
                                    fontSize: "12px",
                                    color: "#52c41a",
                                }}
                            >
                                + {freeQty} Free
                            </div>
                        ) : null}
                    </div>
                );
            },
        },
        {
            title: "Price",
            key: "price",
            width: 120,
            render: (_, item) => (
                <span>
                    {formatCurrency(item?.requiredOfferedBillingPrice)}
                </span>
            ),
        },
        {
            title: "Total Amount",
            key: "totalPrice",
            width: 150,
            render: (_, item) => (
                <b>
                    {formatCurrency(item?.totalPrice)}
                </b>
            ),
        },
    ];

    return (
        <Modal
            open={open}
            footer={null}
            width={900}
            title={historyTitle}
            onCancel={onClose}
        >
            <Table
                columns={columns}
                dataSource={selectedProducts || []}
                rowKey={(item, index) =>
                    item?._id ||
                    item?.productCode ||
                    index
                }
                pagination={false}
                scroll={{ x: 800 }}
            />
        </Modal>
    );
}

export default EditProductsHistoryModal;