import React, { useEffect, useState } from "react";
import {
  Avatar,
  Breadcrumb,
  Button,
  Image,
  Input,
  Modal,
  Pagination,
  Table,
  Tag,
  Typography,
  message,
} from "antd";
import "../../style/partner.css";
import {
  LoadingOutlined,
  PoweroffOutlined,
  ReloadOutlined,
  SearchOutlined,
} from "@ant-design/icons";
import { FaRegUser } from "react-icons/fa";
import { useAuth } from "../../authentication/context/authContext";
import {
  fetchDeliveryPartnerList,
  fetchDeliveryPartnerOrdersOverview,
  updateDeliveryPartnerStatus,
} from "../../service/api_services";
import DefaultImg from "../../assest/chat/user.png";
import RiderOrdersOverviewModal, {
  initialVendorOrdersOverview,
} from "./RiderOrdersOverviewModal";

function ManageRiders() {
  const { token, logout } = useAuth();
  const { Title } = Typography;

  const [riderList, setRiderList] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [current, setCurrent] = useState(1);
  const [totalPage, setTotalPage] = useState(1);
  const [searchInput, setSearchInput] = useState("");
  const [ordersModalOpen, setOrdersModalOpen] = useState(false);
  const [selectedVendor, setSelectedVendor] = useState(null);
  const [vendorOrdersLoading, setVendorOrdersLoading] = useState(false);
  const [updatingVendorId, setUpdatingVendorId] = useState(null);
  const [vendorOrdersOverview, setVendorOrdersOverview] = useState(
    initialVendorOrdersOverview
  );

  const showManageRidersList = async () => {
    setIsLoading(true);
    try {
      const res = await fetchDeliveryPartnerList(token, current, searchInput);

      if (res.status === 200) {
        setRiderList(res?.data?.data?.data || []);
        setTotalPage(res?.data?.data?.totalPage || 1);
      } else if (res?.data?.code === 283) {
        message.error(res?.data?.message);
        logout();
      }
    } catch (error) {
      console.log(error);
      message.error("Failed to fetch delivery riders");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    showManageRidersList();
  }, [current, searchInput]);

  const showVendorOrdersOverview = async (vendor) => {
    try {
      setSelectedVendor(vendor);
      setOrdersModalOpen(true);
      setVendorOrdersLoading(true);

      const res = await fetchDeliveryPartnerOrdersOverview(token, vendor?._id);
      if (res.status === 200) {
        setVendorOrdersOverview(res?.data?.data || initialVendorOrdersOverview);
      }
    } catch (error) {
      console.log(error);
      message.error(
            error?.response?.data?.message || "Failed to fetch delivery rider orders overview"
      );
      setVendorOrdersOverview(initialVendorOrdersOverview);
    } finally {
      setVendorOrdersLoading(false);
    }
  };

  const closeOrdersModal = () => {
    setOrdersModalOpen(false);
    setSelectedVendor(null);
    setVendorOrdersOverview(initialVendorOrdersOverview);
  };

  const isRiderCurrentlyActive = (rider) =>
    rider?.isActive === true || rider?.status === "ACTIVE";

  const getStatusMeta = (rider) => {
    if (isRiderCurrentlyActive(rider)) {
      return { color: "green", label: "ACTIVE" };
    }

    return { color: "orange", label: "INACTIVE" };
  };

  const handleStatusToggle = (rider) => {
    const isCurrentlyActive = isRiderCurrentlyActive(rider);
    const nextIsActive = !isCurrentlyActive;

    Modal.confirm({
      title: nextIsActive ? "Activate delivery rider?" : "Mark delivery rider inactive?",
      content: nextIsActive
        ? `Are you sure you want to activate ${rider?.fullName || "this delivery rider"}?`
        : `Are you sure you want to mark ${rider?.fullName || "this delivery rider"} inactive?`,
      okText: nextIsActive ? "Activate" : "Mark Inactive",
      okButtonProps: nextIsActive ? {} : { danger: true },
      cancelText: "Cancel",
      centered: true,
      onOk: async () => {
        setUpdatingVendorId(rider?._id);

        try {
          const res = await updateDeliveryPartnerStatus(
            token,
            rider?._id,
            nextIsActive
          );

          if (res.status === 200) {
            message.success(
              res?.data?.message ||
          `Delivery Rider ${nextIsActive ? "activated" : "marked inactive"} successfully`
            );
            await showManageRidersList();
          }
        } catch (error) {
          console.log(error);
          message.error(
            error?.response?.data?.message ||
          `Failed to ${nextIsActive ? "activate" : "mark delivery rider inactive"}`
          );
        } finally {
          setUpdatingVendorId(null);
        }
      },
    });
  };

  const renderAssignedBranches = (assignedBranches = []) => {
    if (!assignedBranches.length) {
      return "N/A";
    }

    return (
      <div className="rider-branch-list">
        {assignedBranches.map((branch) => {
          const branchLabel = branch?.branchAlias || branch?.branchCode || "Branch";
          const branchName = branch?.branchName || "N/A";

          return (
            <div className="rider-branch-item" key={branch?._id || `${branchLabel}-${branchName}`}>
              <Tag color="blue">{branchLabel}</Tag>
              <span>{branchName}</span>
            </div>
          );
        })}
      </div>
    );
  };

  const columns = [
      {
        title: "Image",
        dataIndex: "profilePic",
        key: "profilePic",
        width: 80,
        render: (_, { profilePic }) =>
          profilePic ? (
            <Image
              src={profilePic || DefaultImg}
              onError={(e) => (e.currentTarget.src = DefaultImg)}
              width={46}
              height={46}
              style={{
                borderRadius: "100%",
                objectFit: "contain",
                background: "lightGray",
              }}
            />
          ) : (
            <Avatar size={42} icon={<FaRegUser className="pro_icon" />} />
          ),
      },
      {
        title: "Name",
        dataIndex: "fullName",
        key: "fullName",
        ellipsis: true,
      },
      {
        title: "Number",
        dataIndex: "mobileNo",
        key: "mobileNo",
      },
      {
        title: "Assign Branches",
        dataIndex: "assignedBranches",
        key: "assignedBranches",
        width: 260,
        render: renderAssignedBranches,
      },
      {
        title: "Document Upload",
        dataIndex: "isDocumentUpload",
        key: "isDocumentUpload",
        render: (_, { isDocumentUpload }) =>
          isDocumentUpload ? <Tag color="green">Uploaded</Tag> : <Tag color="red">Pending</Tag>,
      },
      {
        title: "Vehicle Type",
        dataIndex: "vehicle",
        key: "vehicle",
        render: (vehicle) => vehicle || "N/A",
      },
      {
        title: "Vehicle Number",
        dataIndex: "vehilceNo",
        key: "vehilceNo",
        render: (vehilceNo) => vehilceNo || "N/A",
      },
      {
        title: "Outstanding Amount",
        dataIndex: "outStandingBalance",
        key: "outStandingBalance",
        render: (outStandingBalance) => {
          const amount = Number(outStandingBalance || 0);
          const hasOutstanding = amount > 0;

          return (
            <span
              className={`rider-outstanding-pill ${
                hasOutstanding ? "has-outstanding" : "no-outstanding"
              }`}
            >
              {`Rs. ${amount.toFixed(2)}`}
            </span>
          );
        },
      },
      {
        title: "Document Action",
        key: "isDocumentVerified",
        dataIndex: "isDocumentVerified",
        render: (_, { isDocumentVerified }) =>
          isDocumentVerified == null ? (
            <Tag color="blue">Pending</Tag>
          ) : isDocumentVerified === true ? (
            <Tag color="green">Approved</Tag>
          ) : (
            <Tag color="red">Reject</Tag>
          ),
      },
      {
        title: "Status",
        key: "status",
        dataIndex: "status",
        render: (_, record) => {
          const statusMeta = getStatusMeta(record);

          return <Tag color={statusMeta.color}>{statusMeta.label}</Tag>;
        },
      },
      {
        title: "Available",
        key: "isOnline",
        dataIndex: "isOnline",
        render: (_, { isOnline }) =>
          isOnline ? <Tag color="green">Online</Tag> : <Tag color="red">Offline</Tag>,
      },
      {
        title: "Action",
        key: "action",
        fixed: "right",
        width: 190,
        render: (_, record) => {
          const isCurrentlyActive = isRiderCurrentlyActive(record);

          return (
            <div className="rider-table-actions">
              <Button type="link" onClick={() => showVendorOrdersOverview(record)}>
                View Orders
              </Button>
              <Button
                type="link"
                danger={isCurrentlyActive}
                icon={<PoweroffOutlined />}
                loading={updatingVendorId === record?._id}
                onClick={() => handleStatusToggle(record)}
              >
                {isCurrentlyActive ? "Inactive" : "Active"}
              </Button>
            </div>
          );
        },
      },
    ];

  return (
    <section className="main_Section">
      <Breadcrumb
        items={[
          { title: "Dashboard" },
          { title: "Delivery Rider" },
      { title: "Manage Delivery Riders" },
        ]}
      />

      <div className="content_title">
        <div className="content_head">
          <div className="content_titles">
            <div className="hear_title">
          <Title level={4}>Manage Delivery Riders</Title>
            </div>
          </div>
        </div>

        <div className="manage-riders-toolbar">
          <div className="manage-riders-search">
            <Input
              allowClear
              placeholder="Search Name Or Number"
              suffix={<SearchOutlined />}
              value={searchInput}
              onChange={(e) => {
                setCurrent(1);
                setSearchInput(e.target.value);
              }}
            />
          </div>

          <Button
            type="primary"
            shape="round"
            className="manage-riders-refresh-btn"
            onClick={showManageRidersList}
            loading={isLoading}
            icon={isLoading ? <LoadingOutlined /> : <ReloadOutlined />}
          >
            Refresh
          </Button>
        </div>

        <div className="content">
          <div className="shoo_recent_order">
            <Table
              rowKey={(record) => record?._id}
              columns={columns}
              dataSource={riderList}
              loading={isLoading}
              scroll={{ x: 1700 }}
              pagination={false}
        locale={{ emptyText: "No delivery riders found" }}
              footer={() => (
                <div className="pagination">
                  <Pagination
                    current={current}
                    onChange={(page) => setCurrent(page)}
                    total={totalPage * 10}
                  />
                </div>
              )}
            />
          </div>
        </div>
      </div>

      <RiderOrdersOverviewModal
        open={ordersModalOpen}
        onCancel={closeOrdersModal}
        selectedVendor={selectedVendor}
        vendorOrdersLoading={vendorOrdersLoading}
        vendorOrdersOverview={vendorOrdersOverview}
      />
    </section>
  );
}

export default ManageRiders;
