import React, { useEffect, useState } from 'react'
import "../../style/order.css"
import LogoImg from "../../assest/png/logoIcon.png"
import { Space, Table, Tag, Card, Button, Avatar, Pagination, message, Input, Image, Popconfirm } from 'antd';
import {
    LoadingOutlined,
    SearchOutlined
} from '@ant-design/icons';

import { CollectPickupCodePayment, fetchCodPayment } from '../../service/api_services';
import { useAuth } from '../../authentication/context/authContext';

import { FaRegUser } from 'react-icons/fa';
import { useScreen } from '../../authentication/context/AuthScreen';


function PickupCodePayment() {
    const { screenWidth } = useScreen();
    const isMobile = screenWidth < 768;
    const { token, logout } = useAuth()
    // const [orderType, setOrderType] = useState("REMOVED")
    const [orderData, setOrderData] = useState([])
    const [isLoading, setIsLoading] = useState(false)
    const [totalPage, setTotalPage] = useState(null);
    const [current, setCurrent] = useState(1);
    const [searchInput, setSearchInput] = useState("")


    const onChange = (page) => {
        setCurrent(page);
        setIsLoading(true);
    };

    const getStatusColor = (status) => {
        switch (status) {

            case 'SUCCESS':
                return '#87A922';

            default:
                return '#B3A398';
        }
    };
    const columns = [
        {
            title: 'Order Code',
            dataIndex: 'orderCode',
            key: 'orderCode',
            render: (_, { orderCode, _id }) => (
                <div className="order_code">
                    <span>#</span><span><b>{orderCode}</b></span>

                </div>
            ),
            ellipsis: true,
        },
        {
            title: 'Customer Image',
            dataIndex: 'userProfilePic',
            key: 'userProfilePic',
            ellipsis: true,

            render: (_, { userProfilePic }) => (
                <div className="show_user_img" >
                    {userProfilePic != null ?
                        <Image src={userProfilePic} width={45}
                            height={45} style={{ background: "lightGray", borderRadius: "100%" }} />
                        : <Avatar icon={<FaRegUser style={{ marginTop: "-.5rem" }} />} />}
                </div>
            )
        },
        {
            title: 'Customer Name',
            dataIndex: 'userFullName',
            key: 'userFullName',


            ellipsis: true,
        },

        {
            title: 'Customer Number',
            dataIndex: 'userMobileNo',
            key: 'userMobileNo',
            ellipsis: true,


        },
        {
            title: 'Status',
            key: 'status',
            dataIndex: 'status',
            render: (_, { status, _id }) => (
                <>
                    <Tag key={_id} color={getStatusColor(status)}>{status}</Tag>
                </>
            ),
        },
        {
            title: 'Customer Payable Amount',
            key: 'totalPayableAmount',
            dataIndex: 'totalPayableAmount',
            ellipsis: true,

            render: (_, { totalPayableAmount }) => (
                <>
                    ₹{totalPayableAmount}
                </>
            ),
        },


        {
            title: 'Delivered Date',
            dataIndex: 'addedDate',
            key: 'addedDate',

            ellipsis: true,
        },
        {
            title: 'Delivery Type',
            dataIndex: 'deliveryOption',
            key: 'deliveryOption',

            ellipsis: true,
        },
        {
            title: 'Delivery Rider',
            dataIndex: 'vendorFullName',
            key: 'vendorFullName',

            ellipsis: true,
        },
        {
            title: 'Delivery Rider No.',
            dataIndex: 'vendorMobileNo',
            key: 'vendorMobileNo',

            ellipsis: true,
        },




        // {
        //     title: 'Branch Collected',
        //     dataIndex: 'amountPaid',
        //     key: 'amountPaid',
        //     render: (_, { amountPaid }) => (
        //         <span>₹ {amountPaid?.toFixed(2)}</span>

        //     ),
        //     ellipsis: true,
        // },
        // {
        //     title: 'Branch Collected Date',
        //     dataIndex: 'paidDateTime',
        //     key: 'paidDateTime',
        //     render: (_, { paidDateTime }) => (
        //         <span> {paidDateTime != null ? paidDateTime : "N/A"}</span>

        //     ),
        //     ellipsis: true,
        // },

        {
            title: 'Action',
            key: '_id',
            render: (_, { _id, status, totalPayableAmount }) => (
                <Popconfirm
                    title="Collect the Payment"
                    description={`Are you sure to receive ₹${totalPayableAmount} from the delivery rider?`}
                    onConfirm={() => handelCollectPayment(_id, totalPayableAmount)}
                    onCancel={cancel}
                    okText="Yes"
                    cancelText="No"
                    placement="topLeft"
                >

                    <Button disabled={status === "SUCCESS"} shape="round" className='collect_pay' >
                        ₹{totalPayableAmount} {status === "SUCCESS" ? "Collected" : "Collect"}
                    </Button>
                </Popconfirm>
            ),
            fixed: 'right',
        },
    ];
    const visibleColumns = columns.filter((column) => column.key !== '_id');

    const cancel = (e) => {
        console.log(e);
        message.error('Click on No');
    };
    const handelCollectPayment = async (_id, totalPayableAmount) => {

        try {
            await CollectPickupCodePayment({
                userOrderPaymentDetailsId: _id,
                amountPaid: totalPayableAmount,
            }, token)
                .then((res) => {
                    console.log("collect payment", res);
                    if (res.status == 201) {
                        message.success(res.data.message)
                        ShowPickupPaymentList()
                    }

                })
                .catch((err) => {
                    console.log(err);
                });
        } catch (error) {
            console.log(error);
        }
    };

    const ShowPickupPaymentList = async () => {
        setIsLoading(true)
        try {
            await fetchCodPayment(token, current, searchInput)
                .then((res) => {
                    console.log("cod order list", res);
                    if (res.status == 200) {
                        setOrderData(res.data.data.data);
                        setTotalPage(res.data.data.totalPage)
                        setIsLoading(false)
                    } else if (res.data.code == 283) {
                        message.error(res.data.message)
                        logout()

                    }
                })
                .catch((err) => {
                    console.log(err.message);
                    setIsLoading(false)
                });
        } catch (error) {
            console.log(error);
            setIsLoading(false)
        }
    };

    useEffect(() => {
        ShowPickupPaymentList();
    }, [searchInput, current]);


    return (
        <section className="main_Section">
            <div className="content_head">
                <div className="order_content_title">
                    <Card className="card_body">
                        <div className="order_status_titiles">
                            <div className="order_title">
                                <div className="order_img">
                                    <img src={LogoImg} className="logo_icon" />
                                </div>
                                <div className="order_status">
                                    <h4> COD Payment Order </h4>
                                    <p>{orderData?.length}  Orders </p>
                                </div>

                            </div>
                            <div className="order_status_action order_status_action_input">
                                <Space>
                                    <Input
                                        allowClear
                                        placeholder="Search Order"
                                        onChange={(e) => setSearchInput(e.target.value)}
                                        prefix={<SearchOutlined />}
                                        id="seach_ord"
                                        size="medium"
                                    />
                                </Space>
                                <Button
                                    type="primary"
                                    onClick={() => ShowPickupPaymentList()}
                                    loading={isLoading}
                                    icon={isLoading ? <LoadingOutlined /> : null}
                                >
                                    Refresh
                                </Button>
                                {/* <Segmented options={["REMOVED", "CANCELLED"]} onChange={(value) => {
                                    setOrderType(value);
                                    console.log(value); // string
                                }} /> */}
                            </div>
                        </div>
                    </Card>
                </div>


            </div>
            <div className="partner_content" style={{ border: '1px solid #f0f0f0', borderRadius: '8px' }}>
                {isLoading ? <div className="loader_main"> <span class="loader2"></span></div> :
                    <Table columns={visibleColumns} dataSource={orderData} scroll={{ x: true }}
                        pagination={false}
                        footer={() => <div className="pagination">
                            <Pagination current={current} onChange={onChange} total={totalPage * 10} />
                        </div>}

                    />}

            </div>
        </section>
    )
}



export default PickupCodePayment
