import React, { useEffect, useRef, useState } from 'react';
import { Avatar, Button, Collapse, Input, List, message, Modal, Steps } from 'antd';
import "../../style/order.css"
import { fetchAllDeliveryBoyList, OrderAssignToVendor, returnReplaceVendorAssign, VendorOrderReturnTrackData, vendorReturnOrderReassignVerify } from '../../service/api_services';
import { useAuth } from '../../authentication/context/authContext';

import dayjs from 'dayjs';
import OtpInput from "react-otp-input";

const VendorAssign = ({ orderId, status, ShowOrderList, orderData, title }) => {
    const { token } = useAuth()
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [venderData, setVendorData] = useState([])
    const [vendorId, setVenderId] = useState(null)
    const [partnerTrack, setPartnerTrack] = useState([]);
    const [isShowOtp, setIsShowOtp] = useState(false);
    const [otp, setOtp] = useState(null)
    const [isOtp, setSetOtp] = useState(null)
    const focusOtp = useRef()
    const [isAssigned, setIsAssigned] = useState(false)



    const showPartnerTracData = async () => {
        try {
            const res = await VendorOrderReturnTrackData(token, orderId);
            console.log("vendor track", res);
            setPartnerTrack(res.data.data.vendorReAssginList || []);
            setIsShowOtp(res.data.data.isOtpScreen || false);
        } catch (error) {
            console.log(error);
        }
    };

    const showModal = () => {
        setIsModalOpen(true);
        ShowDeliveryBoyList()
        showPartnerTracData()
    };
    const handleOk = () => {
        setIsModalOpen(false);
    };
    const handleCancel = () => {
        setIsModalOpen(false);
    };

    const ShowDeliveryBoyList = async () => {
        setIsLoading(true)
        try {
            await fetchAllDeliveryBoyList(token)
                .then((res) => {
                    console.log("delivery boy list ssss", res);
                    if (res.status == 200) {
                        setVendorData(res.data.data);
                        setIsLoading(false)
                    }
                })
                .catch((err) => {
                    console.log(err.message);
                });
        } catch (error) {
            console.log(error);
            setIsLoading(false)
        }
    };



    const assignVendorHandler = async () => {
        setIsAssigned(true)
        if (!vendorId) {
                message.error("Please select a delivery rider.")
            setIsAssigned(false)
        } else {

            const body = {
                userOrderReturnAndReplacementId: orderId,
                vendorId: vendorId,
            }
            try {
                await returnReplaceVendorAssign(body, token)
                    .then((res) => {
                        console.log("assign vendor", res);
                        if (res.status == 201) {
                            message.success(res.data.message)
                            setIsModalOpen(false);
                            setVenderId(null)
                            setIsAssigned(false)
                            ShowOrderList()
                        } else if (res.status === 200) {
                            message.warning(res.data.message)
                            setIsAssigned(false)


                        }

                    })
                    .catch((err) => {
                        console.log(err);
                        setIsAssigned(false)

                    });
            } catch (error) {
                console.log(error);
                setIsAssigned(false)

            }
        }
    };

    const stepItems = partnerTrack.map((item, index) => ({
        title: `From : ${item.fromVendorName || "N/A"} - To : ${item.toVendorName || "N/A"}`,
        description: `Assigned on: ${item.addedDate ? dayjs(item.addedDate).format("DD MMM YYYY, hh:mm A") : "N/A"}`,
    }));


    const OtpVerifyHandler = async () => {
        setSetOtp(true)
        const body = {
            userOrderReturnAndReplacementId: orderId,
            reAssignOtp: otp,
        };
        try {
            const res = await vendorReturnOrderReassignVerify(body, token);
            if (res.status === 201) {
                message.success(res.data.message);
                setIsModalOpen(false);
                setVenderId(null);
                ShowOrderList();
                setSetOtp(false)
            } else if (res.status === 200) {
                message.info(res.data.message);
                setSetOtp(false)
            }
        } catch (error) {
            console.log(error);
            setSetOtp(false)

        }
    };

    useEffect(() => {
        if (focusOtp.current) {
            focusOtp.current.focus();
        }
    }, []);

    return (
        <div className='vendor_list_assign'>
            <Button
                disabled={orderData?.status === "RETURNED" || orderData?.status === "CLOSED" || orderData?.status === "REJECTED"}
                type='primary'
                className='reassing_vendor'
                onClick={showModal} shape='round'>
                {title}
            </Button>
            <Modal style={{
                top: 10
            }} loading={isLoading} title="Delivery Rider List" open={isModalOpen} onOk={handleOk} onCancel={handleCancel} footer={false}>
                <div className="vendor_track">
                    {partnerTrack.length === 0 ? (
                        null
                    ) : (
                        <Collapse expandIconPosition='right' >
                            <Collapse.Panel header="Delivery Rider Tracks" key="1">
                                <Steps
                                    className='custom-steps'
                                    progressDot
                                    current={partnerTrack.length - 1} // last step as current

                                    direction="vertical"
                                    items={stepItems}
                                />
                            </Collapse.Panel>
                        </Collapse>

                    )}
                </div>
                {isShowOtp ? <div className='verify_otp_setion'>
                    <h5>Verify OTP </h5>
                    {/* <p><span>(Ask the OTP previous delivery partner to verify  )</span></p> */}
                    <div className="new_otp_item">
                        <OtpInput
                            value={otp}
                            onChange={setOtp}
                            numInputs={4}
                            placeholder={0}
                            inputType="numeric"
                            // renderSeparator={<span>-</span>}
                            renderInput={(props, index) => (
                                <div className="otp_field">

                                    <Input ref={focusOtp}  {...props} style={{ width: "2.5rem", height: "2.5rem" }} placeholder="0" variant="filled"
                                        // type="number"
                                        inputMode="numeric"
                                        pattern="[0-9]*" />

                                </div>
                            )}
                        />
                    </div>
                    <div className="verify_otp_btn">
                        <Button loading={isOtp} type='primary' onClick={() => OtpVerifyHandler()}>Submit</Button>
                    </div>
                </div> :
                    <section className='show_all_dender'>

                        <List
                            loading={isLoading}
                            itemLayout="horizontal"
                            dataSource={venderData}
                            renderItem={(item) => (
                                <List.Item actions={[<div className={vendorId === item._id ? "assign_btn" : ""}>
                                    <Button onClick={() => setVenderId(item._id)}>{vendorId === item._id ? "Selected" : "Select"}</Button></div>]}>
                                    <List.Item.Meta
                                        avatar={<Avatar src={item.profilePic != null ? item.profilePic : `https://api.dicebear.com/7.x/miniavs/svg?seed=${item._id}`} size={40} />}
                                        title={<p>{item.fullName}</p>}
                                        description={<p>Assign Order: {item.assignedOrder}</p>}
                                    />
                                </List.Item>
                            )}
                        />
                        <div className='assign_vendor'>
                            <Button loading={isAssigned} onClick={() => assignVendorHandler()}>Assign Delivery Rider</Button>
                        </div>
                    </section>
                }
            </Modal>
        </div>
    );
};

export default VendorAssign
