import React, { useState } from "react";
import "./loginpage.css";
import { Link, useNavigate } from "react-router-dom";
import { Button, Divider, Form, Input, Space, Spin, message } from "antd";
import { useAuth } from "../context/authContext";
import LoginImg from "../../assest/chat/ac.jpg";
import { Col, Row } from "react-bootstrap";
import { FaUserCircle } from "react-icons/fa";
import { LoginUsers } from "../../service/api_services";
import BKDLogo from '../../assest/chat/logo.png'

function LoginPage() {

  const { login, getBranchData, fcmtoken } = useAuth();
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);
  const [inital, setInital] = useState({email:'riteshtest1@gmail.com',password:'12345678'});
  const [form] = Form.useForm();

  // console.log("fcmtoken login",fcmtoken)


  const submithandler = async (value) => {
    setIsLoading(true)
    try {
      const res = await LoginUsers({ ...value, fcmToken: fcmtoken });

      if (res.status === 201) {
        login(res.data.data.accessToken);
        localStorage.setItem("token", res.data.data.accessToken);
        localStorage.setItem("branchData", JSON.stringify({ branchCode: res.data.data.branchCode, branchName: res.data.data.branchName }));
        getBranchData({ branchCode: res.data.data.branchCode, branchName: res.data.data.branchName })
        message.success(res.data.message);
        navigate("/dashboard");
      } else {
        message.error(res.data.message);
      }
    } catch (error) {
      message.error(error?.message || "Something went wrong");
    } finally {
      setIsLoading(false);
    }
  };

  const handelFeild = (value) => {
    console.log(value)
  }

  return (
    <section>
      <div className="loginSection">
      </div>
      <div className="login">
        <Row>
          <Col md={7}>
            <div className="loginLogo">
              <img
                src={"https://www.tastingtable.com/img/gallery/13-most-affordable-grocery-stores-in-2023/l-intro-1679073677.jpg" || BKDLogo}
                onError={(e) => e.currentTarget.src = BKDLogo}
              />
            </div>
          </Col>
          <Col md={5}>
            <div className="loginField">
              <div className="log_img">
                <Space>
                  <img src={BKDLogo} />

                </Space>
                <h4>Branch Login</h4>
              </div>

              <Form
                form={form}
                layout="vertical"
                name="basic"
                labelCol={{
                  span: 12,
                }}
                wrapperCol={{
                  span: 24,
                }}
                autoComplete="on"
                initialValues={inital}
                onFinish={submithandler}
                onFinishFailed={handelFeild}

              >
                <Form.Item
                  name="email"
                  rules={[
                    {
                      required: true,
                      message: "Please enter your email!",
                    },
                  ]}
                >
                  <Input
                    placeholder="Enter Email"
                  />
                </Form.Item>

                <Form.Item
                  name="password"
                  rules={[
                    {
                      required: true,
                      message: "Please enter your password!",
                    },
                  ]}
                >
                  <Input.Password
                    placeholder="Enter Password"
                  />
                </Form.Item>

                <Form.Item
                  wrapperCol={{
                    offset: 7,
                    span: 12,
                  }}
                >
                  <div className="submit_btn">
                    <Button
                      type="primary"
                      htmlType="submit"
                      loading={isLoading}
                      size="large"
                      shape="round"
                    >
                      Login
                    </Button>
                  </div>
                </Form.Item>
              </Form>
              <p>Don't have an account please contact your admin</p>
            </div>
          </Col>
        </Row>
      </div>
    </section>
  );
}

export default LoginPage;
