import { Button, Card } from 'antd'
import React, { useEffect, useState } from 'react'
import "./dashboard.css"

import { Space, Table, Tag } from 'antd';
import { useNavigate } from 'react-router-dom';
import { fetchAllOrderList } from '../../service/api_services';
import { useAuth } from '../../authentication/context/authContext';



function RecentOrderList() {

  const [orderList, setOrderList] = useState([]);
  const [isIsLoading, setIsLoading] = useState(false)
  const { token } = useAuth()
  const navigate = useNavigate();


  const getStatusColor = (status) => {
    switch (status) {
      case 'ACCEPTED':
        return '#90D26D';
      case 'DISPATCHED':
        return '#008DDA';
      case 'DELIVERED':
        return '#87A922';
      case 'CANCELLED':
        return '#FF204E';
      default:
        return '#B3A398';
    }
  };
  const columns = [
    {
      title: 'Order ID',
      dataIndex: 'orderCode',
      key: 'orderCode',
      render: (orderCode) => <a>{orderCode}</a>,
    },
    {
      title: 'Order Placed',
      dataIndex: 'addedDate',
      key: 'addedDate',
      render: (_, { addedDate }) => (
        <span>{new Date(addedDate).toLocaleDateString()}</span>
      )
    },
    {
      title: 'Time Slot',
      dataIndex: 'addedDate',
      key: 'addedDate',
      render: (_, { addedDate }) => (
        <Space>
          <span>--</span> / <span>--</span>
        </Space>
      )
    },
    {
      title: 'Delivery Type',
      dataIndex: 'deliveryOption',
      key: 'deliveryOption',
      render: (_, { deliveryOption }) => (
        <Tag color={deliveryOption == "DELIVERY" ? "#7ABA78" : "#387ADF"}>
          {deliveryOption}
        </Tag>

      ),
      ellipsis: true,
    },
    {
      title: 'User Name',
      key: 'userId',
      dataIndex: 'userId',
      render: (_, { userId }) => (
        <span>
          {userId?.fullName}
        </span>
      ),
    },
    {
      title: 'User Number',
      key: 'userId',
      dataIndex: 'userId',
      render: (_, { userId }) => (
        <span>
          {userId?.mobileNo}
        </span>
      ),
    },
    {
      title: 'Payable Amount',
      dataIndex: 'totalPayableAmount',
      key: 'totalPayableAmount',
      render: (_, { totalPayableAmount }) => (
        <span> ₹
          {totalPayableAmount?.toFixed(2)}
        </span>
      ),
    },
    {
      title: 'Order Status',
      key: 'status',
      dataIndex: 'status',
      render: (_, { status, _id }) => (
        <>
          <Tag key={_id} color={getStatusColor(status)}>{status}</Tag>
        </>
      ),
    },
    {
      title: 'Action',
      key: '_id',
      render: (_, { _id, status }) => (
        <Space size="middle">
          <Button shape="round" id="order_branch" >View </Button>

        </Space>
      )
    },
  ];

  const recentOrderList = async () => {
    try {
      await fetchAllOrderList(token)
        .then((res) => {
          console.log("order list", res);
          if (res.status == 200) {
            setOrderList(res.data.data);
            setIsLoading(true)
          }
        })
        .catch((err) => {
          console.log(err.message);
        });
    } catch (error) {
      console.log(error);
      setIsLoading(true)
    }
  };

  useEffect(() => {
    recentOrderList();
  }, []);


  return (
    <div className="shoo_recent_order">
      <p>New Order List</p>
      {!isIsLoading ? <div className="loader_main"> <span class="loader2"></span></div> : <Table columns={columns} dataSource={orderList} scroll={{ x: true }} pagination={false} />
      }
    </div>
  )
}




export default RecentOrderList