import React, { useEffect, useState } from 'react'
import "../../style/order.css"
import LogoImg from "../../assest/png/logoIcon.png"
import { useNavigate } from 'react-router-dom'
import { Space, Table, Tag, Card, Button, Avatar, Segmented } from 'antd';





function CanceOrder({ orderData, isLoading }) {

const navigate=useNavigate()

    const columns = [
        {
            title: 'ORDER ID',
            dataIndex: 'userOrderId',
            key: 'iduserOrderId',
            render: (_, { userOrderId }) => (
                <b>{userOrderId?.orderCode}</b>
            )

        },
        {
            title: 'CUSTOMER ',
            dataIndex: 'userOrderId',
            key: 'userOrderId',
            render: (_, { userOrderId }) => (
                <span>{userOrderId?.userId?.fullName}</span>
            )
        },

        {
            title: 'NUMBER',
            dataIndex: 'userOrderId',
            key: 'userOrderId',
            render: (_, { userOrderId }) => (
                <span>{userOrderId?.userId?.mobileNo}</span>
            )
        },
        {
            title: 'PAYABLE AMOUNT ',
            dataIndex: 'totalActualReturnAmount',
            key: 'totalActualReturnAmount',
            render: (_, { totalActualReturnAmount }) => (
                <p>₹ {totalActualReturnAmount}</p>

            )
        },

        {
            title: 'REFUND AMOUNT',
            dataIndex: 'totalReturnableAmount',
            key: 'totalReturnableAmount',
            ellipsis: true,
            render: (_, { totalReturnableAmount }) => (
                <p>₹ {totalReturnableAmount}</p>

            )
        },

        {
            title: 'DATE',
            dataIndex: 'date',
            key: 'date',
        },

        {
            title: 'TRANSACTION ID',
            dataIndex: 'transactionId',
            key: 'transactionId',
            ellipsis: true,

            render: (_, { transactionId }) => (
                <>
                    {transactionId != null ? transactionId : "N/A"}
                </>

            )
        },

        {
            title: 'REFUND STATUS',
            key: 'status',
            dataIndex: 'status',
            render: (_, { status }) => (

                <Tag color={status == "PENDING" ? "blue" : "green"} >
                    {status}
                </Tag>

            ),
        },
        {
            title: 'ACTION',
            key: '_id',
            dataIndex: '_id',
            render: (_, { _id }) => (

                <Button onClick={() => navigate(`/dashboard/order-history-details/${_id}`)}>View </Button>

            ),
        },

    ];

    return (
        <section className="main_Section">
            <div className="partner_content">
                {!isLoading ? <div className="loader_main"> <span class="loader2"></span></div> : <Table columns={columns} dataSource={orderData} scroll={{ x: true }} />}
            </div>
        </section>
    )
}


export default CanceOrder