import React from "react";
import ReactDOM from "react-dom/client";
import "./index.css";
import App from "./App";
import { BrowserRouter } from "react-router-dom";
import { AuthProvider } from "./authentication/context/authContext";
import { UserProvider } from "./authentication/context/userContext";
import { Provider } from "react-redux";
import store from "./redux-toolkit/Store";
import { ConfigProvider } from "antd";
import { LocationProvider, ScreenProvider } from "./authentication/context/AuthScreen";
import disableConsole from "./utils/consoleDisabler";

// Disable console logs in production to prevent sensitive data exposure
disableConsole();


const themeConfig = {
  token: {
    colorSecondry: "#F2F2F3",
    colorPrimary: "#5AC268", // Change this to your preferred primary color
  },
};


const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(
  <Provider store={store}>
    <AuthProvider>
      <LocationProvider>
        <ScreenProvider>
          <UserProvider>
            <BrowserRouter>
              <ConfigProvider theme={themeConfig}>
                <App />
              </ConfigProvider>
            </BrowserRouter>
          </UserProvider>
        </ScreenProvider>
      </LocationProvider>
    </AuthProvider>
  </Provider>
);

