import React from 'react'
import DefaultImage from "../../assest/png/user.png"
import { Card } from 'antd'
import '../../style/order.css'
import { useParams } from 'react-router-dom'
import VendorAssign from './VendorAssign'

function ReturnVendorInfo({orderData, vendorData,ShowOrderList }) {
    const {id}=useParams()
    return (
        <div >

            <Card 
actions={[<VendorAssign ShowOrderList={ShowOrderList} orderId={id} orderData={orderData} title={vendorData != null ? "Reassign Delivery Rider" : "Assign Delivery Rider"} />]}
                cover={
                    <img
                        className="order_order_img"
                        alt="example"
                        src={vendorData?.profilePic != null ? vendorData?.profilePic : DefaultImage}
                        onError={(e) => e.currentTarget.src = DefaultImage}
                    />
                }

            >
                <Card.Meta
                    title={<div>
                        <p>{vendorData?.fullName}</p>
                    </div>}
                    description={<div>
                        <p>Number : {vendorData?.mobileNo}</p>
                        {/* <p>Gender : {vendorData?.gender}</p>
                        <p>DOB : {new Date(vendorData?.dob).toLocaleDateString()}</p>
                        <p>Locaion : {vendorData?.city}</p> */}
                    </div>}
                />
            </Card>
        </div>
    )
}

export default ReturnVendorInfo
