import React, { useEffect, useState } from 'react'
import "../../style/order.css"
import LogoImg from "../../assest/png/logoIcon.png"
import { useNavigate } from 'react-router-dom'
import { Space, Table, Tag, Card, Button, Avatar, Segmented, message } from 'antd';

import RemoveOrder from './RemoveOrder';
import CanceOrder from './CanceOrder';
import { fetchOrderCancelRemove } from '../../service/api_services';
import { useAuth } from '../../authentication/context/authContext';


function OrderRefund() {
    const {token,logout}=useAuth()
    const [orderType, setOrderType] = useState("REMOVED")
    const [orderData, setOrderData] = useState([])
    const [isLoading, setIsLoading] = useState(false)

    let OrderSegment;

    if (orderType === "REMOVED") {
        OrderSegment = <RemoveOrder orderData={orderData} isLoading={isLoading}/>
    } else if (orderType === "CANCELLED") {
        OrderSegment = <CanceOrder orderData={orderData} isLoading={isLoading}/>
    }

    const ShowOrderHistoryList = async () => {
        try {
            await fetchOrderCancelRemove(token, orderType)
                .then((res) => {
                    console.log("order cancel list", res);
                    if (res.status == 200) {
                        setOrderData(res.data.data.data);
                        setIsLoading(true)
                    }else if (res.data.code == 283) {
                        message.error(res.data.message)
                        logout()

                    }
                })
                .catch((err) => {
                    console.log(err.message);
                });
        } catch (error) {
            console.log(error);
            setIsLoading(true)
        }
    };

    useEffect(() => {
        ShowOrderHistoryList();
    }, [orderType]);


    return (
        <section className="main_Section">
            <div className="content_head">
                <div className="order_content_title">
                    <Card>
                        <div className="order_status_titiles">
                            <div className="order_title">
                                <div className="order_img">
                                    <img src={LogoImg} className="logo_icon" />
                                </div>
                                <div className="order_status">
                                    <h4>Cancel Remove  Refund</h4>
                                    <p>{orderData?.length} {orderType!="REMOVED" ? "Cancel" : "Remove"} Order </p>
                                </div>
                            </div>
                            <div className="order_status_action">
                                <Segmented options={["REMOVED", "CANCELLED"]} onChange={(value) => {
                                    setOrderType(value);
                                    console.log(value); // string
                                }} />
                            </div>
                        </div>
                    </Card>
                </div>


            </div>
            <div className="partner_content">
                {OrderSegment}
            </div>
        </section>
    )
}


export default OrderRefund