import React, { useEffect, useMemo, useState } from "react";
import {
  Avatar,
  Breadcrumb,
  Button,
  Image,
  Input,
  Pagination,
  Table,
  Tag,
  Typography,
  message,
} from "antd";
import "../../style/partner.css";
import {
  LoadingOutlined,
  ReloadOutlined,
  SearchOutlined,
} from "@ant-design/icons";
import { FaRegUser } from "react-icons/fa";
import { useAuth } from "../../authentication/context/authContext";
import {
  fetchDeliveryPartnerList,
  fetchDeliveryPartnerOrdersOverview,
} from "../../service/api_services";
import DefaultImg from "../../assest/chat/user.png";
import RiderOrdersOverviewModal, {
  initialVendorOrdersOverview,
} from "./RiderOrdersOverviewModal";

function ActiveRiders() {
  const { token, logout } = useAuth();
  const { Title } = Typography;

  const [riderList, setRiderList] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [current, setCurrent] = useState(1);
  const [totalPage, setTotalPage] = useState(1);
  const [searchInput, setSearchInput] = useState("");
  const [ordersModalOpen, setOrdersModalOpen] = useState(false);
  const [selectedVendor, setSelectedVendor] = useState(null);
  const [vendorOrdersLoading, setVendorOrdersLoading] = useState(false);
  const [vendorOrdersOverview, setVendorOrdersOverview] = useState(
    initialVendorOrdersOverview
  );

  const showActiveRidersList = async () => {
    setIsLoading(true);
    try {
      const res = await fetchDeliveryPartnerList(token, current, searchInput);

      if (res.status === 200) {
        const list = res?.data?.data?.data || [];
        setRiderList(
          list.filter((item) => item?.status === "ACTIVE" && item?.isOnline === true)
        );
        setTotalPage(res?.data?.data?.totalPage || 1);
      } else if (res?.data?.code === 283) {
        message.error(res?.data?.message);
        logout();
      }
    } catch (error) {
      console.log(error);
      message.error("Failed to fetch active delivery riders");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    showActiveRidersList();
  }, [current, searchInput]);

  const showVendorOrdersOverview = async (vendor) => {
    try {
      setSelectedVendor(vendor);
      setOrdersModalOpen(true);
      setVendorOrdersLoading(true);

      const res = await fetchDeliveryPartnerOrdersOverview(token, vendor?._id);
      if (res.status === 200) {
        setVendorOrdersOverview(res?.data?.data || initialVendorOrdersOverview);
      }
    } catch (error) {
      console.log(error);
      message.error(
            error?.response?.data?.message || "Failed to fetch delivery rider orders overview"
      );
      setVendorOrdersOverview(initialVendorOrdersOverview);
    } finally {
      setVendorOrdersLoading(false);
    }
  };

  const closeOrdersModal = () => {
    setOrdersModalOpen(false);
    setSelectedVendor(null);
    setVendorOrdersOverview(initialVendorOrdersOverview);
  };

  const columns = useMemo(
    () => [
      {
        title: "Image",
        dataIndex: "profilePic",
        key: "profilePic",
        width: 80,
        render: (_, { profilePic }) =>
          profilePic ? (
            <Image
              src={profilePic || DefaultImg}
              onError={(e) => (e.currentTarget.src = DefaultImg)}
              width={46}
              height={46}
              style={{
                borderRadius: "100%",
                objectFit: "contain",
                background: "lightGray",
              }}
            />
          ) : (
            <Avatar size={42} icon={<FaRegUser className="pro_icon" />} />
          ),
      },
      {
        title: "Name",
        dataIndex: "fullName",
        key: "fullName",
        ellipsis: true,
      },
      {
        title: "Number",
        dataIndex: "mobileNo",
        key: "mobileNo",
      },
      {
        title: "Vehicle Type",
        dataIndex: "vehicle",
        key: "vehicle",
        render: (vehicle) => vehicle || "N/A",
      },
      {
        title: "Vehicle Number",
        dataIndex: "vehilceNo",
        key: "vehilceNo",
        render: (vehilceNo) => vehilceNo || "N/A",
      },
      {
        title: "Live Orders",
        dataIndex: "liveOrders",
        key: "liveOrders",
        render: (liveOrders) => liveOrders || 0,
      },
      {
        title: "Total Orders",
        dataIndex: "totalOrderAssign",
        key: "totalOrderAssign",
        render: (totalOrderAssign) => totalOrderAssign || 0,
      },
      {
        title: "Outstanding Amount",
        dataIndex: "outStandingBalance",
        key: "outStandingBalance",
        render: (outStandingBalance) => {
          const amount = Number(outStandingBalance || 0);
          const hasOutstanding = amount > 0;

          return (
            <span
              className={`rider-outstanding-pill ${
                hasOutstanding ? "has-outstanding" : "no-outstanding"
              }`}
            >
              {`Rs. ${amount.toFixed(2)}`}
            </span>
          );
        },
      },
      {
        title: "Available",
        key: "isOnline",
        dataIndex: "isOnline",
        render: () => <Tag color="green">Online</Tag>,
      },
      {
        title: "Action",
        key: "action",
        render: (_, record) => (
          <Button type="link" onClick={() => showVendorOrdersOverview(record)}>
            View Orders
          </Button>
        ),
      },
    ],
    []
  );

  return (
    <section className="main_Section">
      <Breadcrumb
        items={[
          { title: "Dashboard" },
          { title: "Delivery Rider" },
      { title: "Active Delivery Riders" },
        ]}
      />

      <div className="content_title">
        <div className="content_head">
          <div className="content_titles">
            <div className="hear_title">
          <Title level={4}>Active Delivery Riders</Title>
            </div>
          </div>
        </div>

        <div className="manage-riders-toolbar">
          <div className="manage-riders-search">
            <Input
              allowClear
              placeholder="Search Name Or Number"
              suffix={<SearchOutlined />}
              value={searchInput}
              onChange={(e) => {
                setCurrent(1);
                setSearchInput(e.target.value);
              }}
            />
          </div>

          <Button
            type="primary"
            shape="round"
            className="manage-riders-refresh-btn"
            onClick={showActiveRidersList}
            loading={isLoading}
            icon={isLoading ? <LoadingOutlined /> : <ReloadOutlined />}
          >
            Refresh
          </Button>
        </div>

        <div className="content">
          <div className="shoo_recent_order">
            <Table
              rowKey={(record) => record?._id}
              columns={columns}
              dataSource={riderList}
              loading={isLoading}
              scroll={{ x: true }}
              pagination={false}
        locale={{ emptyText: "No active delivery riders found" }}
              footer={() => (
                <div className="pagination">
                  <Pagination
                    current={current}
                    onChange={(page) => setCurrent(page)}
                    total={totalPage * 10}
                  />
                </div>
              )}
            />
          </div>
        </div>
      </div>

      <RiderOrdersOverviewModal
        open={ordersModalOpen}
        onCancel={closeOrdersModal}
        selectedVendor={selectedVendor}
        vendorOrdersLoading={vendorOrdersLoading}
        vendorOrdersOverview={vendorOrdersOverview}
      />
    </section>
  );
}

export default ActiveRiders;
