import { Navigate } from "react-router-dom";
import LoginPage from "../authentication/login/LoginPage";
// import HistoryDetails from "../component/OrderHistory/HistoryDetails";
import OrderHistory from "../component/OrderHistory/OrderHistory";
import OrderHistoryDetails from "../component/OrderHistory/OrderHistoryDetails";
import OrderRefund from "../component/OrderHistory/OrderRefund";
import OrderComplaints from "../component/complaints/OrderComplaints";
import KotDetails from "../component/OrderManage/KotDetails";
import OrderDetails from "../component/OrderManage/OrderDetails";
import OrderList from "../component/OrderManage/OrderList";
import AdminDashboard from "../component/dashboard/AdminDashboard";
import ActiveRiders from "../component/deliveryBoyManage/ActiveRiders";
import MainLayout from "../component/dashboard/MainLayout";
import DeliveryPartner from "../component/deliveryBoyManage/DeliveryPartner";
import ManageRiders from "../component/deliveryBoyManage/ManageRiders";
import PickupCodePayment from "../component/pickupPayment/PickupCodePayment";
import RiderCashCollection from "../component/riderCashCollection/RiderCashCollection";
import RiderOrderCashCollection from "../component/riderOrderCashCollection/RiderOrderCashCollection";
import ReturnReplaceDetails from "../component/retunreplace/ReturnReplaceDetails";
import ReturnReplaceHistory from "../component/retunreplace/ReturnReplaceHistory";
import ReturnReplaceOrder from "../component/retunreplace/ReturnReplaceOrder";

// Main routes object with child routes
const routes = [
  {
    path: "/",
    element: <LoginPage />,
  },
  {
    path: "/",
    element: <MainLayout />,
    children: [
      {
        path: "/dashboard",
        element: <AdminDashboard />,
      },
      {
        path: "/dashboard/order",
        element: <OrderList />,
      },
      {
        path: "/dashboard/order-details/:id",
        element: <OrderDetails />,
      },
      {
        path: "/dashboard/order-history-details/:id",
        element: <OrderHistoryDetails />,
      },
      {
        path: "/dashboard/return-replace",
        element: <ReturnReplaceOrder />,
      },
      {
        path: "/dashboard/return-replace-details/:id",
        element: <ReturnReplaceDetails />,
      },
      {
        path: "/dashboard/delivery-partner",
        element: <Navigate to="/dashboard/delivery-rider/all" replace />,
      },
      {
        path: "/dashboard/delivery-rider/all",
        element: <DeliveryPartner />,
      },
      {
        path: "/dashboard/delivery-rider/active",
        element: <ActiveRiders />,
      },
      {
        path: "/dashboard/delivery-rider/manage",
        element: <ManageRiders />,
      },

      {
        path: "/dashboard/order-history",
        element: <OrderHistory />,
      },
      {
        path: "/dashboard/return-order-history",
        element: <ReturnReplaceHistory />,
      },
      {
        path: "/dashboard/order-refund",
        element: <OrderRefund />,
      },
      {
        path: "/dashboard/pickup-cod-payment",
        element: <PickupCodePayment />,
      },
      {
        path: "/dashboard/rider-cash-collection",
        element: <RiderCashCollection />,
      },
      {
        path: "/dashboard/rider-order-cod-collection",
        element: <RiderOrderCashCollection />,
      },
      {
        path: "/dashboard/order-complaints",
        element: <OrderComplaints />,
      },
      
      {
        path: "/dashboard/kot-details/:id",
        element: <KotDetails />,
      },
    ],
  },
];

export default routes;
