import React, { useEffect, useState } from "react";
import {
  Breadcrumb,
  Button,
  Drawer,
  Input,
  Pagination,
  Select,
  Space,
  Table,
  Tabs,
  Tag,
  Typography,
  message,
} from "antd";
import { EyeOutlined, SearchOutlined } from "@ant-design/icons";
import { fetchBranchOrderComplaintList, replyBranchOrderComplaint } from "../../service/api_services";
import { useAuth } from "../../authentication/context/authContext";

const { Title, Text, Paragraph } = Typography;
const PAGE_SIZE = 20;

const STATUS_COLORS = {
  PENDING: "orange",
  IN_PROGRESS: "blue",
  RESOLVED: "green",
  REJECTED: "red",
};

const STATUS_OPTIONS = [
  { label: "Pending", value: "PENDING" },
  { label: "In Progress", value: "IN_PROGRESS" },
  { label: "Resolved", value: "RESOLVED" },
  { label: "Rejected", value: "REJECTED" },
];

function OrderComplaints() {
  const { token, logout } = useAuth();
  const [activeTab, setActiveTab] = useState("OPEN");
  const [complaints, setComplaints] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [current, setCurrent] = useState(1);
  const [isLoading, setIsLoading] = useState(false);
  const [searchInput, setSearchInput] = useState("");
  const [searchTrigger, setSearchTrigger] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [selected, setSelected] = useState(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [replyMessage, setReplyMessage] = useState("");
  const [replyLoading, setReplyLoading] = useState(false);

  const formatDate = (val) =>
    val
      ? new Date(val).toLocaleString("en-IN", {
          day: "2-digit",
          month: "2-digit",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        })
      : "N/A";

  const fetchComplaints = async () => {
    setIsLoading(true);
    try {
      const params = {
        type: activeTab,
        complaintType: "ORDER",
        raisedByRole: "BRANCH",
        page: current,
        size: PAGE_SIZE,
      };
      if (searchTrigger) params.search = searchTrigger;
      if (statusFilter) params.requestStatus = statusFilter;

      const res = await fetchBranchOrderComplaintList(token, params);
      if (res.status === 200) {
        const data = res?.data?.data || {};
        const list = data?.rows || data?.data || (Array.isArray(data) ? data : []);
        setComplaints(Array.isArray(list) ? list : []);
        setTotalCount(data?.count ?? data?.totalCount ?? 0);
      } else if (res?.data?.code === 283) {
        message.error(res?.data?.message);
        logout();
      }
    } catch (error) {
      message.error(error?.response?.data?.message || "Unable to load complaints.");
      setComplaints([]);
      setTotalCount(0);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchComplaints();
  }, [activeTab, current, searchTrigger, statusFilter]);

  const openDrawer = (record) => {
    setSelected(record);
    setReplyMessage("");
    setDrawerOpen(true);
  };

  const closeDrawer = () => {
    if (replyLoading) return;
    setDrawerOpen(false);
    setSelected(null);
    setReplyMessage("");
  };

  const handleReply = async () => {
    if (!selected?._id || !replyMessage.trim()) {
      message.warning("Please enter a reply.");
      return;
    }
    setReplyLoading(true);
    try {
      const res = await replyBranchOrderComplaint(token, selected._id, {
        message: replyMessage.trim(),
      });
      if (res.status === 200 || res.status === 201) {
        message.success(res?.data?.message || "Reply sent.");
        setReplyMessage("");
        const updated = res?.data?.data;
        if (updated?._id === selected._id) setSelected(updated);
        fetchComplaints();
      } else {
        message.warning(res?.data?.message || "Unable to send reply.");
      }
    } catch (error) {
      message.error(error?.response?.data?.message || "Unable to send reply.");
    } finally {
      setReplyLoading(false);
    }
  };

  const isClosed = selected?.requestStatus === "RESOLVED" || selected?.requestStatus === "REJECTED";

  const columns = [
    {
      title: "Complaint",
      key: "complaintCode",
      width: 180,
      render: (_, record) => (
        <div>
          <div style={{ fontWeight: 600 }}>{record?.complaintCode || "N/A"}</div>
          <div style={{ fontSize: 12, color: "#64748b" }}>{record?.title || "N/A"}</div>
        </div>
      ),
    },
    {
      title: "Order",
      dataIndex: "orderCode",
      key: "orderCode",
      width: 150,
      render: (value) => value || "N/A",
    },
    {
      title: "Delivery Rider",
      key: "deliveryRider",
      width: 190,
      render: (_, record) => (
        <div>
          <div>{record?.vendorId?.fullName || record?.vendorName || "N/A"}</div>
          <div style={{ fontSize: 12, color: "#64748b" }}>{record?.vendorId?.mobileNo || record?.vendorMobileNo || ""}</div>
        </div>
      ),
    },
    {
      title: "Status",
      dataIndex: "requestStatus",
      key: "requestStatus",
      width: 130,
      render: (value) => <Tag color={STATUS_COLORS[value] || "default"}>{value || "PENDING"}</Tag>,
    },
    {
      title: "Created On",
      dataIndex: "addedDate",
      key: "addedDate",
      width: 170,
      render: (value) => formatDate(value),
    },
    {
      title: "Action",
      key: "action",
      width: 90,
      fixed: "right",
      render: (_, record) => (
        <Button type="primary" shape="circle" icon={<EyeOutlined />} onClick={() => openDrawer(record)} />
      ),
    },
  ];

  return (
    <section className="main_Section">
      <Breadcrumb items={[{ title: "Dashboard" }, { title: "Order Complaints" }]} />
      <div className="content_title">
        <div className="content_head">
          <Title level={4}>Order Complaints</Title>
          <Button type="primary" onClick={fetchComplaints} loading={isLoading}>
            Refresh
          </Button>
        </div>

        <div className="pro_selector">
          <Space wrap>
            <Input
              allowClear
              style={{ width: 260 }}
              placeholder="Search complaint / order / rider"
              suffix={<SearchOutlined />}
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              onPressEnter={() => {
                setCurrent(1);
                setSearchTrigger(searchInput.trim());
              }}
            />
            <Select
              allowClear
              placeholder="Filter by Status"
              style={{ width: 180 }}
              value={statusFilter || undefined}
              options={STATUS_OPTIONS}
              onChange={(value) => {
                setCurrent(1);
                setStatusFilter(value || "");
              }}
            />
            <Button
              onClick={() => {
                setCurrent(1);
                setSearchTrigger(searchInput.trim());
              }}
            >
              Search
            </Button>
          </Space>
        </div>

        <Tabs
          activeKey={activeTab}
          onChange={(key) => {
            setActiveTab(key);
            setCurrent(1);
          }}
          items={[
            { key: "OPEN", label: "Open" },
            { key: "CLOSED", label: "Closed" },
            { key: "ALL", label: "All" },
          ]}
        />

        <div className="content">
          <Table
            rowKey={(record) => record?._id}
            columns={columns}
            dataSource={complaints}
            pagination={false}
            loading={isLoading}
            scroll={{ x: 900 }}
            footer={() => (
              <Pagination
                current={current}
                onChange={(page) => setCurrent(page)}
                total={totalCount}
                pageSize={PAGE_SIZE}
                showSizeChanger={false}
              />
            )}
          />
        </div>
      </div>

      <Drawer title="Complaint Details" placement="right" width={520} onClose={closeDrawer} open={drawerOpen} destroyOnClose>
        {selected ? (
          <Space direction="vertical" size={16} style={{ width: "100%" }}>
            <Space wrap>
              <Tag color={STATUS_COLORS[selected?.requestStatus] || "default"}>{selected?.requestStatus || "PENDING"}</Tag>
              <Tag>Branch to Admin</Tag>
              <Text strong>{selected?.complaintCode}</Text>
            </Space>

            <div>
              <Title level={5} style={{ marginBottom: 4 }}>{selected?.title || "N/A"}</Title>
              <Paragraph style={{ marginBottom: 0 }}>{selected?.description || "No description provided."}</Paragraph>
            </div>

            <div className="order-complaint-summary">
              <div>
                <span>Order</span>
                <strong>{selected?.orderCode || "N/A"}</strong>
              </div>
              <div>
                <span>Delivery Rider</span>
                <strong>{selected?.vendorId?.fullName || selected?.vendorName || "N/A"}</strong>
              </div>
              <div>
                <span>Created</span>
                <strong>{formatDate(selected?.addedDate)}</strong>
              </div>
            </div>

            {Array.isArray(selected?.replies) && selected.replies.length > 0 ? (
              <div>
                <Text strong>Conversation</Text>
                <div style={{ marginTop: 8, display: "flex", flexDirection: "column", gap: 8 }}>
                  {selected.replies.map((reply) => {
                    const replyRole = reply?.byRole || "USER";
                    const isAdmin = replyRole === "ADMIN";
                    return (
                      <div
                        key={reply?._id || reply?.addedDate}
                        style={{
                          background: isAdmin ? "#eff6ff" : "#f8fafc",
                          border: `1px solid ${isAdmin ? "#bfdbfe" : "#e5e7eb"}`,
                          borderRadius: 8,
                          padding: 10,
                        }}
                      >
                        <div style={{ fontSize: 12, color: "#64748b", marginBottom: 4 }}>
                          {reply?.byName || replyRole} · {formatDate(reply?.addedDate)}
                        </div>
                        <div>{reply?.message || ""}</div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ) : null}

            {selected?.resolutionNote ? (
              <div style={{ background: "#f0fdf4", border: "1px solid #bbf7d0", borderRadius: 8, padding: 12 }}>
                <Text strong>Resolution Note</Text>
                <Paragraph style={{ marginBottom: 0, marginTop: 4 }}>{selected.resolutionNote}</Paragraph>
              </div>
            ) : null}

            {!isClosed ? (
              <div>
                <Text strong>Reply to Admin</Text>
                <Input.TextArea
                  rows={3}
                  placeholder="Add more information for admin"
                  value={replyMessage}
                  onChange={(e) => setReplyMessage(e.target.value)}
                  style={{ marginTop: 6 }}
                />
                <Button type="primary" style={{ marginTop: 8 }} loading={replyLoading} disabled={!replyMessage.trim()} onClick={handleReply}>
                  Send Reply
                </Button>
              </div>
            ) : null}
          </Space>
        ) : null}
      </Drawer>
    </section>
  );
}

export default OrderComplaints;
