import React, { useState } from "react";
import { Button, Form, Input, message, Modal, Tooltip } from "antd";
import { ExclamationCircleOutlined } from "@ant-design/icons";
import { useAuth } from "../../authentication/context/authContext";
import { CreateBranchOrderComplaint } from "../../service/api_services";

const getAssignedRiderName = (order) => {
    const rider = order?.vendorId;
    if (rider && typeof rider === "object" && Object.keys(rider).length > 0) {
        return rider.fullName || rider.vendorName || "N/A";
    }
    return order?.vendorName || order?.vendorFullName || "N/A";
};

function OrderComplaintAction({ order, buttonProps = {}, label = "", tooltip = "Raise order complaint" }) {
    const { token } = useAuth();
    const [form] = Form.useForm();
    const [open, setOpen] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    const openModal = (event) => {
        event?.stopPropagation();
        setOpen(true);
        form.resetFields();
    };

    const closeModal = (force = false) => {
        if (isSubmitting && !force) return;
        setOpen(false);
        form.resetFields();
    };

    const submitComplaint = async (values) => {
        if (!order?._id) return;
        setIsSubmitting(true);
        try {
            const res = await CreateBranchOrderComplaint(order._id, {
                title: values.title,
                description: values.description,
            }, token);

            if (res.status === 201 || res.data?.code === 201) {
                message.success(res.data?.message || "Complaint submitted to admin");
                closeModal(true);
            } else {
                message.warning(res.data?.message || "Unable to submit complaint");
            }
        } catch (error) {
            message.error(error?.response?.data?.message || error?.message || "Unable to submit complaint");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <>
            <Tooltip title={tooltip}>
                <Button icon={<ExclamationCircleOutlined />} {...buttonProps} onClick={openModal}>
                    {label}
                </Button>
            </Tooltip>
            <Modal
                title="Raise Order Complaint"
                open={open}
                onCancel={() => closeModal()}
                footer={false}
                destroyOnClose
                width={460}
            >
                <div className="order-complaint-summary">
                    <div>
                        <span>Order</span>
                        <strong>#{order?.orderCode || "N/A"}</strong>
                    </div>
                    <div>
                        <span>Customer</span>
                        <strong>{order?.userId?.fullName || "N/A"}</strong>
                    </div>
                    <div>
                        <span>Delivery Rider</span>
                        <strong>{getAssignedRiderName(order)}</strong>
                    </div>
                </div>
                <Form form={form} onFinish={submitComplaint} layout="vertical" className="order-complaint-form">
                    <Form.Item label="Subject" name="title" rules={[{ required: true, message: "Please enter complaint subject" }]}>
                        <Input maxLength={200} placeholder="Example: Wrong packing / rider issue / order issue" />
                    </Form.Item>
                    <Form.Item label="Complaint Details" name="description" rules={[{ required: true, message: "Please enter complaint details" }]}>
                        <Input.TextArea rows={4} maxLength={2000} showCount placeholder="Explain what admin needs to check for this order" />
                    </Form.Item>
                    <Form.Item style={{ marginBottom: 0 }}>
                        <Button loading={isSubmitting} htmlType="submit" shape="round" block className="submitBtn">
                            Submit Complaint
                        </Button>
                    </Form.Item>
                </Form>
            </Modal>
        </>
    );
}

export default OrderComplaintAction;
