import React, { useEffect, useState } from 'react';
import { Button, Modal, Skeleton, message } from 'antd';
import { fetchKotAllDetails } from '../../service/api_services';
import KOT from './KOT';
import { MdLocalPrintshop } from 'react-icons/md';
import { useAuth } from '../../authentication/context/authContext';
import { useLocation } from 'react-router-dom';
import '../../style/order.css'
import { useScreen } from '../../authentication/context/AuthScreen';

const KotDetails = ({ orderId }) => {
    const { screenWidth } = useScreen();
    const location = useLocation()
    console.log("location", location)
    const { token } = useAuth()
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [kotData, setKotData] = useState(null);
    const [isLoading, setIsLoading] = useState(false)

    const showModal = () => {
        setIsModalOpen(true);
        ShowKotDetails();

    };
    const handleOk = () => {
        setIsModalOpen(false);
    };
    const handleCancel = () => {
        setIsModalOpen(false);
    };


    const ShowKotDetails = async () => {
        setIsLoading(true)
        setKotData(null)
        try {
            const res = await fetchKotAllDetails(token, orderId)
            console.log("kot info", res);
            if (res.status == 200) {
                setKotData(res.data.data);
            }
        } catch (error) {
            console.log(error);
            message.error(error?.response?.data?.data || error?.response?.data?.message || "Unable to fetch KOT details");
            setIsModalOpen(false);
        } finally {
            setIsLoading(false)
        }
    };




    return (
        <>
            {location?.pathname ===
                "/dashboard/order" ?
                <Button
                    size="large"
                    shape="circle"
                    onClick={showModal}
                    className="kot-print-icon-btn"
                    aria-label="Print KOT"
                    icon={<MdLocalPrintshop className="order_icons" />}
                ></Button>
                :
                <Button
                    size={screenWidth < 768 ? "small" : "middle"}
                    style={{ backgroundColor: "#2671eb" }}
                    icon={<MdLocalPrintshop />}
                    onClick={showModal}
                    shape="round"
                >
                    Print KOT
                </Button>}

            <Modal width={360} footer={false} style={{
                top: 10
            }}
                open={isModalOpen} onOk={handleOk} onCancel={handleCancel}>
                <div className="bill-containers">
                    {isLoading ? <Skeleton active /> : kotData ? <KOT data={kotData} handleCancel={handleCancel} /> : null}
                </div>
            </Modal>
        </>
    );
};
export default KotDetails
