import { Button, Form, Input, message, notification, Popconfirm } from "antd";
import React, { useEffect, useRef, useState } from "react";
import OtpInput from "react-otp-input";
import "../../style/order.css";
// import { VerifyOTPS } from "../apiService/api";
import { useNavigate, useParams } from "react-router-dom";
import { PickupOrderOtpVerify } from "../../service/api_services";
import { useAuth } from "../../authentication/context/authContext";

function PickupOtpVerify() {
  const { token } = useAuth()
  const focusOtp = useRef()
  const navigate = useNavigate()
  const { id } = useParams()
  const [otp, setOtp] = useState(0);


  useEffect(() => {
    if (focusOtp.current) {
      focusOtp.current.focus();
    }
  }, []);


  const submitHandler = async () => {
    const body = {
      requestOrderStatus: "DELIVERED",
      userOrderId: id,
      orderOtp: otp,
    }
    try {
      await PickupOrderOtpVerify(body, token)
        .then((res) => {
          console.log("verify otp", res);
          if (res.status == 201) {
            navigate("/dashboard/order")
            notification.success({
              placement: "topRight",
              message: res.data.message,
            });

          } else if (res.status === 200) {
            notification.error({
              placement: "topRight",
              message: res.data.message,
            });
          }
        })
        .catch((err) => {
          console.log(err.message);
        });
    } catch (error) {
      console.log(error);
    }
  };

  const cancel = (e) => {
    console.log(e);
    message.error('Click on No');
  };

  return (
    <div className="otp_verification">

      <div className="otp_vefiyed">
        <OtpInput
          value={otp}
          onChange={setOtp}
          numInputs={4}
          placeholder={0}
          inputType="numeric"
          // renderSeparator={<span>-</span>}
          renderInput={(props, index) => (
            <div className="ot_field">
              <Form.Item>

                <Input ref={focusOtp}  {...props} style={{ width: "2.5rem", height: "2.5rem" }} placeholder="0" variant="filled"
                  // type="number"
                  inputMode="numeric"
                  pattern="[0-9]*" />
              </Form.Item>
            </div>
          )}
        />


        <div className="verify_continue">
          <Popconfirm
            title=" Payment OTP Verify"
            description="Are you sure to collect amount and verify otp?"
            onConfirm={submitHandler}
            onCancel={cancel}
            okText="Yes"
            cancelText="No"
            placement="topLeft"

          >

            <Button shape="round" type="default" >Submit</Button>
          </Popconfirm>
        </div>
      </div>
    </div>
  );
}


export default PickupOtpVerify