

import React, { useEffect, useState } from 'react';
import { Avatar, Button, Divider, Image, List, message, Modal, Skeleton, Space } from 'antd';
import { useAuth } from '../../authentication/context/authContext';
import "../../style/order.css"
import { useDispatch, useSelector } from 'react-redux';
import { addItem, fetchCartProducts, removeCartItem, selectCartItems } from '../../redux-toolkit/CartSlice';
import { fetchMultipleProductDetails, fetchProductDetails } from '../../service/api_services';
import BKDLogo from "../../assest/chat/logo.png";
import DefaulImg from "../../assest/icon/bkd logo (1).png";
import RemoveItemDetails from './RemoveItemDetails';

export const formatCurrency = (value) => {
    const amount = Number(value);
    return Number.isFinite(amount) ? `Rs. ${amount.toFixed(2)}` : "Rs. 0.00";
};

export const parseOfferPattern = (offerQtyStr) => {
    if (!offerQtyStr || typeof offerQtyStr !== 'string') return null;
    const parts = offerQtyStr.split('+');
    if (parts.length !== 2) return null;
    const billing = parseInt(parts[0], 10);
    const free = parseInt(parts[1], 10);
    if (isNaN(billing) || isNaN(free)) return null;
    return { billingPerCombo: billing, freePerCombo: free, comboSize: billing + free };
};

export const getPromotionsComboOffer = (item) => {
    if (!item.productOffer?.length) return null;
    const candidates = item.productOffer.filter(
        (o) => o.comboPrice > 0 && o.comboPrice < item.bkdAmount && (!o.promoProductList || o.promoProductList.length === 0)
    );
    if (!candidates.length) return null;
    return candidates.reduce((best, o) => {
        const perUnit = o.comboPrice / o.billingQty;
        const bestPerUnit = best.comboPrice / best.billingQty;
        if (perUnit < bestPerUnit) return o;
        if (perUnit === bestPerUnit && o.billingQty < best.billingQty) return o;
        return best;
    });
};

const EditProductsModal = ({ orderDetailsData, ShowOrderList, open, onClose }) => {
    const { token, branchData } = useAuth();
    const dispatch = useDispatch();
    const cartItem = useSelector(selectCartItems);
    const [isReviewLoad, setIsReviewLoad] = useState(false)

    useEffect(() => {
        if (!cartItem?.length) return;

        const alreadyLoaded = cartItem.every(
            (item) => item.finalPrice !== undefined
        );

        if (alreadyLoaded) return;

        let active = true;

        const loadProductDetails = async () => {
            try {
                setIsReviewLoad(true);
                const productCodeArr = [...new Set(cartItem?.map((item) => item?.productCode)?.filter(Boolean))];

                const res = await fetchMultipleProductDetails(productCodeArr, branchData?.branchCode);

                if (active && res?.status === 200) {
                    const products = res?.data?.data || [];

                    const updatedCart = cartItem.map((cart) => {
                        const detail = products.find((p) => p.productCode === cart.productCode);

                        if (!detail) return cart;
                        let finalPrice = 0;

                        if (cart?.offerTypeName === "DISCOUNT" && cart?.offerProduct) {
                            finalPrice = (Number(cart?.unit || 0) / Number(cart?.offerProduct?.offerQuantity || 1))
                                * Number(detail?.productOffer?.[0]?.comboPrice || 0);

                        } else if (cart?.offerTypeName === "PROMOTIONS" && cart?.offerProduct) {
                            const bestOffer = getPromotionsComboOffer(detail)
                            finalPrice = (Number(cart?.unit || 0) / Number(cart?.offerProduct?.offerQuantity || 1))
                                * Number(bestOffer ? (bestOffer?.comboPrice || 0) : Number(detail?.productOffer?.[0]?.comboPrice || 0));

                        } else if (cart?.offerTypeName === "FOC" && cart?.offerProduct) {
                            const price = (detail?.productOffer?.[0]?.comboPrice || 0) > 0 ? detail?.productOffer?.[0]?.comboPrice : detail?.bkdAmount
                            finalPrice = Number(cart?.requiredOfferedBillingQty || 1) * Number(price);

                        } else if (parseOfferPattern(cart?.offerQty) && cart?.offerProduct) {
                            finalPrice = Number(cart?.requiredOfferedBillingQty || 1) * Number(detail?.productOffer?.[0]?.comboPrice || 0);

                        } else {
                            finalPrice = Number(cart?.quantity || 1) * Number(detail?.bkdAmount || 0);
                        }

                        return {
                            ...cart,
                            bkdAmount: detail?.bkdAmount,
                            mrpPrice: detail?.price,
                            requiredOfferedBillingPrice:
                                cart?.offerProduct === null ? (
                                    detail?.bkdAmount
                                ) : (
                                    cart?.offerTypeName === "PROMOTIONS"
                                        ? getPromotionsComboOffer(detail)?.comboPrice || detail?.bkdAmount
                                        : (detail?.productOffer?.[0]?.comboPrice || 0) > 0 ? detail?.productOffer?.[0]?.comboPrice : detail?.bkdAmount
                                ),
                            productPrice: detail?.productPrice || cart.productPrice,
                            price: detail?.price,
                            finalPrice: finalPrice,
                        };
                    });

                    dispatch(fetchCartProducts(updatedCart));
                    localStorage.setItem("cart", JSON.stringify(cartItem));
                }
            } catch (error) {
                message.error("Error fetching product details", error);
            } finally {
                if (active) {
                    setIsReviewLoad(false);
                }
            }
        };

        loadProductDetails();

        return () => {
            active = false;
        };
    }, [cartItem, branchData?.branchCode]);

    useEffect(() => {
        localStorage.setItem("cart", JSON.stringify(cartItem));
    }, [cartItem]);

    const handleAddItem = (item) => {
        let incrementBy = 1;
        let freeIncrease = 0;

        if ((item?.offerTypeName === "DISCOUNT" || item?.offerTypeName === "PROMOTIONS") && item?.offerProduct) {
            incrementBy = Number(item?.offerProduct?.offerQuantity || 1);
            freeIncrease = incrementBy;

        } else if (parseOfferPattern(item.offerQty) && item?.offerProduct) {
            const offerPattern = parseOfferPattern(item.offerQty);
            if (offerPattern) {
                incrementBy = offerPattern.comboSize;
                freeIncrease = offerPattern.freePerCombo;
            }
        } else if ((item?.offerTypeName === "FOC") && item?.offerProduct) {
            incrementBy = 1;
            freeIncrease = 1;
        }

        dispatch(
            addItem({
                ...item,
                incrementBy,
                freeIncrease,
            })
        );
    };

    const handleDelItem = (item) => {
        let decrementBy = 1;
        let freeDecrease = 0;

        if ((item?.offerTypeName === "DISCOUNT" || item?.offerTypeName === "PROMOTIONS") && item?.offerProduct) {
            decrementBy = Number(item?.offerProduct?.offerQuantity || 1);
            freeDecrease = decrementBy;

        } else if (parseOfferPattern(item.offerQty) && item?.offerProduct) {
            const offerPattern = parseOfferPattern(item.offerQty);
            if (offerPattern) {
                decrementBy = offerPattern.comboSize;
                freeDecrease = offerPattern.freePerCombo;
            }

        } else if ((item?.offerTypeName === "FOC") && item?.offerProduct) {
            decrementBy = 1;
            freeDecrease = 1;
        }

        dispatch(
            removeCartItem({
                productCode: item.productCode,
                offerTypeName: item.offerTypeName,
                hasOfferProduct: !!item.offerProduct,
                decrementBy,
                freeDecrease,
            })
        );
    };

    return (
        <Modal
            style={{ top: 20 }}
            width={800}
            loading={false}
            footer={false}
            title="Edit Products"
            open={open}
            onCancel={onClose}
        >
            <div className="show_data">
                {isReviewLoad ?
                    <Skeleton active />
                    :
                    <>
                        <div className="order_list_items order_list_edit_items order_scroll_wrapper">
                            <List
                                itemLayout="horizontal"
                                dataSource={cartItem}
                                renderItem={(item, index) => {
                                    const currentQty = item.unit || 0;
                                    let displayBillingQty = currentQty;
                                    let displayFreeQty = 0;

                                    const offerPattern = (item.offerQty && item.offerProduct) ? parseOfferPattern(item.offerQty) : null;

                                    if (offerPattern && currentQty > 0) {
                                        const numCombos = Math.floor(currentQty / offerPattern.comboSize);
                                        displayBillingQty = numCombos * offerPattern.billingPerCombo;
                                        displayFreeQty = numCombos * offerPattern.freePerCombo;
                                    } else if ((item?.offerTypeName === "FOC" || item?.offerTypeName === "PROMOTIONS") && item?.offerProduct) {
                                        displayBillingQty = Number(item?.unit);
                                        displayFreeQty = Number(item?.offerProduct.quantity);
                                    }

                                    return (
                                        <List.Item
                                            key={`${item.productCode}-${index}`}
                                            className={item.status === "REMOVED" || item.unit === 0 ? "remove_items_select" : ""}
                                            actions={[
                                                <Space>
                                                    <div className="price_action">
                                                        <b>{formatCurrency(item?.finalPrice || 0)}</b>
                                                        <Button.Group>
                                                            <Button
                                                                type="primary"
                                                                disabled={item.unit === 0}
                                                                onClick={() => handleDelItem(item)}
                                                            >
                                                                -
                                                            </Button>
                                                            <Button type="primary">
                                                                {displayBillingQty}
                                                                {displayFreeQty > 0 && (
                                                                    <span style={{ fontSize: '10px', marginLeft: '2px' }}>
                                                                        +{displayFreeQty}
                                                                    </span>
                                                                )}
                                                            </Button>
                                                            <Button type="primary" onClick={() => handleAddItem(item)}>
                                                                +
                                                            </Button>
                                                        </Button.Group>
                                                    </div>
                                                </Space>
                                            ]}
                                        >
                                            <List.Item.Meta
                                                avatar={
                                                    item.imageUrl ? (
                                                        <Image src={item.imageUrl || BKDLogo} className="order_images" width={50} />
                                                    ) : (
                                                        <Avatar size={50} shape="square" src={DefaulImg} className="order_images" />
                                                    )
                                                }
                                                title={<p><span>{item.productName}</span></p>}
                                                description={
                                                    <div>
                                                        <Space>
                                                            <p>{item.packSize}</p>
                                                            <p>
                                                                Qty. {displayBillingQty}
                                                                {displayFreeQty > 0 && (
                                                                    <span style={{ color: '#52c41a', marginLeft: '4px' }}>
                                                                        + {displayFreeQty} Free
                                                                    </span>
                                                                )}
                                                            </p>
                                                            <strong>{formatCurrency(item?.finalPrice || 0)}</strong>
                                                        </Space>
                                                        {item.offerProduct && (
                                                            <>
                                                                <div style={{ fontSize: '12px', color: '#1890ff', marginTop: '4px' }}>
                                                                    Offer: {item.offerQty || 'Special Offer'}
                                                                </div>
                                                                <div className="order-offer-line">
                                                                    <div className="order-offer-title">{item.offerProduct.productName}</div>
                                                                    <div className="order-product-meta-row order-offer-meta">
                                                                        <span>{item.offerProduct.packSize}</span>
                                                                        <span>Qty. {item.offerProduct.quantity}</span>{" "}
                                                                        <span><del>{formatCurrency(item.offerProduct.mrpPrice)}</del></span>
                                                                        {item.offerProduct.productPrice === 0 ? <span className="offer_product">Free</span> : null}
                                                                    </div>
                                                                </div>
                                                            </>
                                                        )}
                                                    </div>
                                                }
                                            />
                                        </List.Item>
                                    );
                                }}
                            />
                        </div>

                        <RemoveItemDetails
                            ShowOrderList={ShowOrderList}
                            onClose={onClose}
                            orderDetailsData={orderDetailsData}
                        />
                    </>
                }
            </div>
        </Modal>
    );
};

export default EditProductsModal;
