
// cartSlice.js
import { createSlice } from "@reduxjs/toolkit";
import { notification } from "antd";
const cartData = {
  unit: 1,

};

const cartSlice = createSlice({
  name: "cart",
  initialState: {
    // items: JSON.parse(localStorage.getItem("cart")) || [],
    items: (() => {
      try {
        return JSON.parse(localStorage.getItem("cart")) || [];
      } catch {
        return [];
      }
    })(),
  },
  reducers: {
    fetchCartProducts: (state, action) => {
      state.items = (action.payload);
    },

    addItem: (state, action) => {
      const ItemIndex = state.items.findIndex(
        (item) =>
          item.productCode === action.payload.productCode &&
          item.offerTypeName === action.payload.offerTypeName &&
          !!item.offerProduct === !!action.payload.offerProduct
      );

      if (ItemIndex >= 0) {
        if (action.payload?.quantity > state.items[ItemIndex].unit) {
          state.items[ItemIndex].unit += Number(action.payload.incrementBy || 1);

          if (state.items[ItemIndex]?.offerProduct) {
            state.items[ItemIndex].offerProduct.quantity += Number(action.payload.freeIncrease || 0);
          }

        } else {
          notification.warning({
            placement: "topRight",
            message: "User Selected  Qty. not available! ",
          });
        }

      }
    },
    // Remove item quantity from cart
    removeCartItem: (state, action) => {
      const itemIndex = state.items.findIndex(
        (item) =>
          item.productCode === action.payload.productCode &&
          item.offerTypeName === action.payload.offerTypeName &&
          !!item.offerProduct === action.payload.hasOfferProduct
      );
      const decrementBy = Number(action.payload.decrementBy) || 1;

      const updatedItems = state.items.map((item, index) => {
        if (index === itemIndex) {
          return {
            ...item,
            unit: item.unit - decrementBy,
          };
        }

        return item;
      });

      const willAllZero = updatedItems.every((item) => item.unit <= 0);

      if (willAllZero) {
        notification.warning({
          placement: "topRight",
          message: "Partial Return Not Allowed, Cancel This Order!",
        });

        return;
      }

      // const newQuantity = state.items[itemIndex].unit - decrementBy;
      const newQuantity = Math.max(state.items[itemIndex].unit - decrementBy, 0);

      if (itemIndex >= 0 && state.items[itemIndex].unit > 0) {
        state.items[itemIndex].unit = newQuantity;
        if (state.items[itemIndex]?.offerProduct) {

          state.items[itemIndex].offerProduct.quantity =
            Math.max(Number(state.items[itemIndex]?.offerProduct?.quantity || 0) - Number(action.payload.freeDecrease || 0), 0);
        }

      } else if (itemIndex >= 0 && state.items[itemIndex].unit === 0) {
        state.items = state.items.filter(
          (item) => item.productCode !== action.payload.productCode
        );
      }


    },

    //cleaer item from cart
    clearCart: (state) => {
      state.items = [];
    },
  },
});

export const { addItem, removeCartItem, clearCart, fetchCartProducts } = cartSlice.actions;
export const selectCartItems = (state) => state.cart.items;


export default cartSlice.reducer;

