import { createContext, useState, useContext } from "react";

const AuthContext = createContext();

export const useAuth = () => {
  return useContext(AuthContext);
};

export const AuthProvider = ({ children }) => {
  const [token, setToken] = useState(localStorage.getItem("token")) || null;
  const [branchData, setBranchData] = useState(
    JSON.parse(localStorage.getItem("branchData")) || null
  );
  const [fcmtoken, setFcmToken] = useState(
    localStorage.getItem("fcmtoken") || null
  );
  const [role, setRole] = useState(localStorage.getItem("role") || null)
  const [permissions, setPermissions] = useState(localStorage.getItem("permissions") || [])

  const getRole = (role) => {
    setRole(role)
  }

  const getPermissions = (permission) => {
    setPermissions(permission)
  }

  const login = (newToken) => {
    setToken(newToken);
  };
  const getBranchData = (branch) => {
    setBranchData(branch);
  };


  const logout = () => {
    setToken(null);
    localStorage.clear();
  };


  return (
    <AuthContext.Provider
      value={{ token, login, logout, getBranchData, branchData, setFcmToken, fcmtoken, permissions, role, getRole, getPermissions }}
    >
      {children}
    </AuthContext.Provider>
  );
};
