const matchDeliveryRiderCase = (match, replacement) => {
  if (match === match.toUpperCase()) {
    return replacement.toUpperCase();
  }
  if (match[0] === match[0].toUpperCase()) {
    return replacement;
  }
  return replacement.toLowerCase();
};

export const normalizeDeliveryRiderText = (value) => {
  if (typeof value !== "string") {
    return value;
  }

  return value
    .replace(/\bvendors\b/gi, (match) => matchDeliveryRiderCase(match, "Delivery Riders"))
    .replace(/\bvendor\b/gi, (match) => matchDeliveryRiderCase(match, "Delivery Rider"))
    .replace(/\bvenders\b/gi, (match) => matchDeliveryRiderCase(match, "Delivery Riders"))
    .replace(/\bvender\b/gi, (match) => matchDeliveryRiderCase(match, "Delivery Rider"));
};

const normalizeResponseMessage = (payload) => {
  if (!payload || typeof payload !== "object") {
    return;
  }

  if (typeof payload.message === "string") {
    payload.message = normalizeDeliveryRiderText(payload.message);
  }
  if (typeof payload.data === "string") {
    payload.data = normalizeDeliveryRiderText(payload.data);
  }
};

axios.interceptors.response.use(
  (response) => {
    normalizeResponseMessage(response?.data);
    return response;
  },
  (error) => {
    normalizeResponseMessage(error?.response?.data);
    return Promise.reject(error);
  }
);

