/**
 * Security Utilities for Production Build
 * Implements client-side obfuscation to make reverse engineering harder
 * 
 * NOTE: These are obfuscation techniques, NOT true security
 * Determined attackers can still bypass these measures
 */

/**
 * Disable console logs in production
 */
export const disableConsoleInProduction = () => {
    if (process.env.NODE_ENV === 'production') {
        const noop = () => { };
        const methods = ['log', 'debug', 'info', 'warn', 'error', 'trace', 'dir', 'group', 'groupCollapsed', 'groupEnd', 'time', 'timeEnd', 'profile', 'profileEnd', 'dirxml', 'assert', 'count', 'markTimeline', 'timeStamp', 'clear'];

        methods.forEach(method => {
            console[method] = noop;
        });

        // Override toString to prevent detection
        console.toString = () => '[object Console]';
    }
};

