/**
 * Disable common developer tools shortcuts
 */
export const disableDevToolsShortcuts = () => {
    if (process.env.NODE_ENV === 'production') {
        document.addEventListener('keydown', (e) => {
            // F12
            if (e.keyCode === 123) {
                e.preventDefault();
                return false;
            }

            // Ctrl+Shift+I (Windows/Linux) or Cmd+Option+I (Mac)
            if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.keyCode === 73) {
                e.preventDefault();
                return false;
            }

            // Ctrl+Shift+J (Windows/Linux) or Cmd+Option+J (Mac)
            if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.keyCode === 74) {
                e.preventDefault();
                return false;
            }

            // Ctrl+U (View Source)
            if ((e.ctrlKey || e.metaKey) && e.keyCode === 85) {
                e.preventDefault();
                return false;
            }

            // Ctrl+S (Save Page)
            if ((e.ctrlKey || e.metaKey) && e.keyCode === 83) {
                e.preventDefault();
                return false;
            }
        });
    }
};

/**
 * Detect if DevTools is open
 * This is a heuristic and can be bypassed
 */
export const detectDevTools = () => {
    if (process.env.NODE_ENV === 'production') {
        const element = new Image();
        let isOpen = false;

        Object.defineProperty(element, 'id', {
            get: function () {
                isOpen = true;
                return 'devtools-detector';
            }
        });

        setInterval(() => {
            isOpen = false;
            console.log(element);

            if (isOpen) {
                // DevTools detected - you could redirect or take action
                // For now, just clear the page
                document.body.innerHTML = '';
            }
        }, 1000);
    }
};

/**
 * Initialize all security measures
 * Call this in your App component's useEffect
 */
export const initializeSecurity = () => {
    disableConsoleInProduction();
    // disableRightClick(); // Right-click restriction disabled
    disableDevToolsShortcuts();
    // Uncomment if you want to detect DevTools (more aggressive)
    // detectDevTools();
};

export default {
    initializeSecurity,
    disableConsoleInProduction,
    disableRightClick,
    disableDevToolsShortcuts,
    detectDevTools
};
