
import "./sidebar.css";
import { NavLink, useLocation, useNavigate } from "react-router-dom";
import { UserOutlined } from '@ant-design/icons';
import { BiLogOutCircle } from "react-icons/bi";
import Logo from "../../assest/chat/logoicon.png";
import routes from "./SideBarRoute";
import { Avatar, Badge, Button, List, Menu, Skeleton } from "antd";
import { useAuth } from "../../authentication/context/authContext";
import { useCurrentUser } from "../../authentication/context/userContext";
import { useScreen } from "../../authentication/context/AuthScreen";

const SidebarContent = ({ setDrawerOpen }) => {
    const { screenWidth } = useScreen();
    const { role, permissions, logout, branchData } = useAuth()
    const navigate = useNavigate();
    const location = useLocation();
    const { user } = useCurrentUser()
    const isMobile = screenWidth < 768;

    const filterRoutesByPermissions = (routeList = routes) => {
        return routeList.reduce((acc, route) => {
            const filteredChildren = route.children
                ? filterRoutesByPermissions(route.children)
                : [];
            const hasPermission = !route.permission || permissions?.includes(route.permission);

            if (filteredChildren.length) {
                acc.push({ ...route, children: filteredChildren });
                return acc;
            }

            if (hasPermission) {
                acc.push(route);
            }

            return acc;
        }, []);
    };

    const filteredRoutes = role === "BranchAdmin" ? routes : filterRoutesByPermissions();

    const getOpenKeys = (routeList, pathname) => {
        const openKeys = [];

        routeList.forEach((route) => {
            if (route.children?.some((child) => child.path === pathname)) {
                openKeys.push(String(route.key));
            }
        });

        return openKeys;
    };

    const renderMenuItems = (routeList) =>
        routeList.map((route) =>
            route.children?.length ? (
                <Menu.SubMenu
                    key={String(route.key)}
                    icon={<span className="side_menu_icon">{route.icons}</span>}
                    title={route.label}
                >
                    {renderMenuItems(route.children)}
                </Menu.SubMenu>
            ) : (
                <Menu.Item
                    key={route.path}
                    icon={route.icons ? <span className="side_menu_icon">{route.icons}</span> : null}
                >
                    <NavLink
                        to={route.path}
                        onClick={() => setDrawerOpen && setDrawerOpen(false)}
                    >
                        {route.label}
                    </NavLink>
                </Menu.Item>
            )
        );

    return (
        <div className="sidebar_container" style={{ height: isMobile ? '94vh' : '100vh' }}>
            <div className="side_log" onClick={() => navigate("/dashboard")}>
                <div className="side_logo_card">
                    <img src={Logo} alt="ONBKD logo" className="side_logo_img" />
                </div>
            </div>
            <div className="sidebar_branch_card">
                <span className="sidebar_branch_label">Current Branch</span>
                <p>{branchData?.branchName || "Branch"}</p>
                {branchData?.branchCode && <strong>{branchData.branchCode}</strong>}
            </div>
            <div className="show_profile">
                <List className="px-2" itemLayout="horizontal">
                    <List.Item >
                        <List.Item.Meta
                            avatar={
                                <Badge status="success">
                                    <Avatar size="large" icon={<UserOutlined />} />
                                </Badge>
                            }
                            title={
                                <div className="item_title">
                                    <p>{user?.fullName}</p>
                                </div>
                            }
                            description={
                                <div className="order_datas">
                                    <p>{user?.email}</p>
                                </div>
                            }
                        />
                    </List.Item>
                </List>
            </div>

            <div className="menu_scroll">
                <Menu
                    theme="light"
                    mode="inline"
                    selectedKeys={[location.pathname]}
                    defaultOpenKeys={getOpenKeys(filteredRoutes, location.pathname)}
                >
                    {!filteredRoutes ?
                        <Skeleton active />
                        :
                        renderMenuItems(filteredRoutes)
                    }
                </Menu>
            </div>

            <div className="logut_btn">
                <Button
                    type="primary"
                    icon={<BiLogOutCircle />}
                    danger
                    onClick={() => logout()}
                    block
                >
                    Logout
                </Button>
            </div>
        </div>
    );
};

export default SidebarContent;
