export const getSlotDelayColor = (status) => {
  switch (status) {
    case "DELAYED":
      return "red";
    case "SLOT_STARTED":
      return "gold";
    case "ON_TIME":
      return "green";
    default:
      return "default";
  }
};

export const getSlotDelayLabel = (record) => record?.slotDelayLabel || "--";

export const getSlotDelayRowClassName = (record) => {
  if (record?.slotDelayStatus === "DELAYED") {
    return "delayed-delivery-row";
  }
  if (record?.slotDelayStatus === "SLOT_STARTED") {
    return "slot-started-delivery-row";
  }
  return "";
};
